local dialogues = {}
dialogues.npcs = {
    ["I'rk"] = {
        ["Hi, human."] = "Hola, humano.",
        ["Hi, ogre."] = "Hola, ogro.",
        ["How are you today, little ogre?"] = "¿Cómo estás hoy, pequeño ogro?",
        ["*Dialogue 1:*"] = "*Diálogo 1:*",
        ["Can I have some shiny pretties, human?"] = "¿Puedo tener algunas bellezas brillantes, humano?",
        ["What makes you think I'd give my shiny pretties to you?"] = "¿Qué te hace pensar que te daría mis bellezas brillantes?",
        ["That skinny lady at de bank say visitors bring lots of shiny pretties with them when they come visit Oo'glog. Me want my share!"] = "Esa señora flaca del banco dice que los visitantes traen consigo muchas bellezas brillantes cuando vienen a visitar Oo'glog. ¡Quiero mi parte!",
        ["Ah, you see, I've given your share to that skinny lady at the bank; you'll have to ask her for it yourself. Make sure you ask really loudly and growl at her every time she uses a word you don't understand, okay?"] = "Ah, verás, le he dado tu parte a esa señora flaca del banco; Tendrás que pedírselo tú mismo. Asegúrate de preguntarle en voz muy alta y gruñirle cada vez que use una palabra que no entiendes, ¿de acuerdo?",
        ["Yay! Thanks human. I'm gonna get my shiny pretties, even if I have to growl all afternoon."] = "¡Sí! Gracias humano. Voy a conseguir mis bellezas brillantes, incluso si tengo que gruñir toda la tarde.",
        ["*Dialogue 2:*"] = "*Diálogo 2:*",
        ["Fine, please and thank you very much, madam sir!"] = "¡Bien, por favor y muchas gracias señora señor!",
        ["You're very...polite."] = "Eres muy... educado.",
        ["Me know! Me practising! Balnea say I can have job in Customer Rations when I grow up if me polite enough."] = "¡Lo sé! ¡Yo practicando! Balnea dice que puedo tener trabajo en Customer Rations cuando sea mayor si soy lo suficientemente educado.",
        ["Don't you mean 'Customer Relations'?"] = "¿No te refieres a 'Relaciones Customer'?",
        ["Blechh! Dat not sound near as tasty as 'Customer Rations'. Me not sure me want de job after all."] = "¡Blechh! Eso no suena tan sabroso como 'Customer Rations'. Después de todo, no estoy seguro de querer el trabajo.",
        ["*Dialogue 3:*"] = "*Diálogo 3:*",
        ["Hey, human. What did you bring me?"] = "Hola, humano. ¿Qué me trajiste?",
        ["Hmm, let me think carefully about this. Oh, yes, I remember, now! Absolutely nothing."] = "Hmm, déjame pensar detenidamente en esto. ¡Oh, sí, ahora lo recuerdo! Absolutamente nada.",
        ["Aw, shucks."] = "Ay, caray.",
        ["*Dialogue 4:*"] = "*Diálogo 4:*",
        ["How does it feel to be so puny wee small, human?"] = "¿Cómo se siente ser tan pequeño, humano?",
        ["Oh, I dunno. How does it feel to be so incredibly dense?"] = "Oh, no lo sé. ¿Cómo se siente ser tan increíblemente denso?",
        ["Uhh...what dat s'pposed to mean?"] = "Uhh... ¿qué se supone que significa eso?",
        ["Never mind."] = "No importa.",
        ["*Dialogue 5:*"] = "*Diálogo 5:*",
        ["Me like pie!"] = "¡Me gusta el pastel!",
        ["Doesn't everyone?"] = "¿No es así para todos?",
        ["Pie! Pie! Pie! Pie! Pie!"] = "¡Pastel! ¡Pastel! ¡Pastel! ¡Pastel! ¡Pastel!",
        ["Yes, dear, pie."] = "Sí, querido, pastel.",
        ["*Dialogue 6:*"] = "*Diálogo 6:*",
        ["Me wanna go visit Fycie 'n Bugs!"] = "¡Quiero ir a visitar Fycie y Bugs!",
        ["Yes, they're both delightful individuals."] = "Sí, ambos son personas encantadoras.",
        ["Will you take me to see dem, human?"] = "¿Me llevarás a verlos, humano?",
        ["Didn't your mother ever teach you not to talk to strangers?"] = "¿Tu madre nunca te enseñó a no hablar con extraños?",
        ["*Dialogue 7:*"] = "*Diálogo 7:*",
        ["Me wants CHOMPY for dinner!"] = "¡Quiero CHOMPY para cenar!",
        ["Me hopes you GETS chompy for dinner!"] = "¡Espero que te pongas nervioso para la cena!",
        ["What you talk weird like dat for, human? You sound silly!"] = "¿Por qué hablas así de raro, humano? ¡Suenas tonto!",
        ["*Dialogue 8:*"] = "*Diálogo 8:*",
        ["Not so very good. Me just drop me lunch in de pool."] = "No muy bien. Simplemente déjame el almuerzo en la piscina.",
        ["Ew...I think I can see it floating over there."] = "Ew... Creo que puedo verlo flotando por allí.",
        ["Oh, thank you human! I have it as a snack next time I go for swim!"] = "¡Oh, gracias humano! ¡Lo tomaré como refrigerio la próxima vez que vaya a nadar!",
        ["*Dialogue 9:*"] = "*Diálogo 9:*",
        ["You very cute, little creature. Me want to have a human as a pet. What you doing, human? You busy? You want be my little pet human creature?"] = "Eres una pequeña criatura muy linda. Quiero tener un humano como mascota. ¿Qué estás haciendo, humano? ¿Estas ocupado? ¿Quieres ser mi pequeña criatura humana mascota?",
        ["Uh...I think I'm busy at the moment."] = "Uh... Creo que estoy ocupado en este momento.",
        ["Pwetty please?"] = "¿Pequeño, por favor?",
        ["Look, sorry to disappoint, but this isn't going to happen."] = "Mira, lamento decepcionarte, pero esto no va a suceder.",
        ["Aw, you no fun, human."] = "Ay, no eres divertido, humano.",
        ["Select an Option"] = "Selecciona una opción",
        ["How are you today?"] = "¿Cómo estás hoy?",
        ["Can you tell me about this mud pool?"] = "¿Puedes hablarme de esta piscina de barro?",
        ["Dat my favourite pool, dat is! It nice and sticky mud, very warm and comfy. It de muddiest mud around!"] = "¡Ésa es mi piscina favorita! Es un barro agradable y pegajoso, muy cálido y cómodo. ¡Es el barro más fangoso que existe!",
        ["The muddiest mud?"] = "¿El barro más fangoso?",
        ["Plus, if you lie in de mud for a while, it much easier to sneaky-sneak hunt de creatures. De mud, it cover your awful human stink!"] = "Además, si te quedas en el barro por un tiempo, será mucho más fácil cazar furtivamente a las criaturas. ¡De barro, cubre tu horrible hedor humano!",
        ["Huh! I'll have to try that sometime."] = "¡Eh! Tendré que intentarlo alguna vez.",
    },
    ["Ian (cape merchant)"] = {
        ["Hello there! Are you interested in buying one of my special team capes?"] = "¡Hola! ¿Estás interesado en comprar una de mis capas especiales del equipo?",
        ["What do team capes do?"] = "¿Qué hacen las capas del equipo?",
        ["If you and your friends all wear the same team cape, you'll be less likely to attack your friends by accident, and you'll find it easier to attack everyone else."] = "Si todos tus amigos y tú usan la misma capa del equipo, será menos probable que ataques a tus amigos por accidente y te resultará más fácil atacar a todos los demás.",
        ["They're very useful in the Wilderness and other player-vs-player combat areas where you might come across friends you don't want to harm. So would you like to buy one?"] = "Son muy útiles en Wilderness y otras áreas de combate jugador contra jugador donde puedes encontrarte con amigos a los que no quieres hacer daño. Entonces ¿te gustaría comprar uno?",
        ["Yes please!"] = "¡Sí, por favor!",
        ["I'd like to access my bank please."] = "Me gustaría acceder a mi banco por favor.",
        ["No thanks."] = "No gracias.",
    },
    ["Ian"] = {
        ["Behind the Scenes is such a strange place!"] = "¡Detrás de escena hay un lugar tan extraño!",
        ["Choose an option:"] = "Elige una opción:",
        ["I love these cosmetic quest rewards."] = "Me encantan estas recompensas de misiones cosméticas.",
        ["They're great aren't they? Which one is your favourite?"] = "Son geniales, ¿no? ¿Cuál es tu favorito?",
        ["Select an Option"] = "Selecciona una opción",
        ["The Brassica godsword."] = "La espada divina Brassica.",
        ["Cool! Glad you like them."] = "¡Genial! Me alegra que te gusten.",
        ["The cabbagemancer outfit."] = "El traje de repollo.",
        ["The cabbage pet."] = "La mascota de la col.",
        ["Can you return me to the surface?"] = "¿Puedes devolverme a la superficie?",
        ["You should talk to Andrew about that. I think he knows a teleport spell."] = "Deberías hablar con Andrew sobre eso. Creo que conoce un hechizo de teletransporte.",
        ["Goodbye."] = "Adiós.",
        ["Hello, Gower brothers! It's great to see you. I'm feeling nostalgic."] = "¡Hola hermanos Gower! Es genial verte. Siento nostalgia.",
        ["Nostalgia is all well and good, but don't get lost in it. Visit the past, but also look to the future!"] = "La nostalgia está muy bien, pero no te pierdas en ella. ¡Visite el pasado, pero también mire hacia el futuro!",
        ["This world was once great! For some it has remained great! And for others still, it shall be great once again!"] = "¡Este mundo alguna vez fue grandioso! ¡Para algunos ha seguido siendo genial! Y para otros aún, ¡será genial una vez más!",
        ["You're always welcome here where we're at...or you can go old school...or, hey, even visit some wild dragons in the dragon wilds..."] = "Siempre eres bienvenido aquí donde estamos... o puedes ir a la vieja escuela... o, oye, incluso visitar algunos dragones salvajes en Dragon Wilds...",
        ["Gower Power"] = "poder gower",
        ["Talk to any of the Gower brothers at their farm south of Varrock, or, next to the Life altar."] = "Habla con cualquiera de los hermanos Gower en su granja al sur de Varrock o junto al altar de la Vida.",
        ["Yeah! I'm with you!"] = "¡Sí! ¡Estoy contigo!",
        ["Looks like I've completed everything. I'd better go and see Hans about that reward!"] = "Parece que he completado todo. ¡Será mejor que vaya a ver a Hans sobre esa recompensa!",
    },
    ["Ianto"] = {
        ["Hi there!"] = "¡Hola!",
        ["Hi, Ianto."] = "Hola, Ianto.",
        ["I was doing some cleaning and found some things which I'd like you to have!"] = "¡Estaba limpiando un poco y encontré algunas cosas que me gustaría que tuvieras!",
        ["Oh! Really!?"] = "¡Oh! ¿¡En realidad!?",
        ["Yeah! Got some gnomeballer's gear, a large gnomeball, some coronets, a godless ceremonial set and an astromancer set!"] = "¡Sí! ¡Conseguí equipo de gnomobola, una gran bola de gnomo, algunas coronas, un conjunto ceremonial impío y un conjunto de astromante!",
        ["Thanks Ianto!"] = "¡Gracias Ianto!",
        ["The makers of the world have won an award! Have a cracker, with our compliments!"] = "¡Los creadores del mundo han ganado un premio! ¡Toma una galleta, con nuestras felicitaciones!",
        ["Would you like a golden cracker?"] = "¿Quieres una galleta dorada?",
        ["Yes."] = "Sí.",
        ["[Ianto gives you a golden cracker.]"] = "[Ianto te regala una galleta dorada.]",
        ["Thanks, Ianto!"] = "¡Gracias, Ianto!",
        ["Pull it with another person and you'll get a special surprise!"] = "¡Tráelo con otra persona y obtendrás una sorpresa especial!",
        ["Feel free to collect it later!"] = "¡Siéntete libre de recogerlo más tarde!",
        ["Now, what can I do for you? Want to see my spinning plates or kites? Want to check out my range of party items? Or did you want an item back?"] = "Ahora, ¿qué puedo hacer por ti? ¿Quieres ver mis platos giratorios o cometas? ¿Quieres ver mi gama de artículos para fiestas? ¿O querías recuperar un artículo?",
        ["Select an Option"] = "Selecciona una opción",
        ["Spinning plates?"] = "¿Platos giratorios?",
        ["There was a mix-up some years back with a man who lives in Draynor - something about 'dragon plates' being confused for armour."] = "Hubo una confusión hace algunos años con un hombre que vive en Draynor: algo acerca de que las 'placas de dragón' se confundían con una armadura.",
        ["Wow, a kite!"] = "¡Guau, una cometa!",
        ["You're not the first to say that..."] = "No eres el primero en decir eso...",
        ["Can I have one, please?"] = "¿Me das uno, por favor?",
        ["Well, I suppose I did order more than I need... It's yours for the bargain price of 100 coins."] = "Bueno, supongo que pedí más de lo que necesito... Es tuyo por el precio de ganga de 100 coins.",
        ["That's a bargain! I'll take one."] = "¡Eso es una ganga! Tomaré uno.",
        ["No, thanks, I don't want one."] = "No, gracias, no quiero uno.",
        ["Party items, you say?"] = "¿Artículos de fiesta, dices?",
        ["Yes, I have all sorts of stuff - confetti, bubble markers, fireworks, firecrackers and some mugs! Take a look!"] = "Sí, tengo todo tipo de cosas: confeti, marcadores de burbujas, fuegos artificiales, petardos y algunas tazas. ¡Echa un vistazo!",
        ["I'd like to check my items, please."] = "Me gustaría revisar mis artículos, por favor.",
        ["Sure thing, let me just see what you're missing."] = "Claro, déjame ver lo que te estás perdiendo.",
        ["Can you check my bank for items?"] = "¿Puedes comprobar si hay artículos en mi banco?",
        ["Sure thing, let me see what I can take off your hands."] = "Claro, déjame ver qué puedo quitarte de las manos.",
        ["I'll look through items that I will hold onto, items that could go into a costume room in your house and junk items."] = "Revisaré los artículos que guardaré, artículos que podrían ir a la sala de disfraces de tu casa y artículos basura.",
        ["I'd like to redeem an item code, please."] = "Me gustaría canjear un código de artículo, por favor.",
        ["Of course. Here you go."] = "Por supuesto. Aquí tienes.",
    },
    ["Ichabod Russ"] = {
        ["None of you knew Ichabod like he wanted you to, and he won't be liking how you remember him, neither. He always felt like he had a big old keg of greatness in him, that boy, and nothing we could do would shake it out of him. Boy got the notion that he was born to kill, running round town with a pot on his head and stabbing rats. Tried to get him into farming like his Pappy, of course, but the boy never learned."] = "Ninguno de ustedes conocía a Ichabod como él quería, y a él tampoco le gustará cómo lo recuerdan. Siempre sintió como si tuviera un gran barril de grandeza dentro de él, ese niño, y nada de lo que pudiéramos hacer podría sacárselo de encima. El niño tuvo la idea de que había nacido para matar, corriendo por la ciudad con una olla en la cabeza y apuñalando ratas. Intentó que se dedicara a la agricultura como su papá, por supuesto, pero el niño nunca aprendió.",
        ["Then he got into visitin' the edge of the Wilderness. Cursed if I would let a Russ start into killing, so I started taking away his allowance. He'd mumble some nonsense about the combat triangle, that he'd beat it, and the rest you all know. Walked into Varrock market square. Said he would prove his theory, and pulled on a mage outfit he'd made out of sacks. Wild-eyed look on his face, the boy sprinted into the Wilderness. Went as fast as I could after the boy, but I couldn't get in to grab him. Boy didn't last the morning."] = "Luego empezó a visitar el borde del Wilderness. Me maldecía si dejaba que un Russ comenzara a matar, así que comencé a quitarle su asignación. Murmuraba algunas tonterías sobre el combat triangle, que lo había superado, y el resto ya lo sabéis. Entré en la plaza del mercado Varrock. Dijo que probaría su teoría y se puso un traje de mago que había hecho con sacos. Con una mirada desorbitada en su rostro, el niño corrió hacia el Wilderness. Fui lo más rápido que pude tras el niño, pero no pude entrar para agarrarlo. El chico no duró toda la mañana.",
        ["So now you're here in the ground, Ichabod, you fool. Maybe that'll learn you."] = "Así que ahora estás aquí bajo tierra, Ichabod, tonto. Quizás eso te ayude a aprender.",
        ["Pappy Russ, eulogy for Ichabod Russ's funeral"] = "Pappy Russ, elogio del funeral de Ichabod Russ",
    },
    ["Ichi"] = {
        ["Hello, weary traveller. Welcome to Cyclosis!"] = "Hola, viajero cansado. ¡Bienvenidos a Ciclosis!",
        ["I am the khan here.<br/>I am Ichi."] = "Soy el khan aquí.<br/>Soy Ichi.",
        ["Have you tried using any ointments?"] = "¿Has probado a usar algún ungüento?",
        ["Haha! You westerners and your jokes."] = "¡Jaja! Ustedes los occidentales y sus chistes.",
        ["You will find that the people of Cyclosis are friendly and kind. Please, make yourself at home."] = "Descubrirás que la gente de Cyclosis es amigable y amable. Por favor, siéntete como en casa.",
        ["Ekahi is back to normal! We slew a jiangshi, who was the source of all the recent zombiism, which removed the curse from those afflicted."] = "¡Ekahi ha vuelto a la normalidad! Matamos a un jiangshi, que fue la fuente de todo el zombiismo reciente, que eliminó la maldición de los afectados.",
        ["Thank you for everything you have done for him and my people."] = "Gracias por todo lo que has hecho por él y mi gente.",
    },
    ["Iconis"] = {
        ["Good day! I'm afraid you can't use the booth's services on a non-members world. Film costs a lot you know!"] = "¡Buenos días! Me temo que no puedes utilizar los servicios del stand en un mundo que no es miembro. ¡La película cuesta mucho, sabes!",
        ["Good day! Would you like to have your picture taken?"] = "¡Buenos días! ¿Quieres que te tomen una foto?",
        ["Select an Option"] = "Selecciona una opción",
        ["Yes, please!"] = "¡Sí, por favor!",
        ["Yes please!"] = "¡Sí, por favor!",
        ["Just enter the tent, adjust your clothing and press the 'Take picture' button when you're ready!"] = "¡Simplemente ingresa a la tienda, ajusta tu ropa y presiona el botón \"Tomar foto\" cuando estés listo!",
        ["Thank you!"] = "¡Gracias!",
        ["Sorry, you've only recently had your picture taken. You'll be able to have it taken again in [time remaining]."] = "Lo sentimos, te han tomado una foto recientemente. Podrás volver a tomarlo en [time remaining].",
        ["No, thank you."] = "No, gracias.",
        ["As you wish."] = "Como desees.",
        ["What are the pictures for?"] = "¿Para qué son las fotos?",
        ["The imp sends them to a mysterious web that can be found beyond this material plane. From there, they can be viewed by other adventurers to put a face to the name."] = "El diablillo los envía a una misteriosa red que se puede encontrar más allá de este plano material. Desde allí, otros aventureros podrán verlos para ponerle cara al nombre.",
        ["For example, they'll be used to display the faces of adventurers with high skill training accomplishments."] = "Por ejemplo, se utilizarán para mostrar los rostros de aventureros con grandes logros en el entrenamiento de habilidades.",
        ["How does it work?"] = "¿Cómo funciona?",
        ["Is it safe?"] = "¿Es seguro?",
        ["There's an imp in there who uses a spell to take your picture. He can only do it once every 2 hours at the moment, though, and it will take some time to process the picture. There's a lot of demand, you see."] = "Hay un diablillo ahí dentro que usa un hechizo para tomarte una foto. Sin embargo, por el momento sólo puede hacerlo una vez cada 2 horas y le llevará algún tiempo procesar la imagen. Hay mucha demanda, ¿ves?",
        ["Why an imp?"] = "¿Por qué un diablillo?",
        ["Ah, good question! See, I've experimented with lots of ways of making accurate visual representations of things in a magical way. Most recently, I've been trying to modify scrying orbs to get a still picture."] = "¡Ah, buena pregunta! Mira, he experimentado con muchas formas de hacer representaciones visuales precisas de las cosas de una manera mágica. Más recientemente, he estado intentando modificar los orbes de visión para obtener una imagen fija.",
        ["Because of their shape, though, they always made the subject look fat! So I came up with a scrying cube, but that made things look even worse!"] = "Sin embargo, debido a su forma, ¡siempre hacían que el sujeto pareciera gordo! Entonces se me ocurrió un cubo de visión, ¡pero eso hizo que las cosas parecieran aún peor!",
        ["So what did you do?"] = "Entonces, ¿qué hiciste?",
        ["I tweaked and tweaked the shape until I got a decent picture - took me weeks to make - but then this imp just teleported in from out of nowhere right next to it. My scrying device fell on the floor and smashed."] = "Modifiqué y modifiqué la forma hasta que obtuve una imagen decente (me tomó semanas hacerla), pero luego este diablillo se teletransportó de la nada justo al lado. Mi dispositivo de visión cayó al suelo y se hizo añicos.",
        ["Oh, no!"] = "¡Oh, no!",
        ["Imps take pictures?"] = "¿Los diablillos toman fotografías?",
        ["Yes. He wouldn't reveal the exact working of the spell to me, or even why they do it, but the result is very convincing."] = "Sí. No me reveló el funcionamiento exacto del hechizo, ni siquiera por qué lo hacen, pero el resultado es muy convincente.",
        ["That's all, thank you."] = "Eso es todo, gracias.",
        ["That's unfortunate."] = "Eso es desafortunado.",
        ["But are my belongings safe?"] = "¿Pero están seguras mis pertenencias?",
        ["Totally! I've got a few runes, orbs and trinkets in there to ensure of that."] = "¡Totalmente! Tengo algunas runas, orbes y baratijas para garantizarlo.",
        ["You're welcome!"] = "¡De nada!",
    },
    ["Icthlarin"] = {
        ["Greetings, hero."] = "Saludos, héroe.",
        ["I need to get to the other side of the bridge."] = "Necesito llegar al otro lado del puente.",
        ["Do you wish to be teleported to the southern bank?"] = "¿Quieres ser teletransportado al banco sur?",
        ["Yes, send me back."] = "Sí, envíame de vuelta.",
        ["No, I'll stay here."] = "No, me quedaré aquí.",
        ["Ask about becoming the God of the Underworld."] = "Pregunte acerca de convertirse en el Dios del inframundo.",
        ["This is not a title I ever wished to possess, mortal. It was thrust upon me by my father, Tumeken. Like a child I resisted. It was a different time, and I was yet to learn the weight of responsibility. Amascut and I, we had displeased our father. A memory that I do not wish to recount, though it is never far from my mind. Tumeken's rage burned fiercely. He scorned us for our failings and sent us to guard the Underworld so that we would learn the error of our ways. It is here, and in the events that transpired since, that I have learned the importance of sacrifice. My father sought to teach me of responsibility, of which I have learned tenfold. Amascut's descent into madness has left much me with much on my shoulders. But the weight I carry is my own. My deeds have brought me here…  and my deeds will carry me forward."] = "Este no es un título que alguna vez deseé poseer, mortal. Me lo impuso mi padre, Tumeken. Como un niño me resistí. Era una época diferente y todavía tenía que aprender el peso de la responsabilidad. Amascut y yo habíamos disgustado a nuestro padre. Un recuerdo que no deseo contar, aunque nunca está lejos de mi mente. La ira de Tumeken ardió ferozmente. Nos despreció por nuestros errores y nos envió a proteger el inframundo para que aprendiéramos el error de nuestros caminos. Es aquí, y en los acontecimientos que sucedieron desde entonces, que aprendí la importancia del sacrificio. Mi padre buscó enseñarme sobre la responsabilidad, de la cual he aprendido diez veces más. El descenso de Amascut a la locura me ha dejado con muchas cosas sobre mis hombros. Pero el peso que llevo es mío. Mis obras me han traído aquí... y mis obras me llevarán hacia adelante.",
        ["Ask about Amascut."] = "Pregunta por Amascut.",
        ["The Devourer is not my sister, mortal. Amascut is not herself. When our father gave his life to save the Kharid it changed her. He left all his responsibilities to me, as punishment for the decisions I had made. Amascut saw this not as my punishment, but as her failing. She never believed she had earned his forgiveness after being sent to the gates of the Underworld. My sister had been left with nothing. The pain in her heart drove her into the darkness from which she was never to return. Perhaps if I had done things differently… If I had not left… No, hope is not lost. I can still bring her back, Player. I can still save my sister. First, though, we must defeat her here."] = "La Devoradora no es mi hermana, mortal. Amascut no es ella misma. Cuando nuestro padre dio su vida para salvar a Kharid, eso la cambió. Me dejó todas sus responsabilidades, como castigo por las decisiones que había tomado. Amascut vio esto no como mi castigo, sino como su fracaso. Ella nunca creyó que se había ganado su perdón después de ser enviada a las puertas del Inframundo. Mi hermana se había quedado sin nada. El dolor en su corazón la llevó a la oscuridad de la que nunca volvería. Quizás si hubiera hecho las cosas de otra manera… Si no me hubiera ido… No, la esperanza no se pierde. Todavía puedo traerla de vuelta, Player. Todavía puedo salvar a mi hermana. Pero primero debemos derrotarla aquí.",
        ["Ask about Tumeken."] = "Pregunta por Tumekén.",
        ["My father… He taught me all I know of humility and selflessness. I only wish I could embodied them more while he was still of this world. It was my decision to bring the Mahjarrat to Gielinor that ultimately sealed my father's fate. We were on the cusp of defeat. I sought to earn his respect by doing the impossible: winning the war. When our new allies helped us throw the Zarosian forces back I went to Tumeken expecting recognition. Alas, I was only to be greeted by disappointment. I was filled with anger. Why would I still not afford me the respect I deserved? Why did he still withhold his forgiveness? But he simply saw what I did not. The Mahjarrat would soon betray us, the sweet victory would turn to bitter defeat in our mouths. When all hope had faded and the Kharid finally seemed lost, my father stepped forward. I can still hear my sister's screams as we watched Tumeken stride out into the centre of the battlefield. I was filled with immense pride as a bright light engulfed us. Our father was gone and with him most of the military forces - friend or foe. The energy radiated across the Kharid, destroying most flora and fauna. It was my actions that caused all of this. The obliteration of the Kharid. My sister's descent into madness. My father's death. But his memory survives… and I will live up to it. I will make amends for my mistakes, mortal. I will atone."] = "Mi padre… Él me enseñó todo lo que sé sobre la humildad y el altruismo. Sólo desearía poder encarnarlos más mientras él todavía estaba en este mundo. Fue mi decisión de traer Mahjarrat a Gielinor lo que finalmente selló el destino de mi padre. Estábamos al borde de la derrota. Intenté ganarme su respeto haciendo lo imposible: ganar la guerra. Cuando nuestros nuevos aliados nos ayudaron a hacer retroceder a las fuerzas zarosianas, fui a Tumeken esperando reconocimiento. Por desgracia, sólo me encontré con una decepción. Me llené de ira. ¿Por qué todavía no me daría el respeto que merecía? ¿Por qué todavía retuvo su perdón? Pero él simplemente vio lo que yo no vi. El Mahjarrat pronto nos traicionaría, la dulce victoria se convertiría en una amarga derrota en nuestras bocas. Cuando toda esperanza se desvaneció y el Kharid finalmente pareció perdido, mi padre dio un paso adelante. Todavía puedo escuchar los gritos de mi hermana mientras veíamos a Tumeken avanzar hacia el centro del campo de batalla. Me llené de inmenso orgullo cuando una luz brillante nos envolvió. Nuestro padre se había ido y con él la mayoría de las fuerzas militares, amigas o enemigas. La energía irradió a través del Kharid, destruyendo la mayor parte de la flora y la fauna. Fueron mis acciones las que causaron todo esto. La destrucción de los Kharid. El descenso de mi hermana a la locura. La muerte de mi padre. Pero su recuerdo sobrevive... y estaré a la altura. Enmendaré mis errores, mortal. Yo expiaré.",
        ["Goodbye."] = "Adiós.",
        ["How are you doing?"] = "¿Cómo estás?",
        ["I am myself again, which is a good thing. In that maze I was not. I was...losing myself."] = "Vuelvo a ser yo mismo, lo cual es bueno. En ese laberinto yo no estaba. Estaba... perdiéndome.",
        ["It was an experience  of indescribable horror. To find myself losing my ability to remember...to even think."] = "Fue una experiencia de horror indescriptible. Encontrarme perdiendo mi capacidad de recordar... incluso de pensar.",
        ["But it is done now and I am Icthlarin again. I must push such feelings aside, because I have my duties."] = "Pero ya está hecho y soy Icthlarin nuevamente. Debo dejar esos sentimientos a un lado, porque tengo mis deberes.",
        ["Why did you become animalistic?"] = "¿Por qué te volviste animalista?",
        ["My mother and father, Elidinis and Tumeken, lived among their followers, not above them. They wanted to be as they were."] = "Mi madre y mi padre, Elidinis y Tumeken, vivían entre sus seguidores, no por encima de ellos. Querían ser como eran.",
        ["But there was one thing that, try as they might, they could never have. A family."] = "Pero había una cosa que, por mucho que lo intentaran, nunca podrían lograr. Una familia.",
        ["At least, not what mortals would consider to be a family."] = "Al menos, no lo que los mortales considerarían una familia.",
        ["As I was told, they each took a piece of themselves, a spark of their divine power, and combined them into something new."] = "Como me dijeron, cada uno tomó una parte de sí mismo, una chispa de su poder divino, y los combinó en algo nuevo.",
        ["Something formed of the both of them. They then placed this energy into the two beings most akin to their family."] = "Algo se formó entre ambos. Luego colocaron esta energía en los dos seres más afines a su familia.",
        ["I was their pet dog. Not the most esteemed of beginnings, but it is not one I am shamed of."] = "Yo era su perro mascota. No es el comienzo más estimado, pero tampoco es uno del que me avergüence.",
        ["My sister, Amascut, began similar humble beginnings, as their beloved cat. Though she has long fallen away from that person."] = "Mi hermana, Amascut, tuvo comienzos humildes similares a los de su amado gato. Aunque hace tiempo que se alejó de esa persona.",
        ["So when the labyrinth robbed me of my divine nature, I began to revert back to that simple creature."] = "Entonces, cuando el laberinto me robó mi naturaleza divina, comencé a volver a esa simple criatura.",
        ["I suppose my origins explain why I find herding souls through the underworld so...satisfying."] = "Supongo que mis orígenes explican por qué me resulta tan... satisfactorio pastorear almas por el inframundo.",
        ["How did the dragonkin destroy the stone?"] = "¿Cómo destruyeron los dragonantes la piedra?",
        ["I am unsure my friend. I am hardly an expert on the dragonkin."] = "No estoy seguro, amigo. No soy un experto en dragonantes.",
        ["But we were in the Heart of Gielinor, where the anima of Gielinor flows."] = "Pero estábamos en el Corazón de Gielinor, donde fluye el ánima de Gielinor.",
        ["If they found a way to harness that much energy, to channel it into the stone. I can't imagine even the stone would survive that."] = "Si encontraran una manera de aprovechar tanta energía, canalizarla hacia la piedra. No puedo imaginar que ni siquiera la piedra sobreviviera a eso.",
        ["Icthlarin, to what do I owe this pleasure?"] = "Icthlarin, ¿a qué debo este placer?",
        ["I am here to keep an eye on you."] = "Estoy aquí para vigilarte.",
        ["You're really not a fan of necromancy, are you?"] = "Realmente no eres un fanático de la nigromancia, ¿verdad?",
        ["It is a vile affront to everything I stand for."] = "Es una vil afrenta a todo lo que represento.",
        ["Fret not. Death has informed me of the circumstances. Rasial must be dealt with, and that he has chosen you fills me with hope."] = "No te preocupes. La muerte me ha informado de las circunstancias. Hay que ocuparse de Rasial, y que te haya elegido me llena de esperanza.",
        ["Not me, so much."] = "Yo no, mucho.",
        ["So long as you continue as you have begun, I trust in you to wield this newfound power responsibly, and I have faith that you will ultimately prevail."] = "Mientras continúes como comenzaste, confío en ti para ejercer este nuevo poder de manera responsable y tengo fe en que finalmente prevalecerás.",
        ["Oh, hey, I've got a lantern now too."] = "Oh, oye, ahora también tengo una linterna.",
        ["Ha! So I have seen...and much like my own. Use it to guide, never to cajole, and all will be well."] = "¡Ja! Así lo he visto... y muy parecido al mío. Úselo para guiar, nunca para engatusar, y todo estará bien.",
        ["I shall not linger to watch your entire journey. Only long enough to feel reassured."] = "No me detendré a observar todo tu viaje. Sólo el tiempo suficiente para sentirse tranquilo.",
        ["For now, I can offer you some direction to help maintain you on the right path. Perhaps even offer a reward if that is what it takes."] = "Por ahora, puedo ofrecerte algunas indicaciones para ayudarte a mantenerte en el camino correcto. Quizás incluso ofrezca una recompensa si eso es lo que hace falta.",
        ["Choose an option:"] = "Elige una opción:",
        ["To what do I owe this pleasure?"] = "¿A qué debo este placer?",
        ["Show me the easy Underworld tasks I can do."] = "Muéstrame las tareas fáciles de Underworld que puedo hacer.",
        ["Of course. Here is a collection of tasks that will help you discover more about Necromancy and the City of Um."] = "Por supuesto. Aquí hay una colección de tareas que lo ayudarán a descubrir más sobre Necromancy y City of Um.",
        ["You cannot do that right now."] = "No puedes hacer eso ahora mismo.",
        ["You don't have any rewards to claim!"] = "¡No tienes ninguna recompensa que reclamar!",
        ["I've completed all the tasks in the easy Underworld task set."] = "He completado todas las tareas del sencillo conjunto de tareas de Underworld.",
        ["Well done Player, I've kept some rewards aside for you."] = "Bien hecho Player, he reservado algunas recompensas para ti.",
        ["Lupe has also agreed to provide you with a daily supply of bones for your communion rituals in recognition of your efforts."] = "Lupe también ha aceptado proporcionarte un suministro diario de huesos para tus rituales de comunión en reconocimiento a tus esfuerzos.",
        ["I'm afraid you don't have enough backpack space to claim all your rewards. Speak to me again when you have 2 spaces."] = "Me temo que no tienes suficiente espacio backpack para reclamar todas tus recompensas. Hablame de nuevo cuando tengas 2 espacios.",
        ["[You are given some rewards for completing the easy Underworld task set!]"] = "[¡Recibirás algunas recompensas por completar el sencillo conjunto de tareas de Underworld!]",
        ["There you go, looks like that's everything."] = "Ahí lo tienes, parece que eso es todo.",
        ["I lost the Underworld Grimoire 1 you have me..."] = "Perdí el Grimorio del Inframundo 1, me tienes...",
        ["You don't seem to have any room for a new one, come back to me when you do."] = "Parece que no tienes espacio para uno nuevo, vuelve conmigo cuando lo tengas.",
        ["Lucky for you I have a spare. Take better care of this one."] = "Por suerte para ti, tengo uno de repuesto. Cuida mejor este.",
        ["[You're handed another Underworld Grimoire 1.]"] = "[Te entregan otro Grimorio 1 de Underworld.]",
        ["Ask about the Task System."] = "Pregunta por el Sistema de Tareas.",
        ["Tell me about the Task System."] = "Cuéntame sobre el sistema de tareas.",
        ["Very well: the Achievement System is a collection of deeds you may wish to complete while adventuring around the world."] = "Muy bien: el Sistema de Logros es una colección de hazañas que quizás desees completar mientras viajas por el mundo.",
        ["You can earn special rewards for completing certain achievements; at the very least, each is worth a cash bounty from Explorer Jack in Lumbridge."] = "Puedes ganar recompensas especiales por completar ciertos logros; como mínimo, cada uno vale una recompensa en efectivo de Explorer Jack en Lumbridge.",
        ["Some also give items that will help complete other achievements, and many count as progress towards the set for the area they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otros logros y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
        ["Tell me about the set reward for this locality."] = "Cuéntame sobre la recompensa establecida para esta localidad.",
        ["Tell me about the set reward for this area."] = "Cuéntame sobre la recompensa establecida para esta área.",
        ["For completing the Underworld set, you are presented with the Underworld Grimoire."] = "Por completar el conjunto Underworld, se te presenta el Grimorio de Underworld.",
        ["This book will become increasingly useful with each difficulty level of the set that you complete."] = "Este libro será cada vez más útil con cada nivel de dificultad del conjunto que completes.",
        ["When you are presented with your rewards, you will be told of its uses."] = "Cuando se le presenten sus recompensas, se le informará sobre sus usos.",
        ["You may also see what rewards a set item provides by hovering over the Rewards icon for its corresponding Achievement set in the Achievements interface."] = "También puedes ver qué recompensas proporciona un elemento determinado al pasar el cursor sobre el ícono de Recompensas de su conjunto de logros correspondiente en la interfaz de Logros.",
        ["Can I claim any rewards from you?"] = "¿Puedo reclamar alguna recompensa de usted?",
        ["Sorry, I was just leaving."] = "Lo siento, me estaba yendo.",
        ["How do I claim these rewards?"] = "¿Cómo reclamo estas recompensas?",
        ["How do I claim the rewards?"] = "¿Cómo reclamo las recompensas?",
        ["You need to complete all of the Tasks in a set of a particular difficulty, then you can claim your reward. Some of the Underworld Tasks are straightforward, some will require skill levels, and some might require quests to be started or completed."] = "Debes completar todas las tareas de un conjunto de una dificultad particular y luego podrás reclamar tu recompensa. Algunas de las tareas del inframundo son sencillas, algunas requerirán skill levels y otras pueden requerir que se inicien o completen misiones.",
        ["To claim the Underworld set reward, speak to Frank or myself."] = "Para reclamar la recompensa del conjunto Underworld, habla con Frank o conmigo.",
        ["Could I buy a spare of the reward?"] = "¿Puedo comprar un repuesto de la recompensa?",
        ["Underworld Grimoire 1"] = "Grimorio del inframundo 1",
        ["Underworld Grimoire 1? Yes, but I'm afraid it would cost you 5,000 coins."] = "¿Grimorio del inframundo 1? Sí, pero me temo que te costaría 5.000 coins.",
        ["Purchase another for 5,000 coins?"] = "¿Comprar otro por 5.000 coins?",
        ["Yes"] = "si",
        ["No thanks."] = "No, gracias.",
        ["Underworld Grimoire 2"] = "Grimorio del inframundo 2",
        ["Underworld Grimoire 2? Yes, but I'm afraid it would cost you 10,000 coins."] = "¿Grimorio del inframundo 2? Sí, pero me temo que te costaría 10.000 coins.",
        ["Purchase another for 10,000 coins?"] = "¿Comprar otro por 10.000 coins?",
        ["[You're handed another Underworld Grimoire 2.]"] = "[Te entregan otro Underworld Grimoire 2.]",
        ["Farewell."] = "Adiós.",
        ["Select an Option"] = "Selecciona una opción",
        ["Claim an Amulet of Offerings."] = "Reclama un amuleto de ofrendas.",
        ["[You do not have enough space in your backpack for this item.]"] = "[No tienes suficiente espacio en tu backpack para este artículo.]",
        ["[You receive an Amulet of Offerings.]"] = "[Recibes un Amuleto de Ofrendas.]",
        ["Talk about something else."] = "Habla de otra cosa.",
        ["Well met friend."] = "Bien conocido amigo.",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["What exactly is the Sanctum of Rebirth?"] = "¿Qué es exactamente el Santuario del Renacimiento?",
        ["The Sanctum was the domain of my sister."] = "El Santuario era dominio de mi hermana.",
        ["Souls not ready to leave the realm of the living would be brought here to be judged."] = "Las almas que no estaban listas para abandonar el reino de los vivos serían traídas aquí para ser juzgadas.",
        ["Now it is home to creatures of the Devourer, and those that are cursed to enact her will."] = "Ahora es el hogar de las criaturas del Devorador y de aquellos que están malditos para cumplir su voluntad.",
        ["What happened to the Sanctum?"] = "¿Qué pasó con el Santuario?",
        ["There was a brief time in my sister's life, after the Devourer had taken control, but before she was cursed to roam the desert."] = "Hubo un breve período en la vida de mi hermana, después de que el Devorador tomara el control, pero antes de que ella fuera maldecida a vagar por el desierto.",
        ["It was in this time she destroyed the memories of her past self, any means of remembering who she truly was."] = "Fue en este momento que destruyó los recuerdos de su yo pasado, cualquier medio para recordar quién era ella realmente.",
        ["I believe she enacted the same fate on the Sanctum."] = "Creo que ella corrió el mismo destino en el Sanctum.",
        ["Why she did not entirely destroy it, I do not know."] = "Por qué no lo destruyó por completo, no lo sé.",
    },
    ["Icxan"] = {
        ["Greetings young adventurer. Congratulations on finding me!"] = "Saludos joven aventurero. ¡Felicitaciones por encontrarme!",
        ["I've been awaiting your arrival. I have knowledge to share but I am weak, and require assistance."] = "He estado esperando tu llegada. Tengo conocimientos para compartir pero soy débil y necesito ayuda.",
        ["Thank you. You have brought new life back to this old body."] = "Gracias. Has devuelto nueva vida a este viejo cuerpo.",
        ["I see that you have a zodiac card for me to stamp! Let's get that sorted out first."] = "¡Veo que tienes una tarjeta del zodíaco para sellar! Primero solucionemos eso.",
        ["Icxan nods his head and stamps a task for you."] = "Icxan asiente con la cabeza y te asigna una tarea.",
        ["Over my many years of life I have gathered much knowledge. Would you like me to share some with you?"] = "A lo largo de mis muchos años de vida he acumulado muchos conocimientos. ¿Quieres que comparta algunos contigo?",
        ["I'm ready to learn!"] = "¡Estoy listo para aprender!",
        ["*If near Draynor Manor*"] = "*Si está cerca de Draynor Manor*",
        ["Look deep into my eyes so I can discern your current level of learning in Crafting."] = "Mírame profundamente a los ojos para que pueda discernir tu nivel actual de aprendizaje en Crafting.",
        ["*If near Falador*"] = "*Si está cerca de Falador*",
        ["Look deep into my eyes so I can discern your current level of learning in Smithing."] = "Mírame profundamente a los ojos para que pueda discernir tu nivel actual de aprendizaje en Smithing.",
        ["*If in Grotworm Lair*"] = "*Si está en Grotworm Lair*",
        ["Look deep into my eyes so I can discern your current level of learning."] = "Mírame profundamente a los ojos para que pueda discernir tu nivel actual de aprendizaje.",
        ["*If near Lumber Yard*"] = "*Si está cerca de Lumber Yard*",
        ["Look deep into my eyes so I can discern your current level of learning in Cooking."] = "Mírame profundamente a los ojos para que pueda discernir tu nivel actual de aprendizaje en Cooking.",
        ["*If near Nardah*"] = "*Si está cerca de Nardah*",
        ["*If near Oo'glog*"] = "*Si está cerca de Oo'glog*",
        ["Look deep into my eyes so I can discern your current level of learning in Fletching."] = "Mírame profundamente a los ojos para que pueda discernir tu nivel actual de aprendizaje en Fletching.",
        ["*If in Skavid caves*"] = "*Si en cuevas Skavid*",
        ["Look deep into my eyes so I can discern your current level of learning in Construction."] = "Mírame profundamente a los ojos para que pueda discernir tu nivel actual de aprendizaje en Construction.",
        ["*If near Slayer Tower*"] = "*Si está cerca de la torre Slayer*",
        ["Look deep into my eyes so I can discern your current level of learning in Herblore."] = "Mírame profundamente a los ojos para que pueda discernir tu nivel actual de aprendizaje en Herblore.",
        ["*If near White Wolf Mountain*"] = "*Si está cerca de White Wolf Mountain*",
        ["Look deep into my eyes so I can discern your current level of learning in Firemaking."] = "Mírame profundamente a los ojos para que pueda discernir tu nivel actual de aprendizaje en Firemaking.",
        ["*If near Wizards' Tower*"] = "*Si está cerca de Wizards' Tower*",
        ["Look deep into my eyes so I can discern your current level of learning in Runecrafting."] = "Mírame profundamente a los ojos para que pueda discernir tu nivel actual de aprendizaje en Runecrafting.",
        ["You feel momentarily hypnotised by Ixcan's stare. When you come around you find a lamp in your inventory to aid in your training."] = "Te sientes momentáneamente hipnotizado por la mirada de Ixcan. Cuando vuelves, encuentras una lámpara en tu inventario para ayudarte en tu entrenamiento.",
        ["These extra envelopes should also help. Use them to complete your tasks."] = "Estos sobres adicionales también deberían ayudar. Úsalos para completar tus tareas.",
        ["I know everything already."] = "Ya lo sé todo.",
        ["I wish you well with your journeys."] = "Te deseo lo mejor en tus viajes.",
        ["*If the player does not have 31 herblore*"] = "*Si el player no tiene 31 hierbas*",
        ["Unfortunately it appears you are unable to help me."] = "Lamentablemente parece que no puedes ayudarme.",
        ["*You need a Herblore level of 31 to be able to help the wounded snake.*"] = "*Necesitas un nivel Herblore de 31 para poder ayudar a la serpiente herida.*",
        ["Greetings again young adventurer."] = "Saludos nuevamente joven aventurero.",
        ["*If XP lamp has been received at current prestige level*"] = "*Si la lámpara XP se ha recibido en el nivel de prestigio actual*",
        ["I am sorry, but you are not ready to receive more wisdom yet. Do not try to run before you can slither."] = "Lo siento, pero todavía no estás preparado para recibir más sabiduría. No intentes correr antes de que puedas deslizarte.",
        ["*If XP lamp hasn't been received at current prestige level*"] = "*Si la lámpara XP no se ha recibido en el nivel de prestigio actual*",
    },
    ["Idol crablet"] = {
        ["You manage to prise the golden idol free from the crablet's shell."] = "Consigues sacar el ídolo dorado del caparazón del cangrejo.",
    },
    ["Iestin Edern"] = {
        ["Hello, Player, how can I help?"] = "Hola, Player, ¿en qué puedo ayudar?",
        ["Select an Option"] = "Selecciona una opción",
        ["Ask about Lord Iorwerth..."] = "Pregunte por Lord Iorwerth...",
        ["Can you tell me about yourself?"] = "¿Puedes hablarme de ti?",
        ["It's me, Iestin Edern, the new lord of Clan Iorwerth!"] = "¡Soy yo, Iestin Edern, el nuevo señor del Clan Iorwerth!",
        ["My family falls under the auspices of Clan Iorwerth, but it is unusual for one of my standing to be given lordship over the clan."] = "Mi familia está bajo los auspicios del Clan Iorwerth, pero es inusual que a alguien de mi posición se le otorgue el señorío sobre el clan.",
        ["It normally passes to an heir within the family. Except that Morvran - the heir apparent - has waived his claim."] = "Normalmente pasa a un heredero dentro de la familia. Excepto que Morvran, el heredero aparente, ha renunciado a su reclamo.",
        ["It's just as well though. Both Clan Iorwerth and the other clans felt that our clan needed someone more progressive to return us to peace."] = "Aunque es mejor. Tanto el clan Iorwerth como los demás clanes sintieron que nuestro clan necesitaba a alguien más progresista para devolvernos la paz.",
        ["For some reason, they thought that meant me! But I'm stepping up to the role, to honour the memory of my brother."] = "¡Por alguna razón, pensaron que se refería a mí! Pero voy a asumir el papel, para honrar a the memory de mi hermano.",
        ["I fear it was an attempted raising of the Dark Lord that led to the creation of the shadows which killed him."] = "Me temo que fue un intento de resucitar al Señor Oscuro lo que llevó a la creación de las sombras que lo mataron.",
        ["Clan Iorwerth will not be heading down that path again, I assure you."] = "El Clan Iorwerth no volverá a tomar ese camino otra vez, te lo aseguro.",
        ["Ask about Clan Iorwerth..."] = "Pregunte por el Clan Iorwerth...",
        ["Can you tell me about Clan Iorwerth?"] = "¿Puedes hablarme sobre el clan Iorwerth?",
        ["We are a clan of warriors without a war to fight."] = "Somos un clan de guerreros sin una guerra que pelear.",
        ["He says right after an elf civil war ends..."] = "Dice que justo después de que termina una guerra civil entre elfos...",
        ["Yes, but that was our one and only war. Seren forbade us from engaging those who attempted to breach our borders, during the God Wars."] = "Sí, pero esa fue nuestra única guerra. Seren nos prohibió enfrentarnos a aquellos que intentaron traspasar nuestras fronteras durante las Guerras de Dios.",
        ["She protected us, of course, kept them out, but if she'd let us we could have stopped them from trying over and over again."] = "Ella nos protegió, por supuesto, los mantuvo alejados, pero si nos hubiera dejado, podríamos haber evitado que lo intentaran una y otra vez.",
        ["But we were left to guard a city that was protected from on high - a waste of our talents. We should have been allowed to travel east with the Cadarn."] = "Pero nos dejaron proteger una ciudad que estaba protegida desde lo alto: un desperdicio de nuestros talentos. Deberíamos habernos permitido viajar hacia el este con el Cadarn.",
        ["So it was jealousy?"] = "¿Entonces fueron celos?",
        ["No, nothing so base."] = "No, nada tan básico.",
        ["All of my kind wishes for the ability to return home. Ever since the World Gate was taken from us we've been stranded here."] = "Todos mis amables deseos de poder regresar a casa. Desde que nos quitaron la Puerta del Mundo hemos estado varados aquí.",
        ["If the Iorwerth had been given leave to travel beyond the forest, we might have stopped that from happening, or spared our kind from what befell King Baxtorian and Queen Glarial."] = "Si a los Iorwerth se les hubiera dado permiso para viajar más allá del bosque, podríamos haber evitado que eso sucediera, o haber salvado a los de nuestra especie de lo que les sucedió al Rey Baxtorian y a la Reina Glarial.",
        ["You do know the World Gate has been rediscovered, right?"] = "Sabes que la Puerta del Mundo ha sido redescubierta, ¿verdad?",
        ["So Morvran tells me - by you, no less. It's the archaeological find of the century!"] = "Eso me dice Morvran, nada menos que por ti. ¡Es el hallazgo arqueológico del siglo!",
        ["We still can't use it to return home, though there is renewed hope."] = "Todavía no podemos usarlo para regresar a casa, aunque hay esperanzas renovadas.",
        ["You do realise that I've travelled to Tarddiad right?"] = "¿Te das cuenta de que he viajado a Tarddiad, verdad?",
        ["Indeed. There are discussions amongst our clan that now might be the time to return."] = "De hecho. Hay discusiones entre nuestro clan sobre que ahora podría ser el momento de regresar.",
        ["Though the native population may need to be... dealt with... first."] = "Aunque es posible que sea necesario... tratar con... la población nativa primero.",
        ["You have already collected that memory."] = "Ya has recogido ese recuerdo.",
        ["To make matters worse, Seren abandoned us. What were we to do?"] = "Para empeorar las cosas, Seren nos abandonó. ¿Qué íbamos a hacer?",
        ["Seren gone. Baxtorian and the Cadarn gone. Someone had to lead our people. We didn't see anyone else offering."] = "Seren se fue. Baxtorian y el Cadarn desaparecieron. Alguien tenía que liderar a nuestro pueblo. No vimos a nadie más ofreciendo.",
        ["We just wanted to show the other clans what we were capable of."] = "Solo queríamos mostrarles a los otros clanes de lo que éramos capaces.",
        ["So the civil war was for the good of the other clans?"] = "¿Entonces la guerra civil fue por el bien de los otros clanes?",
        ["War is for the good of none, but what led towards it started out as noble intent. The other clan elders disagreed with our more militant view."] = "War no es para el bien de nadie, pero lo que condujo a ello comenzó como una intención noble. Los otros ancianos del clan no estaban de acuerdo con nuestra visión más militante.",
        ["They reverted the city to seed form to protect it from us, but we were ever only trying to protect them, and to find a way back to Tarddiad."] = "Revirtieron la ciudad a su forma semilla para protegerla de nosotros, pero nosotros solo intentábamos protegerlos y encontrar un camino de regreso a Tarddiad.",
        ["To the Iorwerth, they were the traitors. They robbed us of our homes, of Seren's light."] = "Para los Iorwerth, ellos eran los traidores. Nos robaron nuestras casas, la luz de Seren.",
        ["Over the years, our clan lost sight of why this all started, and then this whole business with raising the Dark Lord happened. We lost our way."] = "Con el paso de los años, nuestro clan perdió de vista por qué empezó todo esto, y luego sucedió todo este asunto de criar al Señor Oscuro. Perdimos el rumbo.",
        ["Ask about Iorwerth skills..."] = "Pregunte por las habilidades de Iorwerth...",
        ["Can you tell me about Clan Iorwerth's skills?"] = "¿Puedes contarme sobre las habilidades del clan Iorwerth?",
        ["Clan Iorwerth is comprised of proud and skilled warriors. If the elves were ever to amass an army, its bulk would be comprised of Clan Iorwerth."] = "El clan Iorwerth está compuesto por guerreros orgullosos y hábiles. Si los elfos alguna vez reunieran un ejército, su mayor parte estaría compuesto por el Clan Iorwerth.",
        ["Oh, the Cadarn would field their mages and scouts, the Ithell some war singers, and the Trahaearn some of their combat automatons, but Clan Iorwerth would form the backbone."] = "Oh, los Cadarn desplegarían a sus magos y exploradores, los Ithell algunos cantantes de guerra y los Trahaearn algunos de sus autómatas de combate, pero el Clan Iorwerth formaría la columna vertebral.",
        ["For the army to break, Clan Iorwerth would have to break, and that's just not something we do."] = "Para que el ejército se desmorone, el clan Iorwerth tendría que desmoronarse, y eso no es algo que hagamos.",
        ["So your troops are predominantly melee fighters?"] = "¿Entonces tus tropas son predominantemente luchadores cuerpo a cuerpo?",
        ["Yes - though we do count some trackers and scouts among our number. We've had to become self-reliant, thanks to the civil war."] = "Sí, aunque contamos con algunos rastreadores y exploradores entre nosotros. Hemos tenido que volvernos autosuficientes gracias a la guerra civil.",
        ["Our troops favour the halberd for its reach, and twin daggers for close-quarter fighting."] = "Nuestras tropas prefieren la alabarda por su alcance y las gemelas daggers para el combate cuerpo a cuerpo.",
        ["You are welcome to test them in combat. An untested warrior is useless, like a dulled blade."] = "Puedes probarlos en combate. Un guerrero no probado es inútil, como una espada sin filo.",
        ["We also have a slayer master in our ranks - Morvran. Strictly, he should have become the new Lord Iorwerth, and frankly I'm glad he waived that right."] = "También tenemos un slayer master en nuestras filas: Morvran. Estrictamente, debería haberse convertido en el nuevo Lord Iorwerth y, francamente, me alegro de que haya renunciado a ese derecho.",
        ["Not so that I could become lord, you understand. He's amiable enough, but he has some odd predilections. There's just something slightly off about him, and I can't quite identify what."] = "No para convertirme en señor, ¿entiendes? Es bastante amable, pero tiene algunas predilecciones extrañas. Hay algo un poco extraño en él y no puedo identificar qué.",
        ["Nothing, thanks."] = "Nada, gracias.",
        ["Please don't go up there, those are my private quarters."] = "Por favor, no subas allí, esos son mis alojamientos privados.",
        ["For Clan Iorwerth! Show these Cadarn how it's done!"] = "¡Por el clan Iorwerth! ¡Muéstrales a estos Cadarn cómo se hace!",
        ["Before I will help you, human, you must complete this for me!"] = "¡Antes de que te ayude, humano, debes completar esto por mí!",
        ["[Lord Iorwerth has given you a puzzle box!]"] = "[¡Lord Iorwerth te ha regalado una caja de rompecabezas!]",
        ["Do not waste my time, human!"] = "¡No me hagas perder el tiempo, humano!",
        ["[Lord Iorwerth has given you another clue scroll!]"] = "[¡Lord Iorwerth te ha dado otro pergamino de pistas!]",
        ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
        ["You have done well, human!"] = "¡Lo has hecho bien, humano!",
    },
    ["Ifaba"] = {
        ["Ook! Ah Uh Ah! Ook Ah Uh! Ook Ah Ook!"] = "¡Ok! ¡Ah, ah, ah! ¡Ah, uh! ¡Ok, ah, ook!",
        ["You cannot understand what he is saying."] = "No puedes entender lo que está diciendo.",
        ["Would you like to buy or sell anything?"] = "¿Te gustaría comprar o vender algo?",
        ["Select an Option"] = "Selecciona una opción",
        ["Yes, please."] = "Sí, por favor.",
        ["No, thanks."] = "No, gracias.",
        ["What would you like to do?"] = "¿Qué te gustaría hacer?",
        ["Ask about their request."] = "Pregunta sobre su solicitud.",
        ["What're you requesting today?"] = "¿Qué pides hoy?",
        ["I've been working on my own farm recently and need a few items to bolster my productivity!"] = "¡He estado trabajando en mi propia granja recientemente y necesito algunos artículos para aumentar mi productividad!",
        ["I'm trying to get some extra crops going, so I'll need : [Seed] x [number]"] = "Estoy intentando conseguir algunos cultivos adicionales, así que necesitaré: [Seed] x [número]",
        ["I'm also looking for a new animal, I'm currently after one of the following : [Animal], or [Animal], or [Animal]"] = "También estoy buscando un nuevo animal. Actualmente busco uno de los siguientes: [Animal], o [Animal], o [Animal].",
        ["I'm also looking for a new animal, I'm currently after one of the following : [Animal], or [Animal], or [Animal], or [Animal]"] = "También estoy buscando un nuevo animal. Actualmente busco uno de los siguientes: [Animal], o [Animal], o [Animal], o [Animal].",
        ["I'm also looking for some produce, so I'll need : [Produce] x [number]"] = "También estoy buscando algunos productos, así que necesitaré: [Produce] x [número]",
        ["If you complete this, I'll give you : A chance at obtaining a banana themed cosmetic x 1. I'm sure you'll gain some reputation with the farming guild too!"] = "Si completas esto, te daré: La oportunidad de obtener un cosmético con temática de plátano x 1. ¡Estoy seguro de que también ganarás reputación en el gremio de agricultores!",
        ["You'll have to be quick though!, I'm only here for [number] days, [number] hours and [number] minutes. To be exact."] = "¡Tendrás que ser rápido!, solo estoy aquí por [número] días, [número] horas y [número] minutos. Para ser exactos.",
        ["Give them the items & animals for their request"] = "Dales los artículos y animales que soliciten.",
        ["You don't have enough items to fulfil my request. I won't take favourited animals."] = "No tienes suficientes artículos para cumplir con mi solicitud. No aceptaré animales favoritos.",
        ["For completing this request you've received Brassica primer x 1."] = "Por completar esta solicitud, recibió 1 imprimación para Brassica.",
        ["[You've received : Banana x 1<br>And 5,500 farming reputation.]"] = "[Has recibido: Plátano x 1<br>Y 5500 de reputación agrícola.]",
        ["[You've received : Left banana of knowledge x 1<br>And 5,500 farming reputation.]"] = "[Has recibido: Plátano izquierdo de conocimiento x 1<br>Y 5500 de reputación agrícola.]",
        ["[You've received : Right banana of knowledge x 1<br>And 5,500 farming reputation.]"] = "[Has recibido: Plátano correcto de conocimiento x 1<br>Y 5500 de reputación agrícola.]",
        ["Thank you for your help!"] = "¡Gracias por tu ayuda!",
        ["A new request will be available in [time]."] = "Una nueva solicitud estará disponible en [time].",
        ["Which animal would you like to hand in?"] = "¿Qué animal te gustaría entregar?",
        ["You've already completed this request, there will be a new tri-daily request in [time].."] = "Ya completó esta solicitud, habrá una nueva solicitud tridiaria en [time].",
    },
    ["Iffie"] = {
        ["Hello, dearie! Were you wanting to collect a costume, or is there something else I can do for you today?"] = "¡Hola, cariño! ¿Querías coleccionar un disfraz o hay algo más que pueda hacer por ti hoy?",
        ["What would you like to say?"] = "¿Qué te gustaría decir?",
        ["I've come for a costume."] = "He venido por un disfraz.",
        ["I may be able to find your lost ghostly costumes, or I have my costume store. Which do you want?"] = "Quizás pueda encontrar tus disfraces fantasmales perdidos o tengo mi tienda de disfraces. ¿Cuál quieres?",
        ["Select an option"] = "Selecciona una opción",
        ["One of my ghostly costumes."] = "Uno de mis disfraces fantasmales.",
        ["A costume from your store."] = "Un disfraz de tu tienda.",
        ["Some of these costumes even come with a free emote!"] = "¡Algunos de estos disfraces incluso vienen con un gesto gratis!",
        ["Just buy one piece of the mime or zombie costumes and I'll show you all of the relevant moves."] = "Solo compra una pieza de los disfraces de mimo o zombi y te mostraré todos los movimientos relevantes.",
        ["Aren't you selling anything?"] = "¿No estás vendiendo nada?",
        ["Oh, yes, but only costumes. Thessalia sells some other clothes and runs the makeover mage service."] = "Ah, sí, pero solo disfraces. Thessalia vende otras prendas y gestiona el servicio makeover mage.",
        ["I just came for a chat."] = "Sólo vine para charlar.",
        ["Oh, I'm sorry, but I'll never get my knitting done if I stop for a chit-chat with every young [lad/lass] who wanders through the shop!"] = "Oh, lo siento, ¡pero nunca terminaré de tejer si me detengo a charlar con cada joven [lad/lass] que deambula por la tienda!",
        ["You should go and see my sister, Elsie, upstairs in Varrock Church; she's always ready for a good natter."] = "Deberías ir a ver a mi hermana, Elsie, arriba en la iglesia Varrock; ella siempre está lista para una buena charla.",
        ["I'm here to talk about what you are knitting."] = "Estoy aquí para hablar de lo que estás tejiendo.",
        ["This? I've been knitting all sorts of things, mainly things that remind me of the good ol' days."] = "¿Esto? He estado tejiendo todo tipo de cosas, principalmente cosas que me recuerdan los buenos tiempos.",
        ["You might be younger than me, but perhaps you want a cape that reminds you of the old days too?"] = "Puede que seas más joven que yo, pero ¿quizás también quieras una capa que te recuerde a los viejos tiempos?",
        ["And I see you are a veteran of the old days - would you like a cape that reminds you of the old days?"] = "Y veo que eres un veterano de los viejos tiempos. ¿Te gustaría una capa que te recuerde los viejos tiempos?",
        ["My knitting comes at a price - it's a fair bit of effort and materials. Does 50,000 coins sound okay to you, m'dear?"] = "Tejer tiene un precio: requiere bastante esfuerzo y materiales. ¿Te parece bien 50.000 coins, querida?",
        ["Pay 50,000 for a Classic cape?"] = "¿Pagar 50.000 por una capa clásica?",
        ["I'll take one!"] = "¡Me quedo con uno!",
        ["That's good, but you don't have enough money for the cape."] = "Eso está bien, pero no tienes suficiente dinero para la capa.",
        ["That's good, but you've got no space in your inventory for the cape and hood."] = "Eso está bien, pero no tienes espacio en tu inventario para la capa y la capucha.",
        ["Thanks. Enjoy!"] = "Gracias. ¡Disfrutar!",
        ["No, thanks."] = "No, gracias.",
        ["What can I do with ghostweave?"] = "¿Qué puedo hacer con el tejido fantasma?",
        ["Ghostweave! I've not seen that for such a long time. You can make costumes out of it, and you can look like a scary ghost."] = "¡Tejido fantasma! Hace mucho tiempo que no veo eso. Puedes hacer disfraces con él y puedes parecer un fantasma aterrador.",
        ["It takes quite a lot though, dearie, depending on the costume you want."] = "Aunque se necesita bastante, cariño, dependiendo del disfraz que quieras.",
        ["You could also exchange ghostweave for special Hallowe'en chocolates that have interesting effects."] = "También puedes intercambiar tejido fantasma por chocolates especiales de Halloween que tienen efectos interesantes.",
        ["After the event you can bring any unused ghostweave back to me and I will exchange it for Crafting XP."] = "Después del evento, puedes traerme cualquier tejido fantasma no utilizado y lo cambiaré por Crafting XP.",
        ["*(During the main promotion:)*"] = "*(Durante la promoción principal:)*",
        ["Perhaps later I'll buy any ghostweave you've got left, but you should try making costumer or chocolates with it now."] = "Quizás más adelante compre el tejido fantasma que te quede, pero deberías intentar hacer chocolates o disfraces con él ahora.",
        ["*(After the main promotion:)*"] = "*(Después de la promoción principal :)*",
        ["*(Without ghostweave in backpack:)*"] = "*(Sin tejido fantasma en backpack :)*",
        ["I'll buy any you have spare, or you could convert it in to chocolates yourself."] = "Te compraré los que te sobren o puedes convertirlos en chocolates tú mismo.",
        ["*(With ghostweave in backpack:)*"] = "*(Con tejido fantasma en backpack :)*",
        ["That ghostweave won't last much longer now. Do you want to sell me your spare ghostweave? I'll give you 40 coins or a little crafting training for each piece you have."] = "Ese tejido fantasma ya no durará mucho más. ¿Quieres venderme tu tejido fantasma de repuesto? Te daré 40 coins o un poco de capacitación en artesanía por cada pieza que tengas.",
        ["Sell ghostweave?"] = "¿Vender tejido fantasma?",
        ["Sell all ([N]) for [40N] gold"] = "Vender todo ([N]) por oro [40N]",
        ["There you go, dearie. That's [40N] coins. Don't spend them all at once."] = "Ahí tienes, querida. Eso es [40N] coins. No los gastes todos a la vez.",
        ["[40N] coins have been added to your money pouch."] = "[40N] coins se han agregado a su bolsa de dinero.",
        ["Sell X for gold (40 each)"] = "Vender X por oro (40 cada uno)",
        ["*(After entering amount:)*"] = "*(Después de ingresar el monto:)*",
        ["Sell all ([N]) for [20N] bonus XP"] = "Vende todo ([N]) para obtener XP extra de [20N]",
        ["There you go, dearie. I'm sure you'll be better at crafting with some practice."] = "Ahí tienes, querida. Estoy seguro de que serás mejor haciendo manualidades con un poco de práctica.",
        ["You have gained [20N] bonus experience points in the Crafting skill."] = "Has ganado puntos de experiencia adicionales [20N] en la habilidad Crafting.",
        ["Sell X for bonus Crafting XP (20 each)"] = "Vende X para obtener Crafting XP extra (20 cada uno)",
        ["Don't sell"] = "no vender",
        ["Okay, dearie, but it won't last long, so decide what you want to do with it soon."] = "Está bien, querida, pero no durará mucho, así que decide pronto qué quieres hacer con él.",
        ["Oh, not that Mime nonsense again. How many times do I have to copy you before you leave me alo -"] = "Oh, no esa tontería de Mime otra vez. ¿Cuántas veces tengo que copiarte antes de que me dejes solo?",
        ["Oh, wait, sorry - I'm not the Mime. This isn't some kind of random event."] = "Oh, espera, lo siento, no soy el Mime. Este no es algún tipo de evento aleatorio.",
        ["Oh, thank goodness. All of these odd strangers showing up, expecting us to perform."] = "Oh, gracias a Dios. Todos estos extraños extraños aparecen, esperando que actuemos.",
        ["I suppose it has been a while since they stopped coming by. At least I had someone to talk to..."] = "Supongo que ha pasado un tiempo desde que dejaron de venir. Al menos tenía alguien con quien hablar...",
        ["So Random"] = "tan aleatorio",
        ["Perform the 'Glass Wall' emote while wearing the full Mime outfit inside of Thessalia's Fine Clothes in Varrock."] = "Realiza el gesto 'Glass Wall' mientras usas el atuendo completo de Mime dentro de Fine Clothes de Thessalia en Varrock.",
        ["You never know what you'll missed until it's gone."] = "Nunca sabes lo que te perderás hasta que desaparece.",
        ["Looks like I've completed everything. I'd better go and see Hans about that reward!"] = "Parece que he completado todo. ¡Será mejor que vaya a ver a Hans sobre esa recompensa!",
    },
    ["Ignatius Vulcan"] = {
        ["Can I help you at all?"] = "¿Puedo ayudarte en algo?",
        ["Select an Option"] = "Selecciona una opción",
        ["Who are you?"] = "¿Quién eres?",
        ["My name is Ignatius Vulcan. Once I was - like you - an adventurer, but that was before I realised the beauty and power of flame! Just look at this..."] = "Mi nombre es Ignatius Vulcan. Una vez fui, como tú, un aventurero, ¡pero eso fue antes de que me diera cuenta de la belleza y el poder de las llamas! Solo mira esto...",
        ["Stare into the flame and witness the purity and power of fire! As my attraction to flame grew, so did my skills at firelighting. I began to neglect my combat skills, my Mining skills and my questing. Who needs such mundane skills"] = "¡Mira fijamente la llama y sé testigo de la pureza y el poder del fuego! A medida que mi atracción por las llamas crecía, también crecían mis habilidades para encender fuegos. Empecé a descuidar mis habilidades de combate, mis habilidades Mining y mis misiones. ¿Quién necesita habilidades tan mundanas?",
        ["when one can harness the power of fire? After years of practice I am now the acknowledged Master of Flame! Everything must be purified by fire!"] = "¿Cuándo se puede aprovechar el poder del fuego? ¡Después de años de práctica, ahora soy el Maestro de la Llama reconocido! ¡Todo debe ser purificado por el fuego!",
        ["Okaaaay! Err, I'll be going now. Umm, get better soon."] = "¡Está bien! Err, me voy ahora. Umm, mejora pronto.",
        ["Do you have anything for trade?"] = "¿Tienes algo para intercambiar?",
        ["What is that cape you're wearing?"] = "¿Qué es esa capa que llevas puesta?",
        ["This is a Skillcape of Firemaking. I was given it in recognition of my skill as the greatest firemaker in the lands! I AM the Master of Flame!"] = "Este es un Skillcape de Firemaking. ¡Me lo dieron en reconocimiento a mi habilidad como el mejor fabricante de fuego del país! ¡YO SOY el Maestro de la Llama!",
        ["Hmm, I'll be going now. Keep a sharp look out for those men with their white jackets!"] = "Hmm, ya me voy. ¡Esté atento a esos hombres con sus chaquetas blancas!",
        ["No, thanks."] = "No, gracias.",
        ["Okay, keep the fire burning."] = "Está bien, mantén el fuego encendido.",
        ["Can I buy a Skillcape of Firemaking?"] = "¿Puedo comprar un Skillcape de Firemaking?",
        ["I don't do this for anyone, but I've got a special offer today! Normally I require 99,000 coins for this prestigious item, but for you it's half price. Only 92,000 coins!"] = "No hago esto por nadie, ¡pero hoy tengo una oferta especial! Normalmente necesito 99.000 coins por este prestigioso artículo, pero para ti es la mitad de precio. ¡Solo 92.000 coins!",
        ["Choose an option:"] = "Elige una opción:",
        ["92,000 coins? That's much too expensive."] = "¿92.000 coins? Eso es demasiado caro.",
        ["I know where to find you if I change my mind."] = "Sé dónde encontrarte si cambio de opinión.",
        ["I think I have the money right here, actually."] = "De hecho, creo que tengo el dinero aquí.",
        ["Unfortunately all skillcapes are only available with a free hood, it's part of a skill promotion deal; buy one get one free, you know. So, you'll need to free up some backpack space before I can sell you one."] = "Lamentablemente, todos los skillcapes solo están disponibles con una capucha gratuita, es parte de un acuerdo de promoción de habilidades; Compra uno y llévate otro gratis, ya sabes. Por lo tanto, necesitarás liberar algo de espacio en backpack antes de que pueda venderte uno.",
        ["But unfortunately, I was mistaken."] = "Pero desafortunadamente me equivoqué.",
        ["Well, come back and see me when you do."] = "Bueno, vuelve a verme cuando lo hagas.",
        ["Excellent! Wear that cape with pride my friend."] = "¡Excelente! Lleva esa capa con orgullo, amigo mío.",
        ["99,000 coins? That's much too expensive."] = "¿99.000 coins? Eso es demasiado caro.",
        ["I've mastered this skill. Is there anything else?"] = "He dominado esta habilidad. ¿Hay algo más?",
        ["There is something...though I have kept it a secret for a very long time. It is something that can only be worn by a true master."] = "Hay algo... aunque lo he mantenido en secreto durante mucho tiempo. Es algo que sólo puede ser usado por un verdadero maestro.",
        ["Not even I can wear it - that's how hard it is to achieve."] = "Ni siquiera yo puedo usarlo, así de difícil es lograrlo.",
        ["You say you're a master. Stand straight, let me take a look at you."] = "Dices que eres un maestro. Ponte derecho, déjame echarte un vistazo.",
        ["You...really have mastered it. What an honour! It would be my pleasure to sell you a Firemaking master cape."] = "Tú... realmente lo dominas. ¡Qué honor! Sería un placer venderle un Firemaking master cape.",
        ["Buy Firemaking master cape for 120,000 coins?"] = "¿Comprar Firemaking master cape por 120.000 coins?",
        ["Yes."] = "Sí.",
        ["You do not have enough room in your backpack. Please come back when you have some more."] = "No tienes suficiente espacio en tu backpack. Por favor regresa cuando tengas más.",
        ["You do not have enough money to purchase this cape."] = "No tienes suficiente dinero para comprar esta capa.",
        ["I've noticed there are a couple of versions of each skillcape."] = "He notado que hay un par de versiones de cada skillcape.",
        ["Yes! We, the skill masters, have crafted new versions of all skillcapes! We felt like it was time for a change."] = "¡Sí! ¡Nosotros, los maestros de habilidades, hemos creado nuevas versiones de todos los skillcapes! Sentimos que era hora de un cambio.",
        ["It looks like you're currently using the old model for your Firemaking skillcape. Would you like to change to the newer one?"] = "Parece que actualmente estás usando el modelo anterior para tu Firemaking skillcape. ¿Quieres cambiar a uno más nuevo?",
        ["You can still choose to wear the old model skillcape if you want. Would you like to change which model you are currently using?"] = "Aún puedes elegir usar el modelo antiguo skillcape si lo deseas. ¿Le gustaría cambiar el modelo que está utilizando actualmente?",
        ["Select an option"] = "Selecciona una opción",
        ["Yes, I would like to wear the [new/old] version of the skillcape."] = "Sí, me gustaría usar la versión [new/old] del skillcape.",
        ["Would you like to wear the [old/newer] model for just this cape, or for the Quest Cape and all of the skillcapes you own?"] = "¿Te gustaría usar el modelo [old/newer] solo para esta capa, o para el Quest Cape y todos los skillcapes que tienes?",
        ["I would just like to change the Firemaking skillcape."] = "Solo me gustaría cambiar el Firemaking skillcape.",
        ["No problem, you will now use the [older/newer] model for your Firemaking skillcape."] = "No hay problema, ahora utilizarás el modelo [older/newer] para tu Firemaking skillcape.",
        ["I would like to change all my skillcapes."] = "Me gustaría cambiar todos mis skillcapes.",
        ["No problem, you will now use the [older/newer] model for all of your skillcapes!"] = "¡No hay problema, ahora usarás el modelo [older/newer] para todos tus skillcapes!",
        ["I've changed my mind!"] = "¡He cambiado de opinión!",
        ["No, thank you."] = "No, gracias.",
        ["Great! I'm glad you're still enjoying the [old/new] version!"] = "¡Genial! ¡Me alegra que sigas disfrutando de la versión [old/new]!",
        ["If you want, I can make it so you use the old model for all of the skillcapes you own."] = "Si quieres, puedo hacerlo para que uses el modelo antiguo para todos los skillcapes que tengas.",
        ["Ok, I'd like to wear the old version for all my skillcapes."] = "Ok, me gustaría usar la versión antigua para todos mis skillcapes.",
        ["Great, you will now use the old model for all of your skillcapes!"] = "¡Genial, ahora usarás el modelo antiguo para todos tus skillcapes!",
    },
    ["Ikadia the Exile"] = {
        ["Praise Zamorak for conflict, friend. Will you not test the strength of my chaos druids? I fear they grow weak and deserve to be cut down."] = "Elogie a Zamorak por el conflicto, amigo. ¿No pondrás a prueba la fuerza de mis druidas del caos? Temo que se debiliten y merezcan ser talados.",
        ["Select an Option"] = "Selecciona una opción",
        ["Who are you?"] = "¿Quién eres?",
        ["I am Ikadia the Exile, leader of these druids. I wear the title in honour of my ancestor Urval, who was exiled by the druids above for preaching the truth about Guthix and Zamorak."] = "Soy Ikadia the Exile, líder de estos druidas. Llevo el título en honor a mi antepasado Urval, que fue exiliado por los druidas de arriba por predicar la verdad sobre Guthix y Zamorak.",
        ["Zamorak is Guthix's most perfect incarnation! He brings balance to the world through chaos!"] = "¡Zamorak es la encarnación más perfecta de Guthix! ¡Él trae equilibrio al mundo a través del caos!",
        ["Haven't you heard? Guthix is dead!"] = "¿No te has enterado? ¡Guthix está muerto!",
        ["Of course I've heard, you insolent little man!"] = "¡Por supuesto que lo he oído, hombrecito insolente!",
        ["Like all druids, I felt the shiver run through the world. Unlike them, however, I rejoiced! Guthix has shed his old form, just as Urval foretold. Now he returns in the form of Zamorak, to bring balance through chaos!"] = "Como todos los druidas, sentí el escalofrío recorrer el mundo. ¡Sin embargo, a diferencia de ellos, yo me regocijé! Guthix se ha despojado de su antigua forma, tal como lo predijo Urval. ¡Ahora regresa en forma de Zamorak, para traer equilibrio a través del caos!",
        ["Saradomin defeated Zamorak at the Battle of Lumbridge."] = "Saradomin derrotó a Zamorak en la Batalla de Lumbridge.",
        ["Fool! You see only the surface and are blind to the true meaning!"] = "¡Tonto! ¡Ves sólo la superficie y estás ciego al verdadero significado!",
        ["When Saradomin and Zamorak began to fight, Lumbridge became a war zone, did it not? A place of conflict and destruction - a place of chaos!"] = "Cuando Saradomin y Zamorak comenzaron a pelear, Lumbridge se convirtió en una zona de guerra, ¿no? Un lugar de conflicto y destrucción, ¡un lugar de caos!",
        ["That's an interesting interpretation."] = "Esa es una interpretación interesante.",
        ["I'm glad to meet someone who's willing to think independently, rather than blindly accept popular beliefs."] = "Me alegra conocer a alguien que esté dispuesto a pensar de forma independiente, en lugar de aceptar ciegamente las creencias populares.",
        ["Your beliefs are ridiculous."] = "Tus creencias son ridículas.",
        ["I am not here to win converts. Believe what you will."] = "No estoy aquí para ganar adeptos. Cree lo que quieras.",
        ["I'd rather test *your* strength."] = "Prefiero poner a prueba *tu* fuerza.",
        ["Maybe someday, little one - when I have a reason to fight you."] = "Tal vez algún día, pequeño, cuando tenga una razón para pelear contigo.",
        ["You have tested my strength once before and defeated me. It was a worthy combat!"] = "Ya probaste mi fuerza una vez y me derrotaste. ¡Fue un combate digno!",
        ["Goodbye."] = "Adiós.",
    },
    ["Ikis Krum"] = {
        ["Hello."] = "Hola.",
        ["Good day, [sir/madam]. What brings you to this end of town?"] = "Buenos días, [sir/madam]. ¿Qué te trae a este extremo de la ciudad?",
        ["Well, what is there to do around here?"] = "Bueno, ¿qué hay que hacer por aquí?",
        ["If you're into Mining, plenty! The dwarves have one of the largest mines in the world just under our feet. There's an entrance in the building just north-east of my house."] = "Si te gusta Mining, ¡muchos! Los enanos tienen una de las minas más grandes del mundo justo bajo nuestros pies. Hay una entrada en el edificio justo al noreste de mi casa.",
        ["If you're one of these young, loud, hipster sorts you could visit the Party Room, just north of here. That blasted Pete parties all night and I never get any sleep!"] = "Si eres uno de esos jóvenes, ruidosos e inconformistas, puedes visitar Party Room, justo al norte de aquí. ¡Eso jodió que Pete festeje toda la noche y yo nunca duermo!",
        ["Thanks."] = "Gracias.",
    },
    ["Ileana"] = {
        ["*(Before River of Blood:)*"] = "*(Antes de Río de Sangre:)*",
        ["Hey it's the hero! Wow, you're amazing! How on earth did you manage to tackle those two juvinates and Gadderanks? And the town is lovely - you've done a great job!"] = "¡Oye, es el héroe! ¡Guau, eres increíble! ¿Cómo diablos lograste enfrentarte a esos dos juvinates y Gadderanks? Y la ciudad es preciosa. ¡Has hecho un gran trabajo!",
        ["*(After River of Blood:)*"] = "*(Después de Río de Sangre :)*",
        ["Hey it's the hero! Wow, you're amazing! How did you manage to return all the villagers? Things feel so much safer around here now too - great job!"] = "¡Oye, es el héroe! ¡Guau, eres increíble! ¿Cómo conseguiste devolver a todos los aldeanos? Ahora las cosas también se sienten mucho más seguras por aquí: ¡excelente trabajo!",
        ["You're more than welcome."] = "De nada.",
        ["Select an option"] = "Selecciona una opción",
        ["What do you do here?"] = "¿Qué haces aquí?",
        ["Well met! My name's Ileana. I do a bit of this, a bit of that. Just try to survive really, there's nothing much else we can do."] = "¡Bien conocido! Mi nombre es Ileana. Hago un poco de esto, un poco de aquello. Sólo trata de sobrevivir de verdad, no hay mucho más que podamos hacer.",
        ["How do you like your town?"] = "¿Qué te parece tu ciudad?",
        ["It's just perfect, thanks so much for your efforts."] = "Es simplemente perfecto, muchas gracias por tus esfuerzos.",
        ["What's happening around here?"] = "¿Qué está pasando por aquí?",
        ["Oh, not much really, we're all still hiding from the vampyres and eking out a living from this terrible place, hopefully soon we'll be strong enough to make the journey to the temple on the Salve."] = "Oh, no mucho en realidad, todos todavía nos estamos escondiendo del vampyres y ganándonos la vida a duras penas en este terrible lugar, con suerte pronto seremos lo suficientemente fuertes para hacer el viaje al templo en la Salve.",
        ["Oh, not much really, we're all just trying to eke out a living in this place. Some of us still want to head for the Salve and into Misthalin, but honestly, it's not so bad here anymore...in spite of how it might look."] = "Oh, no mucho en realidad, todos estamos tratando de ganarnos la vida a duras penas en este lugar. Algunos de nosotros todavía queremos dirigirnos a la Salve y a Misthalin, pero, sinceramente, ya no está tan mal aquí... a pesar de cómo pueda parecer.",
        ["Is there anything I can do to help out?"] = "¿Hay algo que pueda hacer para ayudar?",
        ["Not as far as I know, we have some basic amenities now which is so very useful, we're all incredibly grateful to you. I've never really seen or known a hero before, so I have nothing to compare one to, but I suspect in most people's judgement, you would be one! I for one am very pleased to have met you."] = "No que yo sepa, ahora contamos con algunos servicios básicos que son muy útiles y todos te estamos increíblemente agradecidos. Nunca antes había visto o conocido a un héroe, así que no tengo nada con qué compararlo, pero sospecho que, a juicio de la mayoría de la gente, ¡tú serías uno! Por mi parte, estoy muy contento de haberte conocido.",
        ["Okay, thanks."] = "Está bien, gracias.",
    },
    ["Ilfeen"] = {
        ["**Player:{{anchor|helloagain}}** Hello again. Are you still offering to chant seeds?"] = "**Player:{{anchor|helloagain}}** Hola de nuevo. ¿Sigues ofreciendo cantar semillas?",
        ["I am, but you’ll need your own seed. After I've made you a new bow or shield once, I'll be able to chant your bows and shields back to full charges."] = "Lo soy, pero necesitarás tu propia semilla. Después de que te haya hecho un nuevo arco o escudo una vez, podré cantar tus arcos y escudos para que vuelvan a cargarse por completo.",
        ["**Ilfeen:{{anchor|like}}** Would you like me to enchant anything? Or I could give you a book about crystal singing?"] = "**Ilfeen:{{anchor|like}}** ¿Quieres que encante algo? ¿O podría darte un libro sobre el canto con cristales?",
        ["What would you like?"] = "¿Qué te gustaría?",
        ["Enchant something."] = "Encantar algo.",
        ["Show me a crystal seed or crystal item, and I'll see what I can do with it."] = "Muéstrame una semilla de cristal o un objeto de cristal y veré qué puedo hacer con él.",
        ["Crystal singing book."] = "Libro de canto de cristal.",
        ["Could I have the book, please?"] = "¿Podría darme el libro, por favor?",
        ["[Ilfeen hands you a book.]"] = "[Ilfeen te entrega un libro.]",
        ["Thanks, I'll read all about it."] = "Gracias, lo leeré todo.",
        ["Well, good luck."] = "Bueno, buena suerte.",
        ["Goodbye, Ilfeen."] = "Adiós, Ilfeen.",
        ["Nothing, thanks."] = "Nada, gracias.",
        ["There is something I meant to ask you about. Do you remember Oaknock? He was a gnome inventor."] = "Hay algo sobre lo que quería preguntarte. ¿Recuerdas Oaknock? Fue un inventor de gnomos.",
        ["Of course! I remember him from when I was living in the eastern lands."] = "¡Por supuesto! Lo recuerdo de cuando yo vivía en tierras orientales.",
        ["He was just a budding engineer then. I rather liked the young gnome: he was rather loud, but he had a good soul. He was very interested in elven magic."] = "Entonces era solo un ingeniero en ciernes. Me gustó bastante el joven gnomo: era bastante ruidoso, pero tenía buen alma. Estaba muy interesado en la magia élfica.",
        ["Last time we spoke, not too long ago, he was very interested in illusion magic and how to dispel it. I gave him some advice and a few pieces of equipment to help him."] = "La última vez que hablamos, no hace mucho, estaba muy interesado en la magia de ilusión y en cómo disiparla. Le di algunos consejos y algunos equipos para ayudarlo.",
        ["I think Oaknock died of old age a few hundred years ago now..."] = "Creo que Oaknock murió de viejo hace unos cientos de años...",
        ["I keep forgetting - a hundred years is a long time for you."] = "Sigo olvidándome: cien años es mucho tiempo para ti.",
        ["Did you ever give him a seed?"] = "¿Alguna vez le diste una semilla?",
        ["Of course. It grew into a saw. I hope he found it useful."] = "Por supuesto. Se convirtió en una sierra. Espero que le haya resultado útil.",
        ["I think he did! Thanks."] = "¡Creo que sí! Gracias.",
        ["Ilfeen smiles serenely."] = "Ilfeen sonríe serenamente.",
        ["Sorry, I can't do anything with attuned crystals. They're beyond my ability."] = "Lo siento, no puedo hacer nada con cristales sintonizados. Están más allá de mi capacidad.",
        ["Oh, that teleport crystal is still enchanted."] = "Oh, ese cristal de teletransporte todavía está encantado.",
        ["I've never seen a crystal tool like that before! I didn't think it was even possible to..."] = "¡Nunca antes había visto una herramienta de cristal como esa! Ni siquiera pensé que fuera posible...",
        ["This is Lady Ithell's doing, isn't it?"] = "Esto es obra de Lady Ithell, ¿no?",
        ["The harmonic stresses inflicted on this instrument are painful to my ears. I'm surprised it hasn't shattered. Keep it away from me."] = "Las tensiones armónicas infligidas a este instrumento son dolorosas para mis oídos. Me sorprende que no se haya hecho añicos. Mantenlo alejado de mí.",
        ["Add 8 charges to one teleport seed for 400 coins?"] = "¿Agregar 8 cargas a una semilla de teletransporte por 400 coins?",
        ["Cancel"] = "Cancelar",
        ["OK"] = "bien",
        ["Add 8 charges to [number] teleport seeds for [number] coins?"] = "¿Agregar 8 cargas a las semillas de teletransporte [número] para [número] coins?",
    },
    ["Ilona"] = {
        ["Adventurer! It's good to see you again!"] = "¡Aventurero! ¡Qué bueno verte de nuevo!",
        ["Select an Option"] = "Selecciona una opción",
        ["I passed my apprenticeship! I'm a wizard now."] = "¡Aprobé mi aprendizaje! Soy un mago ahora.",
        ["I'm studying stun and bind spells. If I get into a fight again, I want to be able to disable enemies without killing them, like you did with those cultists."] = "Estoy estudiando hechizos para aturdir y vincular. Si vuelvo a pelear, quiero poder desactivar a los enemigos sin matarlos, como hiciste con esos cultistas.",
        ["I'm studying elemental battle spells. I'm not a violent person, but...after you had to kill those cultists to rescue me, it made me realise I have to be able to defend myself."] = "Estoy estudiando hechizos de batalla elementales. No soy una persona violenta, pero... después de que tuviste que matar a esos cultistas para rescatarme, me hizo darme cuenta de que tengo que poder defenderme.",
        ["Sorry, who are you?"] = "Perdón, ¿quién eres?",
        ["You don't remember me? I suppose you must rescue lots of girls from evil cultists. I can't expect you to remember them all."] = "¿No me recuerdas? Supongo que debes rescatar a muchas chicas de los malvados cultistas. No puedo esperar que los recuerdes todos.",
        ["Ilona! How are you doing?"] = "¡Ilona! ¿Cómo estás?",
        ["I should go."] = "Debería irme.",
        ["Hello again, adventurer."] = "Hola de nuevo, aventurero.",
        ["*1. I've got a question about my adventure in the catacombs...*"] = "*1. Tengo una pregunta sobre mi aventura en las catacumbas...*",
        ["*1. What will happen in the catacombs now?*"] = "*1. ¿Qué pasará ahora en las catacumbas?*",
        ["Reese managed to complete the ritual with his own death. He's opened the lower level of the catacombs, which is swarming with undead. without a necromancer to control them, the creatures won't leave the tomb. I'll warn Father Aereck not to let people go down there. You're an adventurer, though. If you want to, you can venture into the tomb and fight the creatures."] = "Reese logró completar el ritual con su propia muerte. Ha abierto el nivel inferior de las catacumbas, que está plagado de muertos vivientes. Sin un nigromante que las controle, las criaturas no abandonarán la tumba. Advertiré a Father Aereck que no deje que la gente baje allí. Pero eres un aventurero. Si quieres, puedes aventurarte en la tumba y luchar contra las criaturas.",
        ["*Back to previous choice menu, option 1 is replaced:*"] = "*Volver al menú de opciones anterior, se reemplaza la opción 1:*",
        ["*1. You weren't really wounded, were you?*"] = "*1. No estabas realmente herido, ¿verdad?*",
        ["Very perceptive, adventurer. I was wounded, but not as badly as I looked. I took the opportunity to see how you would fare."] = "Muy perspicaz, aventurero. Estaba herido, pero no tan mal como parecía. Aproveché la oportunidad para ver cómo te iría.",
        ["*1. You risked that woman's life for the sake of a test?*"] = "*1. ¿Arriesgaste la vida de esa mujer por una prueba?*",
        ["I was prepared to step in and rescue her if you failed. You are more than capable. The world needs heroes. I was a hero, once, but I'm not getting any younger. I need to ensure the new generation has its own heroes."] = "Estaba preparado para intervenir y rescatarla si fallabas. Eres más que capaz. El mundo necesita héroes. Una vez fui un héroe, pero no me estoy haciendo más joven. Necesito asegurarme de que la nueva generación tenga sus propios héroes.",
        ["*Back to previous options*"] = "*Volver a opciones anteriores*",
        ["*2. You risked my life for the sake of a test?*"] = "*2. ¿Arriesgaste mi vida por una prueba?*",
        ["You're a born adventurer. I can practically smell it on you. People like you have a habit of coming back from things that would kill an ordinary person."] = "Eres un aventurero nato. Prácticamente puedo olerlo en ti. La gente como tú tiene la costumbre de regresar de cosas que matarían a una persona común y corriente.",
        ["*3. So how did I do?*"] = "*3. Entonces, ¿cómo lo hice?*",
        ["Very well indeed. You're a hero. You're exactly the sort of person the world needs. I'm glad I met you."] = "Muy bien, por cierto. Eres un héroe. Eres exactamente el tipo de persona que el mundo necesita. Me alegro de haberte conocido.",
        ["*4. Back to my other questions...*"] = "*4. Volver a mis otras preguntas...*",
        ["*Back to second choice menu*"] = "*Volver al menú de segunda opción*",
        ["*2. What is a blood pact?*"] = "*2. ¿Qué es un pacto de sangre?*",
        ["It's something Zamorakian cults do sometimes; a way of swearing loyalty to their leader. A blood pact doesn't have real magic power, but that kind of thing can have great power over a person if they believe strongly enough."] = "Es algo que los cultos zamorakianos hacen a veces; una forma de jurar lealtad a su líder. Un pacto de sangre no tiene poder mágico real, pero ese tipo de cosas pueden tener un gran poder sobre una persona si cree lo suficiente.",
        ["*Back to previous options.*"] = "*Volver a opciones anteriores.*",
        ["*3. Who was Dragith Nurn?*"] = "*3. ¿Quién era Dragith Nurn?*",
        ["Dragith Nurn was a wizard. He studied at the Wizards' Tower, but he also studied the dark art, necromancy, on his own. He had a secret magical workshop beneath Lumbridge. He would steal bodies from the graveyard and perform experiments on them. Necromancy was like an addiction for him. When Xenia met him he was very troubled; very conflicted. She convinced him to put an end to it all. He couldn't destroy all the undead he had created - not permanently - so he trapped them all in the lower level of his workshop and sealed it off. He converted the upper level into these catacombs. Everyone thinks Dragith Nurn is buried here in this tomb, but he isn't. He built the tomb to hide the entrance to the lower level. Dragith Nurn is still down here. He knew that when he died he would rise again as a monster, so he sealed himself in with his creatures."] = "Dragith Nurn era un mago. Estudió en el Wizards' Tower, pero también estudió el arte oscuro, la nigromancia, por su cuenta. Tenía un taller mágico secreto debajo de Lumbridge. Robaba cuerpos del cementerio y realizaba experimentos con ellos. Necromancy era como una adicción para él. Cuando Xenia lo conoció estaba muy preocupado; muy conflictivo. Ella lo convenció para que pusiera fin a todo. No podía destruir a todos los no-muertos que había creado (no permanentemente), así que los atrapó a todos en el nivel inferior de su taller y lo selló. Convirtió el nivel superior en estas catacumbas. Todo el mundo piensa que Dragith Nurn está enterrado aquí, en esta tumba, pero no es así. Construyó la tumba para ocultar la entrada al nivel inferior. Dragith Nurn todavía está aquí abajo. Sabía que cuando muriera resucitaría como un monstruo, por lo que se selló con sus criaturas.",
        ["*4. I think I'll go now.*"] = "*4. Creo que me iré ahora.*",
        ["Farewell, adventurer."] = "Adiós, aventurero.",
        ["*Ends dialogue*"] = "*Termina el diálogo*",
        ["*2. I've lost some of the cultists' weapons.* - This option will only appear when you don't have all the cultist weapons."] = "*2. He perdido algunas de las armas de los cultistas.* - Esta opción solo aparecerá cuando no tengas todas las armas de los cultistas.",
        ["Yes, one of my contacts in the Champions' Guild found them and returned them to me."] = "Sí, uno de mis contactos en Champions' Guild los encontró y me los devolvió.",
        ["*Ilona gives all the cultist weapons you don't have*"] = "*Ilona te da todas las armas cultistas que no tienes*",
        ["*3. I've lost the Helmet of Trials.* - This option will only appear when you don't have the Helmet after claiming it once."] = "*3. He perdido el Casco de las Pruebas.* - Esta opción solo aparecerá cuando no tengas el Casco después de reclamarlo una vez.",
        ["These things happen. I've got a new one for you... You're one of the most accomplished heroes I've ever seen. You've done things I can scarcely imagine, and I've lost count of the people who owe you their lives. If there's any justice when history is written, your name will be among the greatest heroes of old. With Arrav; with Camorra; with Robert the Strong. I've talked to some people at the Legends' and Heroes' guilds, and they've created a special prize for you. Think of it as a token of recognition from the whole adventuring community."] = "Estas cosas pasan. Tengo uno nuevo para ti... Eres uno de los héroes más consumados que he visto en mi vida. Has hecho cosas que apenas puedo imaginar y he perdido la cuenta de las personas que te deben la vida. Si hay algo de justicia cuando se escribe la historia, tu nombre estará entre los más grandes héroes de la antigüedad. Con Arrav; con la Camorra; con Roberto el Fuerte. Hablé con algunas personas de los gremios de Leyendas y Héroes y crearon un premio especial para ti. Piense en ello como una muestra de reconocimiento de toda la comunidad aventurera.",
        ["*Ilona gives you an ornamental helmet*"] = "*Ilona te regala un casco ornamental*",
        ["*1. Thank you, Ilona. This is an honour.*"] = "*1. Gracias, Ilona. Esto es un honor.*",
        ["The honour is mine. You truly are an outstanding hero. I know with you on the scene, the world is in safe hands. Farewell, adventurer."] = "El honor es mío. Realmente eres un héroe excepcional. Sé que contigo en escena el mundo está en buenas manos. Adiós, aventurero.",
        ["*2. About time I got some recognition!*"] = "*2. ¡Ya era hora de que obtuviera algún reconocimiento!*",
        ["Ha ha! I see you didn't get where you are today by being humble! Well, if anyone has a right to be proud of himself/herself then it's you. I can't wait to see what you do next. Farewell, adventurer."] = "¡Ja, ja! ¡Veo que no llegaste a donde estás hoy siendo humilde! Bueno, si alguien tiene derecho a estar orgulloso de sí mismo, entonces eres tú. No puedo esperar a ver qué haces a continuación. Adiós, aventurero.",
        ["*3. I don't want your stupid helmet.*"] = "*3. No quiero tu estúpido casco.*",
        ["Oh. I just thought that... Oh, well, never mind, then."] = "Oh. Sólo pensé que... Oh, bueno, entonces no importa.",
        ["Glad you came by. I've got something for you. You're one of the most accomplished heroes I've ever seen. You've done things I can scarcely imagine, and I've lost count of the people who owe you their lives. If there is any justice when history is written, your name will be among the greatest heroes of old. With Arrav, with Camorra; with Robert the Strong. I've talked to some people at the Legends's and Heroes' guilds, and we've created a special prize for you. Think of it as a token of recognition from the whole adventuring community."] = "Me alegra que hayas venido. Tengo algo para ti. Eres uno de los héroes más consumados que he visto en mi vida. Has hecho cosas que apenas puedo imaginar y he perdido la cuenta de las personas que te deben la vida. Si hay algo de justicia cuando se escribe la historia, tu nombre estará entre los más grandes héroes de la antigüedad. Con Arrav, con Camorra; con Roberto el Fuerte. Hablé con algunas personas de los gremios de Leyendas y Héroes y hemos creado un premio especial para ti. Piense en ello como una muestra de reconocimiento de toda la comunidad aventurera.",
        ["Thank you, Xenia, This is an honour."] = "Gracias, Xenia. Es un honor.",
        ["I don't feel like i deserve this."] = "No siento que merezco esto.",
        ["I know how you feel. I've felt the same way for a lot of my adventuring career. There's always so much more to do - challenges to face, injustices to right. A hero's work is never done. Don't let that blind you to what you've already achieved though. Thinking about what you've accomplished so far can be a source of strength. Remember that. Farewell, adventurer."] = "Sé cómo te sientes. He sentido lo mismo durante gran parte de mi carrera aventurera. Siempre hay mucho más por hacer: desafíos que enfrentar, injusticias que corregir. El trabajo de un héroe nunca termina. Sin embargo, no dejes que eso te ciegue ante lo que ya has logrado. Pensar en lo que ha logrado hasta ahora puede ser una fuente de fortaleza. Recuerda eso. Adiós, aventurero.",
        ["About time I got some recognition"] = "Ya era hora de que obtuviera algún reconocimiento.",
        ["I don't want your stupid helmet."] = "No quiero tu estúpido casco.",
    },
    ["Ima"] = {
        ["Hi!"] = "¡Hola!",
        ["*Ima may say one of the following at random:*"] = "*Ima puede decir una de las siguientes palabras al azar:*",
        ["*Dialogue 1:*"] = "*Diálogo 1:*",
        ["A fight over love and money would be a duel purpose."] = "Una pelea por amor y dinero sería un duelo.",
        ["*Dialogue 2:*"] = "*Diálogo 2:*",
        ["What did the skeleton say before it ate?"] = "¿Qué dijo el esqueleto antes de comer?",
        ["I don't know."] = "No lo sé.",
        ["Bone appétit."] = "Apetito de huesos.",
        ["*Dialogue 3:*"] = "*Diálogo 3:*",
        ["My favourite fighter is Mubariz."] = "Mi luchador favorito es Mubariz.",
        ["The guy at the information kiosk?"] = "¿El chico del quiosco de información?",
        ["Yeah! He rocks!"] = "¡Sí! ¡Él es genial!",
        ["Takes all sorts, I guess."] = "Supongo que se aceptan de todo tipo.",
        ["*Dialogue 4:*"] = "*Diálogo 4:*",
        ["Did you know, they think this place dates back to the Second Age."] = "¿Sabías que creen que este lugar se remonta a la Segunda Edad?",
        ["Really?"] = "¿En serio?",
        ["Yeah, the guy at the information kiosk was telling me."] = "Sí, me lo estaba diciendo el chico del quiosco de información.",
        ["*Dialogue 5:*"] = "*Diálogo 5:*",
        ["Why do giants lose all their duels against vampires?"] = "¿Por qué los gigantes pierden todos sus duelos contra vampiros?",
        ["I don't know - why?"] = "No lo sé, ¿por qué?",
        ["The stakes are always too high!"] = "¡Siempre hay mucho en juego!",
        ["*Dialogue 6:*"] = "*Diálogo 6:*",
        ["Ooh, this is exciting."] = "Oh, esto es emocionante.",
        ["Yup!"] = "¡Sí!",
        ["*Dialogue 7:*"] = "*Diálogo 7:*",
        ["Well, this beats doing the shopping."] = "Bueno, esto es mejor que hacer compras.",
        ["*Dialogue 8:*"] = "*Diálogo 8:*",
        ["Can't you see I'm watching the duels?"] = "¿No ves que estoy viendo los duelos?",
        ["Sorry!"] = "¡Lo siento!",
        ["*Dialogue 9:*"] = "*Diálogo 9:*",
        ["*Dialogue 10:*"] = "*Diálogo 10:*",
        ["Aww, come on, keep fighting. It's just a flesh wound!"] = "Oh, vamos, sigue luchando. ¡Es sólo una herida superficial!",
        ["*Dialogue 11:*"] = "*Diálogo 11:*",
        ["My son just won his first duel!"] = "¡Mi hijo acaba de ganar su primer duelo!",
        ["Congratulations."] = "Felicitaciones.",
        ["He ripped his opponent in half."] = "Partió a su oponente por la mitad.",
        ["That's gotta hurt."] = "Eso tiene que doler.",
        ["He's only 15!"] = "¡Solo tiene 15 años!",
        ["You gotta start 'em young."] = "Tienes que empezarlos jóvenes.",
        ["*Dialogue 12:*"] = "*Diálogo 12:*",
        ["I wouldn't want to be the poor guy who has to clean up after the duels."] = "No me gustaría ser el pobre que tiene que limpiar después de los duelos.",
        ["Me neither."] = "Yo tampoco.",
        ["*Dialogue 13:*"] = "*Diálogo 13:*",
        ["Hi! I'm here to watch the duels."] = "¡Hola! Estoy aquí para ver los duelos.",
        ["Me too!"] = "¡Yo también!",
        ["*Dialogue 14:*"] = "*Diálogo 14:*",
        ["*Dialogue 15:*"] = "*Diálogo 15:*",
        ["I once duelled a man from Entrana,"] = "Una vez me batí en duelo con un hombre de Entrana,",
        ["Who wielded a mighty katana,"] = "Quien empuñaba una poderosa katana,",
        ["It caused me a fright, but it lost him the fight,"] = "Me dio un susto, pero le hizo perder la pelea,",
        ["It was made, not from steel, but banana!"] = "¡No estaba hecho de acero, sino de plátano!",
        ["*Dialogue 16:*"] = "*Diálogo 16:*",
        ["How many duellists does it take to kill a vampyre?"] = "¿Cuántos duelistas se necesitan para matar a un vampyre?",
        ["Uh, wait: I can do this. You would need thousands, because they'd all be too busy arguing ovr who gets the stake!"] = "Uh, espera: puedo hacer esto. ¡Necesitarías miles, porque estarían todos demasiado ocupados discutiendo sobre quién se queda con la apuesta!",
        ["What? No, we've got a vampyre problem back home. I was thinking of recruiting fighters."] = "¿Qué? No, tenemos un problema con vampyre en casa. Estaba pensando en reclutar combatientes.",
        ["Oh, I thought it was a joke."] = "Oh, pensé que era una broma.",
        ["Oh my! How big was that fight to have knocked down the arena?"] = "¡Dios mío! ¿Qué tan grande fue esa pelea para haber derribado la arena?",
    },
    ["Image of Lord Daquarius"] = {
        ["The Invasion of Falador has begun, much to my regret. Will you aid the Kinshra, or fight for the White Knights?"] = "La invasión de Falador ha comenzado, muy a mi pesar. ¿Ayudarás a los Kinshra o lucharás por los Caballeros Blancos?",
        ["Both sides would benefit from your aid. Join the fighting on the streets of Falador, sabotage enemy catapults, tend to the wounded, and join the search for the mythical artefacts of Raddallin. You will be commended for your efforts, and the more commendations you earn, the more you will enjoy the spoils of war. Also, that madman Party Pete will periodically drop balloons across the city. For some inexplicable reason, there are commendations in them too."] = "Ambas partes se beneficiarían de su ayuda. Únete a los combates en las calles de Falador, sabotea las catapultas enemigas, atiende a los heridos y únete a la búsqueda de los artefactos míticos de Raddallin. Serás elogiado por tus esfuerzos y cuantos más elogios obtengas, más disfrutarás del botín de guerra. Además, ese loco Party Pete lanzará globos periódicamente por toda la ciudad. Por alguna razón inexplicable, también contienen elogios.",
        ["*Collect 100 commendations from Invasion of Falador activities and convert the commendations into a supply cache.*"] = "*Recoge 100 elogios de las actividades de Invasión de Falador y conviértelos en un alijo de suministros.*",
        ["*Commendations also let you check your daily commendation cap, and configure the experience you get from Invasion of Falador activities.*"] = "*Los elogios también te permiten verificar tu límite de elogios diario y configurar la experiencia que obtienes de las actividades de Invasion of Falador.*",
        ["*Open supply caches to discover various rewards, including…*"] = "*Abre cachés de suministros para descubrir varias recompensas, incluidas...*",
        ["*Fragments of the Banner of Farradorn! (Collect and assemble to unlock a banner in the wings cosmetic override slot)*"] = "*¡Fragmentos del Estandarte de Farradorn! (Recoge y ensambla para desbloquear un estandarte en la ranura de anulación cosmética de las alas)*",
        ["*Tiny White and Black Knight pets!*"] = "*¡Pequeñas mascotas blancas y Black Knight!*",
        ["*The candyfloss maul! (Two-handed comedy weapon)*"] = "*¡El mazo de algodón de azúcar! (Arma de comedia a dos manos)*",
        ["*Plus a variety of experience lamps and resource bundles!*"] = "*¡Además de una variedad de lámparas de experiencia y paquetes de recursos!*",
        ["*Also, until the Invasion of Falador ends: the Giant Mole beneath Falador Park drops double loot the Artisan’s Workshop gives triple reputation and +50% XP*"] = "*Además, hasta que finalice la invasión de Falador: el topo gigante debajo del parque Falador arroja doble botín, el taller de Artisan otorga triple reputación y +50 % de XP*",
        ["*(Before Wanted!, The Void Stares Back and Dishonour Among Thieves)*"] = "*(¡Antes buscado!, El vacío te devuelve la mirada y Deshonra entre ladrones)*",
        ["I am the leader of the Kinshra…a Zamorakian knightly order founded in the early Fifth Age."] = "Soy el líder de Kinshra... una orden de caballeros zamorakiana fundada a principios de la Quinta Edad.",
        ["*(same as below)*"] = "*(igual que a continuación)*",
        ["*(After Wanted!, The Void Stares Back and Dishonour Among Thieves)*"] = "*(Después de ¡Se busca!, El vacío te devuelve la mirada y Deshonra entre ladrones)*",
        ["Indeed. At least thrice have I encountered you, and I doubt this shall be the last. Well met."] = "De hecho. Al menos tres veces te he encontrado y dudo que ésta sea la última. Bien conocido.",
        ["Do you think me a coward for projecting a magical image? Do you imagine that I cower in our Kinshra headquarters, safe from harm? On the contrary. I am not one to direct the battle from a safe haven. I would stand by my men and risk life and limb against our enemies. To do otherwise fills me with shame. However, I am concerned for the citizens of Falador. There are those among our order, over-eager and ambitious, who would see my presence as an opportunity to curry favour and display their might. I do not wish to inspire those that would destroy without purpose, slaughtering the innocent and looting the city that was once our home. The battle itself is a smoke screen. A distraction to occupy the White Knights while my agents work behind enemy lines to discover the artefacts of Raddallin."] = "¿Crees que soy un cobarde por proyectar una imagen mágica? ¿Te imaginas que me encojo en nuestra sede de Kinshra, a salvo de cualquier daño? De lo contrario. No soy alguien que dirija la batalla desde un refugio seguro. Apoyaría a mis hombres y arriesgaría la vida y la integridad física contra nuestros enemigos. Hacer lo contrario me llena de vergüenza. Sin embargo, estoy preocupado por los ciudadanos de Falador. Hay quienes entre nuestra orden, demasiado ansiosos y ambiciosos, verían mi presencia como una oportunidad para ganarse el favor y mostrar su poder. No deseo inspirar a aquellos que destruirían sin propósito, masacrando a inocentes y saqueando la ciudad que una vez fue nuestro hogar. La batalla en sí es una cortina de humo. Una distracción para ocupar a los Caballeros Blancos mientras mis agentes trabajan detrás de las líneas enemigas para descubrir los artefactos de Raddallin.",
        ["I am both cautious and dubious. When last the Kinshra laid siege to Falador, under my predecessor Lord Sulla, it was a bloody battle with fierce casualties. I do not wish to see its like again. There is political value internal to the Kinshra for allowing the assault, regardless of whether the relics of Raddallin exist. While I am opposed to the waste of lives on both sides, the potential gains as presented to me by my officers cannot be ignored. The military might of both factions has yet to recover from the Siege of Falador, and the White Knights have grown complacent in times of peace. Falador’s gates are held wide open, and the city guard are legendarily poorly equipped to muster a defence. A smaller force, such as the one present at this invasion, can conceal our movements long enough to distract the White Knights from our true prize…assuming the sword and banner exist at all."] = "Soy cauteloso y dudoso al mismo tiempo. La última vez que los Kinshra sitiaron Falador, bajo el mando de mi predecesor, Lord Sulla, fue una batalla sangrienta con muchas bajas. No deseo volver a ver algo parecido. Existe un valor político interno para Kinshra por permitir el asalto, independientemente de si existen o no las reliquias de Raddallin. Si bien me opongo al desperdicio de vidas en ambos lados, no se pueden ignorar los beneficios potenciales que me presentan mis oficiales. El poder militar de ambas facciones aún no se ha recuperado del asedio de Falador, y los Caballeros Blancos se han vuelto complacientes en tiempos de paz. Las puertas de Falador se mantienen abiertas de par en par y la guardia de la ciudad está legendariamente mal equipada para formar una defensa. Una fuerza más pequeña, como la presente en esta invasión, puede ocultar nuestros movimientos el tiempo suficiente para distraer a los Caballeros Blancos de nuestro verdadero premio... suponiendo que la espada y el estandarte existan.",
        ["The Kinshra were once the official defenders of the Kingdom of Asgarnia. In fact, the Kinshra order helped King Raddallin to establish Asgarnia near the dawn of the Fifth Age. Soon after the White Knights seized political supremacy in Falador, we were banished from the kingdom, and forced to live in exile as the price for our faith in Zamorak."] = "Los Kinshra alguna vez fueron los defensores oficiales del Reino de Asgarnia. De hecho, la orden Kinshra ayudó al rey Raddallin a establecer Asgarnia cerca de los albores de la Quinta Edad. Poco después de que los Caballeros Blancos tomaran la supremacía política en Falador, fuimos desterrados del reino y obligados a vivir en el exilio como precio por nuestra fe en Zamorak.",
        ["We have intercepted intelligence that the legendary Sword and Banner of Raddallin are hidden in Falador. You’ve no doubt heard the rumours, but there’s an unusual amount of evidence to suggest there’s something in it this time. If we are to claim these artefacts, now is the time to strike. I have allowed one of my officers to lead an infiltrating attack to attempt to claim the relics. They have strict orders to retreat immediately if resistance becomes too stiff, civilian casualties start to become significant, or the rumours turn out to be false."] = "Hemos interceptado información de que la legendaria Espada y Estandarte de Raddallin están ocultos en Falador. Seguramente habrás escuchado los rumores, pero hay una cantidad inusual de evidencia que sugiere que esta vez hay algo en esto. Si queremos reclamar estos artefactos, ahora es el momento de atacar. He permitido que uno de mis oficiales lidere un ataque de infiltración para intentar reclamar las reliquias. Tienen órdenes estrictas de retirarse inmediatamente si la resistencia se vuelve demasiado dura, las bajas civiles comienzan a ser significativas o los rumores resultan falsos.",
        ["The sword and banner are potent tokens of the right to rule, and would give the Kinshra the legitimacy we’ve lacked, and been keen to garner for ages."] = "La espada y el estandarte son potentes muestras del derecho a gobernar y le darían a los Kinshra la legitimidad que nos ha faltado y que hemos estado deseosos de obtener durante años.",
        ["Raddallin was the first King of Asgarnia. Lord Valzin, the founder of the Kinshra and a Varrockian nobleman, advised King Raddallin and helped the kingdom to flourish. The Sword of Raddallin was commissioned as a gift for Lord Valzin just before the burning of the Wizards’ Tower. Thanks to the exile of the Kinshra, the lost sword was never delivered to its rightful owners. Our intelligence suggests the sword has been unearthed in Falador Park. As for the banner, legend tells of an ancient artifact tied to the destiny of Falador: a banner of holy power which will direct the fate of the kingdom. So, the usual rot. The banner was last seen at the ascension of Raddallin, the first King of Farradorn. I’ve heard rumours that the banner was torn into fragments, yet our spy in the White Knight organisation assures me it remains intact. How could both be true?"] = "Raddallin fue el primer rey de Asgarnia. Lord Valzin, el fundador de Kinshra y un noble varockiano, asesoró al rey Raddallin y ayudó al reino a florecer. La Espada de Raddallin fue encargada como regalo para Lord Valzin justo antes del incendio de la Torre de los Magos. Gracias a the exile de Kinshra, la espada perdida nunca fue entregada a sus legítimos dueños. Nuestra inteligencia sugiere que la espada ha sido desenterrada en el parque Falador. En cuanto al estandarte, la leyenda habla de un antiguo artefacto ligado al destino de Falador: un estandarte de poder sagrado que dirigirá el destino del reino. Entonces, la podredumbre habitual. El estandarte fue visto por última vez en la ascensión de Raddallin, el primer rey de Farradorn. He escuchado rumores de que la pancarta fue rota en fragmentos, pero nuestro espía en la organización de los Caballeros Blancos me asegura que permanece intacta. ¿Cómo podrían ser ambas cosas ciertas?",
    },
    ["Image of Zemouregal"] = {
        ["Select an Option"] = "Selecciona una opción",
        ["What should I be doing?"] = "¿Qué debería estar haciendo?",
        ["Only a fool would come at me with a bronze sword and a backpack full of shrimp."] = "Sólo un tonto vendría hacia mí con una espada de bronce y un backpack lleno de camarones.",
        ["You'll be wanting Silverlight and the Shield of Arrav, at least."] = "Al menos querrás Silverlight y el Escudo de Arrav.",
        ["Gather provisions from Varrock and then meet me at the Palace."] = "Reúne provisiones de Varrock y luego reúnete conmigo en el Palacio.",
        ["I'll be waiting in a suitably threatening pose."] = "Estaré esperando en una pose adecuadamente amenazadora.",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["New Varrock, you mean?"] = "¿Nuevo Varrock, quieres decir?",
        ["It was Avarrocka, then Varrock, then some other names and now...New Varrock."] = "Fue Avarrocka, luego Varrock, luego algunos otros nombres y ahora... Nuevo Varrock.",
        ["New Varrock instils a feeling of hope, of a new beginning."] = "El nuevo Varrock infunde un sentimiento de esperanza, de un nuevo comienzo.",
        ["I offer exactly the opposite, of course. <br> No hope, and a terrible end."] = "Ofrezco exactamente lo contrario, por supuesto. <br> Sin esperanza y con un final terrible.",
        ["How did things get so bad?"] = "¿Cómo es que las cosas se pusieron tan mal?",
        ["Varrock was buckling under the weight of its threats."] = "Varrock estaba cediendo bajo el peso de sus amenazas.",
        ["Demons, rifts opening, corporeal beasts."] = "Demonios, apertura de fisuras, bestias corpóreas.",
        ["I made my move as the few heroes of Varrock were busy with these nuisances."] = "Hice mi movimiento ya que los pocos héroes de Varrock estaban ocupados con estas molestias.",
        ["When I came knocking, the Shield of Arrav was broken, Silverlight was lost. They were as prepared as Duke Horacio's cake."] = "Cuando llamé a la puerta, el escudo de Arrav se rompió y Silverlight se perdió. Estaban tan preparados como el pastel de Duke Horacio.",
        ["The abridged version? <br>I won."] = "¿La versión abreviada? <br>I ganó.",
        ["You're going to die."] = "Vas a morir.",
        ["Undoubtedly, undoubtedly."] = "Sin duda, sin duda.",
        ["Or, perhaps, I will choke you with a mouthful of coins, like Ozan the Thief."] = "O, tal vez, te estrangularé con un bocado de coins, como Ozan el Ladrón.",
        ["Or make your innards explode, like the Wise Old Man."] = "O haz explotar tus entrañas, como el Wise Old Man.",
        ["The possibilities are gloriously endless."] = "Las posibilidades son gloriosamente infinitas.",
        ["See you later."] = "Hasta luego.",
    },
    ["Imhapi"] = {
        ["I think I've grown numb to all the smiles I create."] = "Creo que me he vuelto insensible a todas las sonrisas que creo.",
    },
    ["Imiago"] = {
        ["You don't have anything planted in that patch. Plant something and I might agree to look after it for you."] = "No tienes nada plantado en ese parche. Planta algo y tal vez acepte cuidarlo por ti.",
        ["I want 8 poison ivy berries for that."] = "Quiero 8 hiedra venenosa berries para eso.",
        ["Thanks, maybe another time."] = "Gracias, tal vez en otro momento.",
        ["Pay 8 poison ivy berries?"] = "¿Pagar 8 hiedra venenosa berries?",
        ["Yes."] = "Sí.",
        ["That'll do nicely, [sir/madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [sir/madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
        ["The gardener is now looking after the patch for you."] = "El jardinero ahora se ocupará del parche por usted.",
        ["Yes, and don't ask again."] = "Sí, y no vuelvas a preguntar.",
        ["I don't know what you're talking about - I'm already looking after that patch for you."] = "No sé de qué estás hablando. Ya estoy cuidando ese parche por ti.",
        ["Oh sorry, I forgot."] = "Oh, lo siento, lo olvidé.",
        ["That patch is already fully grown. I don't know what you want me to do with it."] = "Ese parche ya está completamente desarrollado. No sé qué quieres que haga con él.",
        ["Choose an option:"] = "Elige una opción:",
        ["Would you look after my crops for me?"] = "¿Cuidarías mis cultivos por mí?",
        ["That patch is already fully grown! I don't know what you want me to do with it!"] = "¡Ese parche ya está completamente desarrollado! ¡No sé qué quieres que haga con él!",
        ["If you like, but I want 8 poison ivy berries for that."] = "Si quieres, pero quiero 8 hiedra venenosa berries para eso.",
        ["I'm afraid I don't have enough of those at the moment."] = "Me temo que no tengo suficientes en este momento.",
        ["Well, I'm not wasting my time for free."] = "Bueno, no voy a perder el tiempo gratis.",
        ["Select an Option"] = "Selecciona una opción",
        ["Okay, it's a deal."] = "Está bien, es un trato.",
        ["That'll do nicely, [Sir/Madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [Sir/Madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
        ["No, that's too much."] = "No, eso es demasiado.",
        ["Bittercap mushrooms can only be grown in a special patch in Morytania, near the Mort Myre swamp. There the ground is especially dank and suited to growing poisonous fungi."] = "Los hongos Bittercap solo se pueden cultivar en una zona especial en Morytania, cerca del pantano de Mort Myre. Allí el suelo es especialmente húmedo y propicio para el cultivo de hongos venenosos.",
        ["Can you stop weeding my farming patches please."] = "¿Puedes dejar de desherbar mis parcelas de cultivo, por favor?",
        ["Sure, I'll stop weeding them now."] = "Claro, dejaré de eliminarlos ahora.",
        ["Can you keep my farming patches weeded please?"] = "¿Puedes mantener mis parcelas de cultivo desyerbadas, por favor?",
        ["That shouldn't be a problem, Martin said I should give you special attention for your help with the fairies! Be sure to clear your allotment though as I don't want to interupt their growth!"] = "Eso no debería ser un problema, ¡Martin dijo que debería darte especial atención por tu ayuda con las hadas! ¡Asegúrate de limpiar tu asignación ya que no quiero interrumpir su crecimiento!",
        ["Can you sell me something?"] = "¿Puedes venderme algo?",
        ["That depends on whether I have it to sell. What is it that you're looking for?"] = "Eso depende de si lo tengo para vender. ¿Qué es lo que estás buscando?",
        ["That's all, thanks."] = "Eso es todo, gracias.",
        ["Some plant cure."] = "Alguna cura vegetal.",
        ["Plant cure, eh? I might have some put aside for myself. Tell you what, I'll sell you some plant cure for 25 gp if you like."] = "Cura vegetal, ¿eh? Quizás tenga algo reservado para mí. Te diré una cosa, te venderé una cura vegetal por 25 po si quieres.",
        ["I don't have enough money for that, I'm afraid."] = "Me temo que no tengo suficiente dinero para eso.",
        ["Yes, that sounds like a fair price."] = "Sí, parece un precio justo.",
        ["No thanks, I can get that much cheaper elsewhere."] = "No, gracias, puedo conseguirlo mucho más barato en otro sitio.",
        ["A bucket of compost."] = "Un balde de abono.",
        ["A bucket of compost, eh? I might have one spare... tell you what, I'll sell it to you for 35 gp if you like."] = "Un balde de abono, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 35 po si quieres.",
        ["A rake."] = "Un rastrillo.",
        ["A rake, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un rastrillo, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
        ["(See more items)"] = "(Ver más artículos)",
        ["A watering can"] = "una regadera",
        ["A watering can."] = "Una regadera.",
        ["A watering can, eh? I might have one spare... tell you what, I'll sell it to you for 25 gp if you like."] = "Una regadera, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 25 po si quieres.",
        ["A gardening trowel"] = "Una paleta de jardinería",
        ["A gardening trowel."] = "Una paleta de jardinería.",
        ["A gardening trowel, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Una paleta de jardín, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
        ["A seed dibber"] = "Un zambullidor de semillas",
        ["A seed dibber."] = "Un arrancador de semillas.",
        ["A seed dibber, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un zambullidor de semillas, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
        ["(See previous items)"] = "(Ver artículos anteriores)",
        ["Forget it."] = "Olvídalo.",
        ["Forget it, you don't have anything I need."] = "Olvídalo, no tienes nada que necesite.",
        ["That looks like something that you can make normal compost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of compost."] = "Parece algo con lo que se puede hacer abono normal. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de abono.",
        ["That looks like something that you can make supercompost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of supercompost."] = "Parece algo con lo que se puede hacer supercompost. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de supercompost.",
    },
    ["Immenizz"] = {
        ["Hello. So, what is this place?"] = "Hola. Entonces, ¿qué es este lugar?",
        ["This is my home, mundane human! What do you have in your pockets? Something tasty?"] = "¡Este es mi hogar, humano mundano! ¿Qué tienes en tus bolsillos? ¿Algo sabroso?",
        ["Stay out of my pockets! I don't have anything that you want."] = "¡No te metas en mis bolsillos! No tengo nada que quieras.",
        ["Ah, but do you have anything that *you* want?"] = "Ah, pero ¿tienes algo que *quieres*?",
        ["Of course I do!"] = "¡Por supuesto que sí!",
        ["Then you have something that implings want."] = "Entonces tienes algo que implica deseo.",
        ["Eh?"] = "¿Eh?",
        ["We want things you people want. They are tasty to us! The more you want them, the tastier they are!"] = "Queremos las cosas que ustedes quieren. ¡Para nosotros son deliciosos! ¡Cuanto más los quieras, más sabrosos serán!",
        ["So, you collect things that humans want? Interesting... So, what would happen if I caught an impling in a butterfly net?"] = "Entonces, ¿coleccionas cosas que los humanos quieren? Interesante... Entonces, ¿qué pasaría si atrapara un implicado en un cazamariposas?",
        ["Don't do that! That would be cruel. But chase us, yes! That is good. Implings are not easy to catch. Especially ones with really tasty food."] = "¡No hagas eso! Eso sería cruel. ¡Pero persíguenos, sí! Está bien. Los implings no son fáciles de detectar. Especialmente aquellos con comida realmente sabrosa.",
        ["So, some of these implings have things that I will really want? Hmm, maybe it would be worth my while trying to catch some."] = "Entonces, ¿algunos de estos implicados tienen cosas que realmente querré? Hmm, tal vez valdría la pena intentar atrapar algunos.",
        ["Going so soon?"] = "¿Vas tan pronto?",
        ["Yes, get me out of here!"] = "¡Sí, sáquenme de aquí!",
        ["Ah, no I'll hang around a bit longer."] = "Ah, no, me quedaré un poco más.",
        ["*(Dialogue ends)*"] = "*(Termina el diálogo)*",
        ["Where will I go if I leave?"] = "¿A dónde iré si me voy?",
        ["Back where you came from, of course!"] = "¡De donde vienes, por supuesto!",
        ["So not back to where the crop circle is now?"] = "Entonces, ¿no volver a donde está ahora el círculo de los cultivos?",
        ["The aetheric thread connecting you to your own plane leads back to the wheat field where you came from. Obviously. So you will always go back to where you came from! Don't you humans know anything?"] = "El hilo etérico que te conecta con tu propio plano te lleva de regreso al campo de trigo de donde viniste. Obviamente. ¡Así siempre volverás al lugar de donde viniste! ¿Ustedes los humanos no saben nada?",
        ["Evidently not."] = "Evidentemente no.",
        ["You wanna leave?"] = "¿Quieres irte?",
        ["Yes, Get me out of here!"] = "¡Sí, sácame de aquí!",
        ["Um, no. I'll hang around a bit longer."] = "Mmm, no. Me quedaré un poco más.",
    },
    ["Imp (2015 Easter event)"] = {
        ["All your jadinkos are belong to us."] = "Todos tus jadinkos nos pertenecen.",
        ["Give me a jadinko!"] = "¡Dame un jadinko!",
        ["Have you got a spare jadinko? I need one for Vyvyan."] = "¿Tienes un jadinko de repuesto? Necesito uno para Vyvyan.",
        ["Do I look like I carry jadinkos around?"] = "¿Parece que llevo jadinkos a todas partes?",
        ["Well, I've seen you adventurers carrying sharks around."] = "Bueno, os he visto aventureros cargando tiburones.",
        ["I was chased by a jadinko and I dropped my egg."] = "Me persiguió un jadinko y se me cayó el huevo.",
        ["It's Easter time! And that means eggs...jadinko eggs!"] = "¡Es tiempo de Pascua! Y eso significa huevos... ¡huevos jadinko!",
        ["This factory is cool! I've found so many machine parts. They're nearly as good as magic beads."] = "¡Esta fábrica es genial! He encontrado tantas piezas de máquinas. Son casi tan buenas como las cuentas mágicas.",
        ["Those Easter jadinkos are great! No wonder Vyvyan wants one."] = "¡Esos jadinkos de Pascua son geniales! No es de extrañar que Vyvyan quiera uno.",
        ["Vyvyan wants a jadinko! We should get him one."] = "¡Vyvyan quiere un jadinko! Deberíamos conseguirle uno.",
        ["Why can't I have a pet too?"] = "¿Por qué no puedo tener una mascota también?",
    },
    ["Imp"] = {
        ["All your jadinkos are belong to us."] = "Todos tus jadinkos nos pertenecen.",
        ["Give me a jadinko!"] = "¡Dame un jadinko!",
        ["Have you got a spare jadinko? I need one for Vyvyan."] = "¿Tienes un jadinko de repuesto? Necesito uno para Vyvyan.",
        ["Do I look like I carry jadinkos around?"] = "¿Parece que llevo jadinkos a todas partes?",
        ["Well, I've seen you adventurers carrying sharks around."] = "Bueno, os he visto aventureros cargando tiburones.",
        ["I was chased by a jadinko and I dropped my egg."] = "Me persiguió un jadinko y se me cayó el huevo.",
        ["It's Easter time! And that means eggs...jadinko eggs!"] = "¡Es tiempo de Pascua! Y eso significa huevos... ¡huevos jadinko!",
        ["This factory is cool! I've found so many machine parts. They're nearly as good as magic beads."] = "¡Esta fábrica es genial! He encontrado tantas piezas de máquinas. Son casi tan buenas como las cuentas mágicas.",
        ["Those Easter jadinkos are great! No wonder Vyvyan wants one."] = "¡Esos jadinkos de Pascua son geniales! No es de extrañar que Vyvyan quiera uno.",
        ["Vyvyan wants a jadinko! We should get him one."] = "¡Vyvyan quiere un jadinko! Deberíamos conseguirle uno.",
        ["Why can't I have a pet too?"] = "¿Por qué no puedo tener una mascota también?",
    },
    ["Imp-in-a-box (NPC)"] = {
        ["There ya go, guv!"] = "¡Ahí tienes, jefe!",
    },
    ["Imp-in-a-box"] = {
        ["Hey imp, can you hear me?"] = "Oye diablillo, ¿puedes oírme?",
        ["Of course I can hear ya, ya great big ape. You know, 'veres not even enuf space to swing Bob about in 'ere. How about a breather? You know, stretch me pins for a bit?"] = "Por supuesto que puedo oírte, gran simio. Ya sabes, ni siquiera hay suficiente espacio para mover a Bob aquí. ¿Qué tal un respiro? Ya sabes, ¿estirarme un poco?",
        ["No, I'm going to keep you in there."] = "No, voy a mantenerte ahí.",
        ["No, I'm going to keep you in there. I might keep you as a pet."] = "No, te dejaré ahí. Podría tenerte como mascota.",
        ["Pet!! Nah mate. I fink you'd find dat you'd be my pet!! We is not makin good pets."] = "¡¡Mascota!! No amigo. ¡Creo que descubrirías que serías mi mascota! No somos buenas mascotas.",
        ["Really? Why not?"] = "¿En serio? ¿Por qué no?",
        ["Coz...errr..."] = "Porque...errr...",
        ["We bite! Yeah we is biting and...and...er..."] = "¡Morderemos! Sí, estamos mordiendo y... y... eh...",
        ["We is fire risk! Yeah dat's it! We be burning down your housey and stealin' all ya shiny gems. Oh, and da beads!! Mmmm, beads."] = "¡Tenemos riesgo de incendio! ¡Sí, eso es todo! Quemaremos tu casa y robaremos todas tus gemas brillantes. Ah, y las cuentas!! Mmmm, cuentas.",
        ["Fire risk? How does that work?"] = "¿Riesgo de incendio? ¿Cómo funciona eso?",
        ["Is those wizzies. Dey don't like de imps so dey make us go BOOOM!!"] = "Son esos genios. No les gustan los diablillos, así que nos hacen hacer ¡¡BOOOM!!",
        ["It's not that bad."] = "No es tan malo.",
        ["It's not that bad. You've got four big windows, charming company...er..."] = "No es tan malo. Tienes cuatro ventanas grandes, una compañía encantadora... eh...",
        ["Yeah, we's love tiny, crampt space. It be magical. But I is a busy imp, innit? Dragons needin' ticklin', shiny relics needin' stealin', you know how it goes."] = "Sí, nos encantan los espacios pequeños y estrechos. Será mágico. Pero soy un diablillo ocupado, ¿no? Dragones que necesitan cosquillas, reliquias brillantes que necesitan ser robadas, ya sabes cómo va.",
        ["So, if you's know whas good for ya, you'd be lettin' me go, right?"] = "Entonces, si sabes lo que es bueno para ti, me dejarías ir, ¿verdad?",
        ["Don't I get three wishes?"] = "¿No recibo tres deseos?",
        ["Nah, mate. Dunno what you're chirpin' about."] = "No, amigo. No sé de qué estás hablando.",
        ["Well, you're a magical creature aren't you? Surely I get some wishes for capturing you, or releasing you, or something?"] = "Bueno, eres una criatura mágica, ¿no? Seguramente tengo algunos deseos de capturarte, liberarte o algo así.",
        ["I'm finking dat you be a bit confoosed. I is an imp, not some namby-pamby genie or some kinda fairy. Ye can tell by the horns."] = "Supongo que estás un poco confundido. Soy un diablillo, no un genio tonto o una especie de hada. Se nota por los cuernos.",
        ["Sayin' dat, I don't fancy being cooped up like one of me uncle's pigeons. Tell you what, is there anything you need deliverin' to the bank? I may not be no cunjerer or sommink like dat, but I can get about nice"] = "Dicho esto, no me gusta estar encerrado como una de las palomas de mi tío. ¿Hay algo que necesites entregar al banco? Puede que no sea un cunjerer o un sommink como ese, pero puedo comportarme bien",
        ["an quick like. If you let me scarper, I'll take a couple of fings to the bank for ya. You game?"] = "un me gusta rápido. Si me dejas escapar, llevaré un par de dólares al banco por ti. ¿Tu juego?",
        ["Okay, that sounds fair."] = "Vale, eso suena justo.",
        ["Surely it should be three items?"] = "¿Seguramente deberían ser tres elementos?",
        ["Surely it should be three items? Then it's one item per wish."] = "¿Seguramente deberían ser tres elementos? Entonces es un artículo por deseo.",
        ["I've already told ya, I ain't no bloomin' fairy. Besides, you know wot dey say, three's a crowd innit? I don't fink I can hop about carryin' more dan 2 fings."] = "Ya te lo dije, no soy un hada. Además, ¿sabes lo que dicen: tres son muchos, verdad? No creo que pueda andar cargando más de dos dedos.",
        ["I've got nothing I need banking right now."] = "No tengo nada que necesite en el banco en este momento.",
        ["Great, just blinkin great, dat is. I'll just sit about countin' zombie sheep then. One...two...two and a bit...three and a bit more... I don't fink sheep 'ave dat many legs..."] = "Genial, simplemente parpadea, genial, eso es. Entonces me sentaré a contar ovejas zombis. Uno...dos...dos y un poco...tres y un poco más... No creo que las ovejas tengan tantas patas...",
        ["Hey imp, are you still there?"] = "Oye diablillo, ¿todavía estás ahí?",
        ["An who's fault is that, eh? EH? I got betta fings to do dan sit ere waitin' for ya. 'Ave ya made up ya mind what else I'm luggin about?"] = "¿Y de quién es la culpa, eh? ¿EH? Tengo mejores dedos que hacer y sentarme aquí esperándote. ¿Ya has decidido de qué más estoy hablando?",
        ["Yes I have."] = "Sí, lo he hecho.",
        ["No, I'm afraid you're going to have to wait a bit longer."] = "No, me temo que tendrás que esperar un poco más.",
        ["Dat's alright guv'nor. I'll get back to me luvverly dream about beads. Big shiny beads. Love it!"] = "Eso está bien, jefe. Volveré a contarme cómo sueñas con las cuentas. Grandes cuentas brillantes. ¡Me encanta!",
        ["Sorry, guv'nor, I seem to 'ave caught meself; I can't do nuffink right now."] = "Lo siento, jefe, parece que me he pillado; No puedo hacer tonterías ahora.",
        ["What use would that be in a bank? You'd be better off leaving it in yer house."] = "¿De qué serviría eso en un banco? Será mejor que lo dejes en tu casa.",
        ["Ow! That's hot! Put it in yer bank yerself!"] = "¡Ay! ¡Eso está caliente! ¡Ponlo tú mismo en tu banco!",
        ["No way, I can't bank your looting bag."] = "De ninguna manera, no puedo guardar tu bolsa de botín.",
        ["Nope, between me and you, that toad doesn't look stable."] = "No, entre tú y yo, ese sapo no parece estable.",
        ["What good is banking that book? Just read it or throw it away!"] = "¿De qué sirve guardar ese libro en el banco? ¡Solo léelo o tíralo!",
        ["I'm no expert, but when a mushroom glows that much, I'm guessing it's dangerous. Keep it away from me."] = "No soy un experto, pero cuando un hongo brilla tanto, supongo que es peligroso. Mantenlo alejado de mí.",
        ["I'm not touching a gnome ball; that's a vicious game! I might die!"] = "No voy a tocar una bola de gnomo; ¡Ese es un juego cruel! ¡Podría morir!",
        ["Don't you know? You can get into trouble for giving alcohol to minors, and I'm pretty small, it has to be said."] = "¿No lo sabes? Te puedes meter en líos por darle alcohol a menores, y yo soy bastante pequeña, todo hay que decirlo.",
        ["There's something weird about those bones; I ain't touching them."] = "Hay algo raro en esos huesos; No los voy a tocar.",
        ["It's a flipping stick; why bother banking that? You humans are crazy sometimes."] = "Es un palo giratorio; ¿Por qué molestarse en depositar eso? Ustedes los humanos a veces están locos.",
        ["I know what lamps like that contain; I'm not touching it. I might get hurt."] = "Sé lo que contienen lámparas como esa; No lo voy a tocar. Podría resultar herido.",
        ["Sorry, I'm not going to risk upsetting someone by bundling random holy symbols I don't recognise into bank vaults."] = "Lo siento, no voy a arriesgarme a molestar a alguien agrupando símbolos sagrados aleatorios que no reconozco en las bóvedas de los bancos.",
        ["Hey, if she wants to use the bank, why can't she use her own two legs? Besides, she's too big."] = "Oye, si quiere usar el banco, ¿por qué no puede usar sus propias piernas? Además, ella es demasiado grande.",
    },
    ["Imperial district musician"] = {
        ["Select an option"] = "Seleccione una opción",
        ["Who are you?"] = "¿Quién eres?",
        ["Me? I'm a musician! Let me help you relax: sit down, rest your weary limbs and allow me to wash away the troubles of the day. After a long trek, what could be better than some music to give you the energy to continue? Did you know music has curative properties? Music stimulates the healing humours in your body, so they say."] = "¿Yo? ¡Soy músico! Déjame ayudarte a relajarte: siéntate, descansa tus miembros cansados ​​y permíteme eliminar los problemas del día. Después de un largo viaje, ¿qué mejor que un poco de música para darte energía para continuar? ¿Sabías que la música tiene propiedades curativas? La música estimula los humores curativos del cuerpo, según dicen.",
        ["Who says that, then?"] = "¿Quién dice eso entonces?",
        ["I was told by a travelling medical practitioner, selling oil extracted from snakes. It's a commonly known fact, so he said. After resting to some music, you will be able to run longer and your life points will increase noticeably. A panacea, if you will. Ah, the power of music."] = "Me lo contó un médico que viajaba y vendía aceite extraído de serpientes. Es un hecho comúnmente conocido, dijo. Después de descansar con un poco de música, podrás correr más tiempo y tus puntos de vida aumentarán notablemente. Una panacea, por así decirlo. Ah, el poder de la música.",
        ["So, just listening to some music will cure me of all my ills?"] = "Entonces, ¿solo escuchar un poco de música me curará de todos mis males?",
        ["Well, not quite. Poison, lack of faith and dismembered limbs are all a bit beyond even the most rousing of harmonies, but I guarantee you will feel refreshed, and better equipped to take on the challenges of the day."] = "Bueno, no del todo. El veneno, la falta de fe y los miembros desmembrados están un poco más allá incluso de las armonías más conmovedoras, pero te garantizo que te sentirás renovado y mejor equipado para afrontar los desafíos del día.",
        ["Does this cost me anything?"] = "¿Esto me cuesta algo?",
        ["Oh, no! My reward is the pleasure I bring to the masses. Just remember me and tell your friends, and that is payment enough. So sit down and enjoy!"] = "¡Oh, no! Mi recompensa es el placer que brindo a las masas. Sólo recuérdame y díselo a tus amigos, y eso es pago suficiente. ¡Así que siéntate y disfruta!",
        ["Can I ask you some questions about resting?"] = "¿Puedo hacerte algunas preguntas sobre el descanso?",
        ["How does resting work?"] = "¿Cómo funciona el descanso?",
        ["Have you ever been on a long journey, and simply wanted to have a rest? When you're running from city to city, it's so easy to run out of breath, don't you find?"] = "¿Alguna vez has estado en un viaje largo y simplemente quisiste descansar? Cuando corres de ciudad en ciudad, es muy fácil quedarte sin aliento, ¿no te parece?",
        ["Yes, I can never run as far as I'd like."] = "Sí, nunca puedo correr tan lejos como quisiera.",
        ["Well, you may rest anywhere, simply choose the Rest option on the run buttons. When you rest, you will sit on the floor. When you are nice and relaxed, you will recharge your run energy more quickly and your life points twice as fast as you would do normally. Of course, you can't do anything else while you're resting, other than talk."] = "Bueno, puedes descansar en cualquier lugar, simplemente elige la opción Descanso en los botones de ejecución. Cuando descanses, te sentarás en el suelo. Cuando estés agradable y relajado, recargarás tu energía de carrera más rápidamente y tus puntos de vida dos veces más rápido de lo que lo harías normalmente. Por supuesto, mientras descansas no puedes hacer nada más que hablar.",
        ["Why not?"] = "¿Por qué no?",
        ["Well, you wouldn't be resting, now would you? Also, you should know that resting by a musician, has a similar effect but the benefits are greater."] = "Bueno, no estarías descansando, ¿verdad? Además, debes saber que el descanso junto a un músico, tiene un efecto similar pero los beneficios son mayores.",
        ["What's special about resting by a musician?"] = "¿Qué tiene de especial el descanso de un músico?",
        ["The effects of resting are enhanced by music. Your run energy will recharge many times the normal rate, and your life points three times as fast. Simply sit down and rest as you would normally, nice and close to the musician. You'll turn to face the musician and hear the music. Like resting anywhere, if you do anything other than talk, you will stop resting."] = "Los efectos del descanso se potencian con la música. Tu energía de carrera se recargará muchas veces más rápido que lo normal y tus puntos de vida tres veces más rápido. Simplemente siéntate y descansa como lo harías normalmente, agradable y cerca del músico. Te volverás hacia el músico y escucharás la música. Como descansar en cualquier lugar, si haces algo más que hablar, dejarás de descansar.",
        ["Can you summarise the effects for me?"] = "¿Puedes resumirme los efectos?",
        ["Certainly. You can rest anywhere, simply choose the Rest option on the run buttons. Resting anywhere will replenish your run energy more quickly than normal, your life points will replenish twice as fast as well! Resting by a musician will replenish your run energy many times faster than normal, and your life points will also replenish three times as fast."] = "Por supuesto. Puedes descansar en cualquier lugar, simplemente elige la opción Descanso en los botones de ejecución. Descansar en cualquier lugar repondrá tu energía para correr más rápido de lo normal, ¡y tus puntos de vida también se repondrán el doble de rápido! Descansar junto a un músico repondrá tu energía de carrera muchas veces más rápido de lo normal, y tus puntos de vida también se repondrán tres veces más rápido.",
        ["That's all for now."] = "Eso es todo por ahora.",
        ["Can I ask you some questions about running?"] = "¿Puedo hacerte algunas preguntas sobre correr?",
        ["Running? Of course! Not that I do much running, I prefer to saunter. But you adventuring types always seem to be in a rush, zipping hither and thither."] = "¿Corriendo? ¡Por supuesto! No es que corro mucho, prefiero pasear. Pero ustedes, los aventureros, siempre parecen tener prisa, yendo de aquí para allá.",
        ["Why do I need to run anyway?"] = "¿Por qué necesito ejecutar de todos modos?",
        ["Running is the simplest way to get somewhere quickly. When you run you move twice as fast as you normally would. Also, you don't look like the cowardly type, but most creatures can't run very fast, so if you don't want to fight, you can always run away."] = "Correr es la forma más sencilla de llegar rápidamente a algún lugar. Cuando corres, te mueves el doble de rápido de lo que lo harías normalmente. Además, no pareces del tipo cobarde, pero la mayoría de las criaturas no pueden correr muy rápido, así que si no quieres pelear, siempre puedes huir.",
        ["Can I keep running forever?"] = "¿Puedo seguir corriendo para siempre?",
        ["No, eventually you'll get tired. When that happens you will stop running, and start walking. It takes a while to get your breath back, but once you've recovered a little, you can start running again. You recover quickly whilst resting, or more slowly whilst walking."] = "No, eventualmente te cansarás. Cuando eso suceda, dejarás de correr y empezarás a caminar. Te llevará un tiempo recuperar el aliento, pero una vez que te hayas recuperado un poco, podrás empezar a correr de nuevo. Te recuperas rápidamente mientras descansas o más lentamente mientras caminas.",
        ["That's all for now. {{anchor|thats-all-for-now}}"] = "Eso es todo por ahora. {{anchor|thats-all-for-now}}",
        ["Well, don't forget to have a rest every now and again."] = "Bueno, no olvides descansar de vez en cuando.",
    },
    ["Impling collector"] = {
        ["Have you seen any implings around here?"] = "¿Has visto algún implícito por aquí?",
        ["I haven't."] = "No lo he hecho.",
        ["That's a shame. I hear if you work hard in Menaphos you'll start to find more of them."] = "Es una pena. He oído que si trabajas duro en Menaphos empezarás a encontrar más de ellos.",
        ["Reaching tier 4 in Menaphos city reputation will unlock a chance to roll for implings and Guthix butterflies while skilling in Menaphos."] = "Alcanzar el nivel 4 en la reputación de la ciudad de Menaphos desbloqueará la oportunidad de realizar tiradas para implings y mariposas Guthix mientras desarrollas habilidades en Menaphos.",
        ["Yeah, I keep seeing them while I work round the city."] = "Sí, los sigo viendo mientras trabajo por la ciudad.",
        ["Of course! If you disrupt their environment they're bound to appear. Sometimes you don't find the ones you're looking for though - if you're interested I could teach you how to stop those implings and butterflies noticing you?"] = "¡Por supuesto! Si perturbas su entorno, es probable que aparezcan. Sin embargo, a veces no encuentras los que estás buscando. Si estás interesado, ¿podría enseñarte cómo evitar que esos implícitos y mariposas se fijen en ti?",
        ["Toggle impling and butterfly settings?"] = "¿Alternar la configuración de implícita y mariposa?",
        ["Yes."] = "Sí.",
        ["*(Gathering Settings opens)*"] = "*(Se abre la configuración de reunión)*",
        ["Okay, see you around."] = "Está bien, nos vemos.",
    },
    ["Imre"] = {
        ["*One of the following dialogues plays at random:*"] = "*Uno de los siguientes diálogos se reproduce aleatoriamente:*",
        ["*Dialogue 1*"] = "*Diálogo 1*",
        ["Out of my way, punk."] = "Fuera de mi camino, punk.",
        ["*Dialogue 2*"] = "*Diálogo 2*",
        ["I have no interest in talking to a pathetic meat bag like yourself."] = "No tengo ningún interés en hablar con un patético bolsa de carne como tú.",
        ["*Dialogue 3*"] = "*Diálogo 3*",
        ["If I were as ugly as you I would not dare to show my face in public!"] = "¡Si fuera tan feo como tú no me atrevería a mostrar mi cara en público!",
        ["*Dialogue 4*"] = "*Diálogo 4*",
        ["Hmm... you smell strange..."] = "Hmm... hueles raro...",
        ["Strange how?"] = "¿Qué extraño cómo?",
        ["Like a human!"] = "¡Como un humano!",
        ["Oh! Er... I just ate one is why!"] = "¡Oh! Er... ¡acabo de comer uno, por eso!",
        ["*Dialogue 5*"] = "*Diálogo 5*",
        ["Get lost!"] = "¡Piérdete!",
        ["*Dialogue 6*"] = "*Diálogo 6*",
        ["Leave me alone."] = "Déjame en paz.",
        ["*Dialogue 7*"] = "*Diálogo 7*",
        ["Have you no manners?"] = "¿No tienes modales?",
        ["*Dialogue 8*"] = "*Diálogo 8*",
        ["I don't have anything to give you so leave me alone, mendicant."] = "No tengo nada que darte así que déjame en paz, mendigo.",
        ["*Dialogue 9*"] = "*Diálogo 9*",
        ["I don't have time for this right now."] = "No tengo tiempo para esto ahora.",
        ["*Dialogue 10*"] = "*Diálogo 10*",
        ["Don't talk to me again if you value your life!"] = "¡No vuelvas a hablarme si valoras tu vida!",
        ["I might try my hand at farming onions some time."] = "Podría intentar cultivar cebollas en algún momento.",
        ["I may be a werewolf, but I do love the smell of frying onions."] = "Puede que sea un hombre lobo, pero me encanta el olor de las cebollas fritas.",
        ["People are like onions. They have lots of layers and sometimes smell quite pungent."] = "Las personas son como las cebollas. Tienen muchas capas y a veces huelen bastante picante.",
        ["Did you know that the onion is of genus Allium and species cepa?"] = "¿Sabías que la cebolla es del género Allium y especie cepa?",
        ["Maybe I'll start an Onion Guild."] = "Tal vez inicie un Onion Guild.",
        ["Down with rutabagas!"] = "¡Abajo los colinabos!",
        ["When you cut onions, they release a gas that makes you cry."] = "Cuando cortas cebollas, liberan un gas que te hace llorar.",
        ["If you hear an onion ring, answer it!"] = "Si escuchas un aro de cebolla, ¡responde!",
        ["Life is like an onion... well, sort of."] = "La vida es como una cebolla... bueno, más o menos.",
        ["Onion skins very thin, mild winter coming in. Onion skins very rough, coming winter very tough."] = "La piel de la cebolla es muy fina, se acerca el invierno suave. La piel de la cebolla es muy áspera, el invierno se acerca muy duro.",
    },
    ["Inanna"] = {
        ["Greetings, Player."] = "Saludos, Player.",
        ["Select an Option"] = "Selecciona una opción",
        ["Ask about Amberfell."] = "Pregunte por Amberfell.",
        ["How is Amberfell faring?"] = "¿Cómo le está yendo a Amberfell?",
        ["For now, it is well."] = "Por ahora, todo está bien.",
        ["I remain close to reassure them. While I am here, they are safe."] = "Permanezco cerca para tranquilizarlos. Mientras estoy aquí, ellos están a salvo.",
        ["Sorrel's transgressions have been forgiven and the bonds to Wendlewick have been mended. They are all stronger for it."] = "Las transgresiones de Sorrel han sido perdonadas y los vínculos con Wendlewick han sido reparados. Todos son más fuertes por eso.",
        ["Ask about the Sanguine."] = "Pregunta por el Sanguine.",
        ["Has the Sanguine spread closer?"] = "¿Se ha extendido más el Sanguine?",
        ["Yes. Each day, it consumes more of the east."] = "Sí. Cada día consume más del este.",
        ["The monsters that attacked us at the temple were a vanguard. A sign of what is to come."] = "Los monstruos que nos atacaron en el templo eran una vanguardia. Una señal de lo que está por venir.",
        ["Amberfell itself is safe for now. We will have to take the fight east soon, though, if we are to survive."] = "Amberfell en sí está a salvo por ahora. Sin embargo, pronto tendremos que luchar hacia el este si queremos sobrevivir.",
        ["Ask about the Moonrise temple."] = "Pregunta por el templo Moonrise.",
        ["What can you tell me about the temple to the north of here?"] = "¿Qué puedes decirme sobre el templo al norte de aquí?",
        ["It is called Moonrise."] = "Se llama Salida de la Luna.",
        ["Once, long ago, it was a site of great power. This was before I came to be. I do not know what it hides."] = "Una vez, hace mucho tiempo, fue un sitio de gran poder. Esto fue antes de que yo naciera. No sé qué esconde.",
        ["I seldom travel there myself. It is watched over by another. One I wish to avoid."] = "Yo rara vez viajo allí. Está vigilado por otro. Uno que deseo evitar.",
        ["Perhaps it will soon reveal its secrets to you."] = "Quizás pronto te revele sus secretos.",
        ["Attempt to pet."] = "Intenta acariciar.",
        ["May I?"] = "¿Puedo?",
        ["You may."] = "Puedes.",
        ["Briefly."] = "Brevemente.",
        ["You have my trust, Player. Do not squander it."] = "Tienes mi confianza, Player. No lo desperdicies.",
        ["Goodbye."] = "Adiós.",
        ["May the moonlight favour you."] = "Que la luz de la luna te favorezca.",
        ["Introduce Anzagar."] = "Presenta a Anzagar.",
        ["I thought you might like to meet Anzagar."] = "Pensé que te gustaría conocer a Anzagar.",
        ["I sensed it. But I could scarcely believe it."] = "Lo sentí. Pero apenas podía creerlo.",
        ["My brother has been freed from his eternal torment. You have succeeded where I never could."] = "Mi hermano ha sido liberado de su tormento eterno. Has tenido éxito donde yo nunca pude.",
        ["Thank you, my friend."] = "Gracias, amigo mío.",
        ["Your fate is a blessed one, little Anzagar. You will grow to be a mighty colossus one day."] = "Tu destino es bendito, pequeño Anzagar. Algún día te convertirás en un poderoso coloso.",
        ["He spoke!"] = "¡Habló!",
        ["He is rather fond of you and the adventures you have shared, I see. Do not squander this trust. For a colossus' favour is precious beyond measure."] = "Veo que le tienes bastante cariño y las aventuras que habéis compartido. No desperdicies esta confianza. Porque el favor de un coloso es precioso sin medida.",
        ["Go now, with my blessing. And may moonlight forever guide your path."] = "Ve ahora, con mi bendición. Y que la luz de la luna guíe por siempre tu camino.",
    },
    ["Information clerk"] = {
        ["Welcome to Varrock Museum. How can I help you today?"] = "Bienvenido al Museo Varrock. ¿Cómo puedo ayudarte hoy?",
        ["Take a map of the Museum."] = "Tome un mapa del Museo.",
        ["[You reach and take a map of the Museum.]"] = "[Llegas y tomas un mapa del Museo.]",
        ["Find out about the Dig Site exhibit."] = "Obtenga más información sobre la exposición Dig Site.",
        ["Could you tell me about the Dig Site exhibit please?"] = "¿Podría hablarme sobre la exhibición Dig Site, por favor?",
        ["Of course. The Dig Site exhibit has several display cases of finds discovered on the Dig Site to the east of Varrock."] = "Por supuesto. La exhibición Dig Site tiene varias vitrinas de hallazgos descubiertos en Dig Site al este de Varrock.",
        ["As you are on a free world, you can't help us with cleaning finds and putting them in their display cases, but do feel free to take a look around at the displays available. You'll find out a little about the things we've found on the Dig"] = "Como estás en un mundo libre, no puedes ayudarnos a limpiar los hallazgos y colocarlos en sus vitrinas, pero siéntete libre de echar un vistazo a las exhibiciones disponibles. Descubrirás un poco sobre las cosas que hemos encontrado en la Excavación.",
        ["Site from the 3rd and 4th Ages - all really quite interesting."] = "Sitio de la Tercera y Cuarta Edad: todo realmente muy interesante.",
        ["Unfortunately, you haven't passed your Earth Science exams, so you aren't qualified to help us on the dig. If you're interested, visit the Education Centre on the Dig Site to the east and talk to the examiners there."] = "Desafortunadamente, no has aprobado tus exámenes de Ciencias de la Tierra, por lo que no estás calificado para ayudarnos en la excavación. Si está interesado, visite el Centro educativo en el sitio de excavación hacia el este y hable con los examinadores allí.",
        ["As you've passed your Earth Science exams at the Dig Site, you can go through into the cleaning area and clean off some finds. This will help our Dig Site display floor to give a more accurate view of life back in the 3rd and 4th Ages, as well as earning you Kudos. If you'd like to know more about cleaning finds, just ask the archaeologists."] = "Una vez que hayas aprobado tus exámenes de Ciencias de la Tierra en el sitio de excavación, puedes pasar al área de limpieza y limpiar algunos hallazgos. Esto ayudará a que nuestro piso de exhibición del Sitio de Excavación brinde una visión más precisa de la vida en la Tercera y Cuarta Edad, además de otorgarle Felicitaciones. Si desea saber más sobre la limpieza de hallazgos, pregúntele a los arqueólogos.",
        ["I see you've already helped out in the Dig Site exhibit. Our picture of life back in the 3rd and 4th Ages in that old city is really becoming clearer. There are still a few displays that need updating, though. If you'd like to know more about cleaning finds, just ask the archaeologists."] = "Veo que ya ayudaste en la exhibición del sitio de excavación. Nuestra imagen de la vida en la Tercera y Cuarta Edad en esa antigua ciudad se está volviendo cada vez más clara. Sin embargo, todavía hay algunas pantallas que necesitan actualización. Si desea saber más sobre la limpieza de hallazgos, pregúntele a los arqueólogos.",
        ["You have really helped out a lot. I see all the nice clean finds with their information are in the once empty cases. I'm sure we'll get some more cases in soon for you to fill. For now, perhaps you should investigate the rest of the"] = "Realmente has ayudado mucho. Veo que todos los hallazgos limpios y agradables con su información están en las cajas que alguna vez estuvieron vacías. Estoy seguro de que pronto recibiremos más casos para que usted los complete. Por ahora, tal vez deberías investigar el resto del",
        ["Museum."] = "Museo.",
        ["Ask about something else."] = "Pregunta por otra cosa.",
        ["Bye"] = "Adiós",
        ["Bye."] = "Adiós.",
        ["Have a good day!"] = "¡Que tengas un buen día!",
        ["Find out about the Timeline exhibit."] = "Obtenga más información sobre la exposición Timeline.",
        ["Could you tell me about the Timeline exhibit please?"] = "¿Podría hablarme sobre la exposición Timeline, por favor?",
        ["Why, yes. The Timeline exhibit has lots of display cases showing things from the beginning of time right up to the present day."] = "Pues, sí. La exhibición Timeline tiene muchas vitrinas que muestran cosas desde el principio de los tiempos hasta el día de hoy.",
        ["You could help out in the Timeline exhibit upstairs. By providing information you may have gathered on your travels around the world, you can help to make our displays more comprehensive and earn yourself Kudos too."] = "Podrías ayudar en la exhibición Timeline de arriba. Al proporcionar información que haya recopilado en sus viajes por el mundo, puede ayudar a que nuestras presentaciones sean más completas y también ganarse elogios.",
        ["I know you've helped out a bit in the Timeline exhibit upstairs, but I'm sure you can help more. When you're out on your travels being a brave adventurer, remember that you can come back to the Museum after some quests to"] = "Sé que has ayudado un poco en la exposición Timeline de arriba, pero estoy seguro de que puedes ayudar más. Cuando viajes siendo un valiente aventurero, recuerda que puedes regresar al Museo después de algunas misiones para",
        ["let us know important historical facts. This will help us to update the displays and make the Museum a more informative place! You'll earn yourself Kudos too."] = "háganos saber hechos históricos importantes. ¡Esto nos ayudará a actualizar las exhibiciones y hacer del Museo un lugar más informativo! Tú también te ganarás felicitaciones.",
        ["I see you have filled up the display cases we have, and given us large amounts of information for the Timeline exhibit. At the moment, you have left us nothing to do ourselves, but I'm sure we'll be getting some new cases in soon for you to help us out with! For now, perhaps you should investigate the rest of the Museum."] = "Veo que has llenado las vitrinas que tenemos y nos has proporcionado una gran cantidad de información para la exposición Timeline. Por el momento, no nos has dejado nada que hacer nosotros mismos, pero estoy seguro de que pronto recibiremos algunos casos nuevos con los que podrás ayudarnos. Por ahora, quizás deberías investigar el resto del Museo.",
        ["Okay, thanks. One more question: why are the display numbers all out of sequence?"] = "Está bien, gracias. Una pregunta más: ¿por qué todos los números de la pantalla están fuera de secuencia?",
        ["Ahh, that's due to the numbering being done as we were constructing the cases and putting the displays in them, then shuffling them into the right places. We thought rather than renumbering them all - such a boring job,"] = "Ahh, eso se debe a que la numeración se realizó mientras construíamos las cajas y colocamos las pantallas en ellas, y luego las ordenábamos en los lugares correctos. Pensamos que en lugar de volver a numerarlos todos -un trabajo tan aburrido,",
        ["writing labels - we'd leave it. They all have unique numbers and future displays would mess up the consecutive numbering anyway."] = "escribir etiquetas: lo dejaríamos. Todos tienen números únicos y, de todos modos, visualizaciones futuras estropearían la numeración consecutiva.",
        ["Ahhh, I see."] = "Ahhh, ya veo.",
        ["Find out about the Natural History exhibit."] = "Infórmate sobre la exposición de Historia Natural.",
        ["Could you tell me about the Natural History exhibit please?"] = "¿Podría hablarme sobre la exhibición de Historia Natural, por favor?",
        ["Why, yes. The Natural History exhibit has displays of various creatures you can find around Gielinor."] = "Pues, sí. La exhibición de Historia Natural tiene exhibiciones de varias criaturas que puedes encontrar alrededor de Gielinor.",
        ["Downstairs, in the Natural History exhibit, you can answer quizzes about animals to show us your knowledge and earn Kudos at the same time. Talk to Orlando, I'm sure he'd appreciate your knowledge."] = "Abajo, en la exhibición de Historia Natural, puedes responder cuestionarios sobre animales para mostrarnos tus conocimientos y ganar felicitaciones al mismo tiempo. Habla con Orlando, estoy seguro de que apreciará tus conocimientos.",
        ["I see you have already demonstrated some of your knowledge of the natural world in the Natural History exhibit, so why not pop down and do some more quizzes with Orlando! You can earn Kudos at the same time."] = "Veo que ya has demostrado algunos de tus conocimientos del mundo natural en la exposición de Historia Natural, así que ¿por qué no vienes y haces más pruebas con Orlando? Puedes ganar Kudos al mismo tiempo.",
        ["You really know your stuff when it comes to animals, don't you! Orlando tells me you have exceeded his teachings. For now, perhaps you should investigate the rest of the Museum."] = "Realmente sabes lo que haces cuando se trata de animales, ¿no? Orlando me dice que has excedido sus enseñanzas. Por ahora, quizás deberías investigar el resto del Museo.",
        ["Select an Option"] = "Selecciona una opción",
        ["But what's Natural History got to do with existing animals?"] = "Pero ¿qué tiene que ver la Historia Natural con los animales existentes?",
        ["But what's natural history got to do with existing animals?"] = "¿Pero qué tiene que ver la historia natural con los animales existentes?",
        ["The study of natural history is simply the study of the history of the species. The species doesn't necessarily need to be an extinct one."] = "El estudio de la historia natural es simplemente el estudio de la historia de las especies. No es necesario que la especie esté extinta.",
        ["Find out about Kudos."] = "Infórmese sobre Felicitaciones.",
        ["Find out about kudos"] = "Descubra las felicitaciones",
        ["Kudos is a measure of how much you've assisted the Museum. The more information you give us, Dig Site finds that you clean and quizzes you solve, the higher your Kudos."] = "Felicitaciones es una medida de cuánto has ayudado al Museo. Cuanta más información nos brindes, Dig Site encuentre lo que limpies y los cuestionarios que resuelvas, mayores serán tus felicitaciones.",
        ["But what's it for?"] = "¿Pero para qué sirve?",
        ["Well, recently we found a rather interesting island to the north of Morytania. We believe that it may be of archaeological significance. I suspect we'll be looking for qualified archaeologists once we have constructed our"] = "Bueno, recientemente encontramos una isla bastante interesante al norte de Morytania. Creemos que puede tener importancia arqueológica. Sospecho que buscaremos arqueólogos calificados una vez que hayamos construido nuestro",
        ["canal and barge. So, we're using Kudos as a measure of who is willing and able to help us here at the Museum, so they can then be invited on our dig on the new island."] = "canal y barcaza. Entonces, estamos usando Felicitaciones como una medida de quién está dispuesto y es capaz de ayudarnos aquí en el Museo, para que luego puedan ser invitados a nuestra excavación en la nueva isla.",
        ["Would I qualify, then?"] = "¿Calificaría entonces?",
        ["Unfortunately, you haven't earned enough Kudos yet, so you aren't qualified to help us on the dig. If you're interested in helping us out and getting that Kudos, simply help out around the Museum."] = "Desafortunadamente, aún no has obtenido suficientes felicitaciones, por lo que no estás calificado para ayudarnos en la excavación. Si está interesado en ayudarnos y recibir felicitaciones, simplemente ayúdenos en el museo.",
        ["Okay, thanks."] = "Está bien, gracias.",
        ["Why yes! You've helped us so much around the Museum and you have the necessary qualifications from the Earth Sciences exams you took. When the canal is ready, we'll let you know."] = "¡Por qué sí! Nos has ayudado mucho en el Museo y tienes las calificaciones necesarias de los exámenes de Ciencias de la Tierra que tomaste. Cuando el canal esté listo, se lo haremos saber.",
        ["Thank you, I'll look forward to it!"] = "¡Gracias, lo espero con ansias!",
        ["How can I earn more kudos?"] = "¿Cómo puedo ganar más felicitaciones?",
        ["Hmm, let me see, I've got this written down somewhere..."] = "Hmm, déjame ver, tengo esto escrito en alguna parte...",
        ["[The Information clerk hands you a sheet of paper.]"] = "[El Information clerk te entrega una hoja de papel.]",
        ["Ohh, hello there, I see from our records that you've helped us out a bit. My father knew an awful lot about all sorts like Mining, Crafting and such, and he passed his tricks on to me... would you like me to share?"] = "Ohh, hola. Veo por nuestros registros que nos has ayudado un poco. Mi padre sabía muchísimo sobre todo tipo de Mining, Crafting y demás, y me pasó sus trucos... ¿te gustaría que te los comparta?",
        ["Yes"] = "si",
        ["Yes."] = "Sí.",
        ["[You feel more knowledgeable in the skills Crafting, Smithing, Slayer, Prayer and Hunter.]"] = "[Te sientes más conocedor de las habilidades Crafting, Smithing, Slayer, Prayer y Hunter.]",
        ["Wow, thanks."] = "Vaya, gracias.",
        ["You're most welcome. Now, is there anything else I can help you with?"] = "De nada. Ahora bien, ¿hay algo más en lo que pueda ayudarte?",
        ["I'll come back later."] = "Volveré más tarde.",
        ["Okay!"] = "¡Está bien!",
    },
    ["Inga"] = {
        ["I cannot speak to you outerlander! Talk to Brundt, the Chieftain!"] = "¡No puedo hablar contigo, extranjero! ¡Habla con Brundt, el cacique!",
        ["They are too suspicious of you for you to get close enough to steal from them."] = "Sospechan demasiado de ti como para que te acerques lo suficiente como para robarles.",
        ["Hello."] = "Hola.",
        ["Hello. Did you want something, [Fremennik name]?"] = "Hola. ¿Querías algo, [Fremennik name]?",
        ["Can I ask you about V?"] = "¿Puedo preguntarte sobre V?",
        ["He was a great hero to our people. Why couldn't they have gone for one of the bad gods, like Zamorak or Saradomin?"] = "Fue un gran héroe para nuestro pueblo. ¿Por qué no pudieron haber elegido a uno de los dioses malos, como Zamorak o Saradomin?",
        ["Goodbye."] = "Adiós.",
        ["[Fremennik name], it has been too long since last we met!"] = "[Fremennik name], ¡ha pasado demasiado tiempo desde la última vez que nos vimos!",
        ["Hello to you, too!"] = "¡Hola a ti también!",
        ["Those cowards. They didn't even have the decency to face him as a warrior."] = "Esos cobardes. Ni siquiera tuvieron la decencia de enfrentarlo como un guerrero.",
        ["How are you, (Player Fremennik name)? I hope all fares well with you this day!"] = "¿Cómo estás, (nombre de Player Fremennik)? ¡Espero que a todos les vaya bien este día!",
        ["I'm fine, thanks, how are you?"] = "Estoy bien, gracias, ¿cómo estás?",
        ["All is well with me also!"] = "¡Todo está bien para mí también!",
        ["It's sad that he's gone, but he will live on as an inspiration to countless heroes across countless worlds."] = "Es triste que se haya ido, pero seguirá viviendo como una inspiración para innumerables héroes en innumerables mundos.",
        ["Hello. Did you want something, (Player Fremennik name)?"] = "Hola. ¿Querías algo, (nombre de Player Fremennik)?",
        ["He died saving you, (Player Fremennik name). Make sure you use his final gift wisely and live a life that we can all be proud of."] = "Murió salvándote, (nombre de Player Fremennik). Asegúrate de utilizar sabiamente su regalo final y vivir una vida de la que todos podamos estar orgullosos.",
    },
    ["Inglin"] = {
        ["Are you a surface-dweller?"] = "¿Eres un habitante de la superficie?",
        ["Yes..."] = "Sí...",
        ["Haha! You look funny! All tall and skinny with tiny eyes!"] = "¡Jaja! ¡Te ves gracioso! ¡Todo alto y delgado con ojos diminutos!",
        ["Are you Player? Did you help Zanik save the city?"] = "¿Eres Player? ¿Ayudaste a Zanik a salvar la ciudad?",
        ["Yes, that was me!"] = "¡Sí, ese era yo!",
        ["When I'm older I'm going to be an adventurer, just like Zanik!"] = "Cuando sea mayor seré un aventurero, ¡como Zanik!",
        ["Sorry, I'm not meant to talk to strangers."] = "Lo siento, no debo hablar con extraños.",
        ["Shh! Don't tell anyone!"] = "¡Shh! ¡No se lo digas a nadie!",
        ["Don't tell anyone what?"] = "¿No decirle a nadie qué?",
        ["SHHH!"] = "¡SHHH!",
        ["Help! Help! The surface people are attacking!"] = "¡Ayuda! ¡Ayuda! ¡La gente de la superficie está atacando!",
        ["It's alright, I'm friendly!"] = "¡Está bien, soy amigable!",
    },
    ["Ingrid Hradson"] = {
        ["Outlander, I have work to be getting on with... Please stop bothering me."] = "Outlander, tengo trabajo que hacer... Por favor, deja de molestarme.",
        ["Good afternoon! How do you like our village?"] = "¡Buenas tardes! ¿Qué te parece nuestro pueblo?",
        ["It's lovely. You have a fine collection of goats."] = "Es encantador. Tienes una excelente colección de cabras.",
        ["We polish them every day to get them nice and clean."] = "Los pulimos todos los días para que queden bonitos y limpios.",
        ["Hello again! Have you any word from my husband?"] = "¡Hola de nuevo! ¿Tiene alguna noticia de mi marido?",
        ["Err, no, not yet. It takes a while for the messages to reach me you know."] = "Err, no, todavía no. Los mensajes tardan un poco en llegar, ¿sabes?",
        ["Well, when you do, tell him we'll be more than happy to see him again."] = "Bueno, cuando lo hagas, dile que estaremos más que felices de volver a verlo.",
    },
    ["Ingrid"] = {
        ["Hello."] = "Hola.",
        ["Good day, your Royal Highness."] = "Buenos días, Alteza Real.",
    },
    ["Inhamat"] = {
        ["I used to be a merchant, famed for my wines. All it takes is two bad harvests in a row to ruin a man."] = "Solía ​​ser un comerciante, famoso por mis vinos. Bastan dos malas cosechas seguidas para arruinar a un hombre.",
        ["Please...spare some time. I could really use some help."] = "Por favor... dedica algo de tiempo. Realmente me vendría bien un poco de ayuda.",
        ["Would you like to help?"] = "¿Quieres ayudar?",
        ["Yes."] = "Sí.",
        ["Ah...thank you."] = "Ah... gracias.",
        ["Not right now."] = "No ahora mismo.",
        ["Nevermind."] = "No importa.",
        ["I've been awaiting a delivery that contains some [item 1] and some [item 2]. I urgently need the [item 1], but folks on the pier say that there's no sign of the ship for miles."] = "He estado esperando una entrega que contenga algo de [item 1] y algo de [item 2]. Necesito urgentemente el [item 1], pero la gente en el muelle dice que no hay señales del barco en millas.",
        ["Do you think you could get me [number] barberry seeds? I'm desperate for seeds that grow into barberry bushes."] = "¿Crees que podrías conseguirme semillas de agracejo [número]? Estoy desesperado por semillas que se conviertan en agracejos.",
        ["Where could I find a barberry seed?"] = "¿Dónde puedo encontrar una semilla de agracejo?",
        ["Barberry seeds are often dropped by monsters, or they can be procured from master farmers around Gielinor. Is that okay?"] = "Las semillas de agracejo a menudo las dejan los monstruos, o se pueden conseguir de los maestros agricultores alrededor de Gielinor. ¿Está bien?",
        ["Do you think you could get me [number] rosemary seeds? I'm desperate for seeds that grow into rosemary plants."] = "¿Crees que podrías conseguirme semillas de romero [número]? Estoy desesperado por semillas que se conviertan en plantas de romero.",
        ["Where could I find a rosemary seed?"] = "¿Dónde puedo encontrar una semilla de romero?",
        ["Rosemary seeds are often dropped by monsters, or they can be procured from master farmers around Gielinor. Is that okay?"] = "Las semillas de romero a menudo las dejan los monstruos, o se pueden conseguir de los maestros agricultores alrededor de Gielinor. ¿Está bien?",
        ["Do you think you could get me [number] rosemary seeds? I'm desperate for some regular old bones, dropped from creatures."] = "¿Crees que podrías conseguirme semillas de romero [número]? Estoy desesperado por algunos huesos viejos y normales, caídos de criaturas.",
        ["Where could I find a pile of bones?"] = "¿Dónde podría encontrar un montón de huesos?",
        ["Almost every living thing has bones, right? It shouldn't be too hard to find some. Is that okay?"] = "Casi todos los seres vivos tienen huesos, ¿verdad? No debería ser demasiado difícil encontrar algunos. ¿Está bien?",
        ["Select an option"] = "Selecciona una opción",
        ["Would you like to abandon this city quest?"] = "¿Te gustaría abandonar esta búsqueda de la ciudad?",
        ["Are you sure you wish to abandon this city quest?"] = "¿Estás seguro de que deseas abandonar esta búsqueda de la ciudad?",
        ["A new Menaphos city quest is now available."] = "Ya está disponible una nueva misión de ciudad Menaphos.",
        ["Talk about your current task."] = "Hable sobre su tarea actual.",
        ["Do you have [number] [item]? It's fairly urgent. ([number] remaining)"] = "¿Tienes [número] [item]? Es bastante urgente. ([número] restantes)",
        ["Abandon this city quest."] = "Abandona esta búsqueda de la ciudad.",
        ["Number of [item] given to Inhamat ([number]/[number])"] = "Número de [item] dado a Inhamat ([número]/[número])",
        ["Just one for now. Take it. I'll be back."] = "Sólo uno por ahora. Tómalo. Vuelvo enseguida.",
        ["I have some. Take them. I'll be back."] = "Tengo algunos. Tómelos. Vuelvo enseguida.",
        ["Great. Thank you."] = "Genial. Gracias.",
        ["Yep! I have the [item]."] = "¡Sí! Tengo el [item].",
        ["Yes! Thank you."] = "¡Sí! Gracias.",
        ["Now that's done, we need the next block of supplies."] = "Ahora que está hecho, necesitamos el siguiente bloque de suministros.",
        ["The next supplies I'm missing are a load of [item]."] = "Los siguientes suministros que me faltan son un montón de [item].",
        ["...and they still haven't arrived yet?"] = "...¿y todavía no han llegado?",
        ["Nope! All I need is a staff infused with fire magic and the ports workers tell me it will be days before I see them."] = "¡No! Todo lo que necesito es un staff con magia de fuego y los trabajadores del puerto me dicen que pasarán días antes de que los vea.",
        ["Nope! All I need is a starchy, tuberous crop and the ports workers tell me it will be days before I see them."] = "¡No! Todo lo que necesito es una cosecha de tubérculos y almidón y los trabajadores del puerto me dicen que pasarán días antes de que los vea.",
        ["Nope! All I need is some hot glass and the ports workers tell me it will be days before I see them."] = "¡No! Lo único que necesito es un vaso caliente y los trabajadores del puerto me dicen que pasarán días antes de que los vea.",
        ["Could you get me some to tide me over for now? About [number] [item] should do."] = "¿Podrías conseguirme algo para ayudarme por ahora? Acerca de [número] [item] debería funcionar.",
        ["Sure thing."] = "Claro.",
        ["No, sorry."] = "No, lo siento.",
        ["Do you have [number] [item]? ([number] remaining)"] = "¿Tienes [número] [item]? ([número] restantes)",
        ["Yes, I have the [item]."] = "Sí, tengo el [item].",
        ["Excellent. Saving the day with the [item 1] and now some [item 2], I appreciate your generosity."] = "Excelente. Salvando el día con el [item 1] y ahora algunos [item 2], agradezco su generosidad.",
        ["Seeing as you're so resourceful, I wonder if you could save me a trip around the city..."] = "Dado que eres tan ingenioso, me pregunto si podrías ahorrarme un viaje por la ciudad...",
        ["Go on..."] = "Continúa...",
        ["I need a way to grow dwarf weed herb bushes to see the month through. Approximately [number] dwarf weed seeds will save me a lot of hassle."] = "Necesito una forma de cultivar arbustos de malezas enanas para pasar el mes. Aproximadamente las semillas de malezas enanas [número] me ahorrarán muchos problemas.",
        ["I need potion supplies to see the month through. Approximately [number] goat horns will save me a lot of hassle."] = "Necesito suministros de pociones para terminar el mes. Aproximadamente [número] los cuernos de cabra me ahorrarán muchos problemas.",
        ["I need gear for climbing to see the month through. Approximately [number] lengths of rope will save me a lot of hassle."] = "Necesito equipo de escalada para pasar el mes. Aproximadamente [número] longitudes de cuerda me ahorrarán muchas molestias.",
        ["Are [number] [item] too much to ask for? Will you find me some?"] = "¿[número] [item] es mucho pedir? ¿Me encontrarás algunos?",
        ["Of course."] = "Por supuesto.",
        ["It's too much."] = "Es demasiado.",
        ["Do you have [number] dwarf weed seeds? Dwarf weed seeds are often dropped by monsters, or they can be procured from master farmers around Gielinor. ([number] remaining)"] = "¿Tienes semillas de hierba enana [número]? Las semillas de malezas enanas a menudo las dejan caer los monstruos, o se pueden obtener de los maestros agricultores alrededor de Gielinor. ([número] restante)",
        ["Do you have [number] goat horns? Goats can be found out around Nardah or west of the Kalphite Hive. ([number] remaining)"] = "¿Tienes cuernos de cabra [número]? Se pueden encontrar cabras alrededor de Nardah o al oeste de Kalphite Hive. ([número] restante)",
        ["Do you have [number] lengths of rope? They should be in any general store. ([number] remaining)"] = "¿Tienes [número] trozos de cuerda? Deberían estar en cualquier general store. ([número] restante)",
        ["Thank you so much for helping me!"] = "¡Muchas gracias por ayudarme!",
    },
    ["Inn Keeper"] = {
        ["Welcome to the King's Axe inn! What can I help you with?"] = "¡Bienvenido a la posada King's Axe! ¿En qué puedo ayudarte?",
        ["Can I have some beer please?"] = "¿Puedo tomar un poco de cerveza, por favor?",
        ["Go to the bar downstairs. I only deal with residents."] = "Ve al bar de abajo. Sólo trato con residentes.",
        ["Residents? People live here?"] = "¿Residentes? ¿La gente vive aquí?",
        ["No, just guests that stay the night. Like the gnome delegation that's come in recently. I believe they've come to talk to the Red Axe."] = "No, solo huéspedes que pasan la noche. Como la delegación de gnomos que llegó recientemente. Creo que han venido a hablar con Red Axe.",
        ["Where have they come from, do you know?"] = "¿De dónde vienen, lo sabes?",
        ["That's a rather impertinent question, one I certainly don't ask of my guests."] = "Esa es una pregunta bastante impertinente, una que ciertamente no hago a mis invitados.",
        ["No, just guests that stay the night."] = "No, solo huéspedes que pasan la noche.",
    },
    ["Intern Jimmy"] = {
        ["You're free to access Senntisten through here, but if you want to learn more about it, you should talk to Dr Nabanik. I believe he's up in the old Guildmaster's office."] = "Puedes acceder a Senntisten a través de aquí, pero si quieres obtener más información al respecto, debes hablar con Dr Nabanik. Creo que está en la oficina del viejo Guildmaster.",
        ["You are cleared for access. Feel free to enter the city at any time."] = "Tienes autorización para acceder. Siéntete libre de ingresar a la ciudad en cualquier momento.",
        ["Wait, it doesn't even teleport me into the cathedral? This ring is lame."] = "Espera, ¿ni siquiera me teletransporta a la catedral? Este anillo es patético.",
        ["Oh, yeah, about that... We're working to create an exception so your ring can teleport you past the wards straight into the cathedral. But it's going to take us at least a few weeks. I promise we'll make that ring more useful for you or my name's not James."] = "Oh, sí, sobre eso... Estamos trabajando para crear una excepción para que tu anillo pueda teletransportarte más allá de las barreras directamente a la catedral. Pero nos llevará al menos unas semanas. Prometo que haremos que ese anillo sea más útil para ti o mi nombre no es James.",
        ["Don't you go by 'Jimmy'?"] = "¿No te llamas 'Jimmy'?",
        ["Look, gimme a chance here, we're working on it... Please, be patient."] = "Mira, dame una oportunidad, estamos trabajando en ello... Por favor, ten paciencia.",
        ["Hello."] = "Hola.",
        ["Select an Option"] = "Selecciona una opción",
        ["Why are you the site manager here?"] = "¿Por qué eres el administrador del sitio aquí?",
        ["Well, since Senntisten is effectively your discovery, I would say you're the site manager really."] = "Bueno, dado que Senntisten es efectivamente tu descubrimiento, yo diría que en realidad eres el administrador del sitio.",
        ["But since you've got a lot of stuff on your plate already, I'm here to assist you as best I can."] = "Pero como ya tienes muchas cosas entre manos, estoy aquí para ayudarte lo mejor que pueda.",
        ["I'll handle the minutiae of the site management and you can focus on uncovering ancient secrets from the Second Age."] = "Yo me encargaré de los detalles de la administración del sitio y tú podrás concentrarte en descubrir antiguos secretos de la Segunda Edad.",
        ["What is this dig site about?"] = "¿De qué se trata este sitio de excavación?",
        ["This is the ancient city of Senntisten, the centre of power for the vast Zarosian Empire of the Second Age."] = "Esta es la antigua ciudad de Senntisten, el centro de poder del vasto Imperio Zarosiano de la Segunda Edad.",
        ["Right now it's a war zone. With the forces of the Elder Gods gathering against us, it's hard to perform the delicate work that an archaeological dig requires."] = "Ahora mismo es una zona de guerra. Con las fuerzas de los Dioses Mayores reuniéndose contra nosotros, es difícil realizar el delicado trabajo que requiere una excavación arqueológica.",
        ["But there's still so much to discover here! We can try to understand what life was like for the citizens of the Empire."] = "¡Pero todavía hay mucho por descubrir aquí! Podemos intentar comprender cómo era la vida de los ciudadanos del Imperio.",
        ["We can perhaps learn about the rituals and trappings of the ancient Zarosian religion."] = "Quizás podamos aprender sobre los rituales y adornos de la antigua religión zarosiana.",
        ["We might even uncover forgotten techniques and secrets to improve our daily lives."] = "Incluso podríamos descubrir técnicas y secretos olvidados para mejorar nuestra vida diaria.",
        ["The possibilities are endless."] = "Las posibilidades son infinitas.",
        ["I want to talk about mysteries."] = "Quiero hablar de misterios.",
        ["Bye."] = "Adiós.",
        ["See you around, boss."] = "Nos vemos, jefe.",
        ["We haven't uncovered anything yet, boss."] = "Aún no hemos descubierto nada, jefe.",
        ["Which mystery would you like to discuss?"] = "¿Qué misterio te gustaría discutir?",
        ["Empty Children"] = "Niños vacíos",
        ["Night Theatre"] = "Teatro Nocturno",
        ["Secrets of the Inquisition"] = "Secretos de la Inquisición",
    },
    ["Intern"] = {
        ["What could have led the dragonkin to settle in a place like this?"] = "¿Qué pudo haber llevado a los dragonantes a establecerse en un lugar como este?",
        ["Hello there, how's the site investigation been going? Any big discoveries so far?"] = "Hola, ¿cómo va la investigación del sitio? ¿Algún gran descubrimiento hasta ahora?",
        ["So far all I've discovered is that it's far too cold in here!"] = "¡Hasta ahora todo lo que he descubierto es que hace demasiado frío aquí!",
        ["I don't think that's quite the kind of discovery the guild is looking for."] = "No creo que ese sea el tipo de descubrimiento que el gremio está buscando.",
        ["Be sure to take a break by the campfire if you need to."] = "Asegúrate de tomar un descanso junto a la fogata si es necesario.",
    },
    ["Iona"] = {
        ["Hello."] = "Hola.",
        ["I can never catch Eoin, he is just too fast, I am always 'It'."] = "Nunca puedo alcanzar a Eoin, él es demasiado rápido, yo siempre soy \"Eso\".",
    },
    ["Irina"] = {
        ["*One of the following dialogues plays at random:*"] = "*Uno de los siguientes diálogos se reproduce aleatoriamente:*",
        ["*Dialogue 1*"] = "*Diálogo 1*",
        ["Out of my way, punk."] = "Fuera de mi camino, punk.",
        ["*Dialogue 2*"] = "*Diálogo 2*",
        ["I have no interest in talking to a pathetic meat bag like yourself."] = "No tengo ningún interés en hablar con un patético bolsa de carne como tú.",
        ["*Dialogue 3*"] = "*Diálogo 3*",
        ["If I were as ugly as you I would not dare to show my face in public!"] = "¡Si fuera tan feo como tú no me atrevería a mostrar mi cara en público!",
        ["*Dialogue 4*"] = "*Diálogo 4*",
        ["Hmm... you smell strange..."] = "Hmm... hueles raro...",
        ["Strange how?"] = "¿Qué extraño cómo?",
        ["Like a human!"] = "¡Como un humano!",
        ["Oh! Er... I just ate one is why!"] = "¡Oh! Er... ¡acabo de comer uno, por eso!",
        ["*Dialogue 5*"] = "*Diálogo 5*",
        ["Get lost!"] = "¡Piérdete!",
        ["*Dialogue 6*"] = "*Diálogo 6*",
        ["Leave me alone."] = "Déjame en paz.",
        ["*Dialogue 7*"] = "*Diálogo 7*",
        ["Have you no manners?"] = "¿No tienes modales?",
        ["*Dialogue 8*"] = "*Diálogo 8*",
        ["I don't have anything to give you so leave me alone, mendicant."] = "No tengo nada que darte así que déjame en paz, mendigo.",
        ["*Dialogue 9*"] = "*Diálogo 9*",
        ["I don't have time for this right now."] = "No tengo tiempo para esto ahora.",
        ["*Dialogue 10*"] = "*Diálogo 10*",
        ["Don't talk to me again if you value your life!"] = "¡No vuelvas a hablarme si valoras tu vida!",
        ["Give me a moment... I have a bit of someone stuck in my teeth..."] = "Dame un momento... tengo un poco de alguien pegado entre los dientes...",
        ["I haven't smelt you around here before..."] = "No te había olido por aquí antes...",
        ["If you catch anyone promise me you'll share."] = "Si atrapas a alguien, prométeme que lo compartirás.",
        ["You look to me like someone with a healthy taste for blood."] = "Me pareces alguien con un gusto saludable por la sangre.",
        ["Fancy going up to the castle for a bit of a snack?"] = "¿Te apetece subir al castillo a tomar un refrigerio?",
        ["I bet you have wonderful paws."] = "Apuesto a que tienes unas patas maravillosas.",
        ["Seen any humans around here? I'm v-e-r-y hungry."] = "¿Has visto humanos por aquí? Tengo mucha hambre.",
        ["Good day to you, my friend."] = "Buenos días, amigo mío.",
        ["You smell familiar..."] = "Hueles familiar...",
        ["A very miserable day, altogether... enjoy it while it lasts."] = "Un día muy miserable, en definitiva... disfrútalo mientras dure.",
    },
    ["Irksol"] = {
        ["Selling ruby rings! The best deals on rings in over twenty four hundred planes of existence!"] = "¡Vendiendo anillos de rubíes! ¡Las mejores ofertas en anillos en más de dos mil cuatrocientos planos de existencia!",
        ["Select an option"] = "Seleccione una opción",
        ["I'm interested in these deals."] = "Estoy interesado en estas ofertas.",
        ["Aha! A connoisseur! Check out these beauties!"] = "¡Ajá! ¡Un conocedor! ¡Mira estas bellezas!",
        ["No thanks, just browsing."] = "No, gracias, solo navegando.",
        ["Fair enough."] = "Bastante bien.",
    },
    ["Iroh, the Group Ironman tutor"] = {
        ["Good day! What do you want to know about Group Ironman?"] = "¡Buenos días! ¿Qué quieres saber del Grupo Ironman?",
        ["Choose an option:"] = "Elija una opción:",
        ["Tell me more about Group Ironman mode."] = "Cuéntame más sobre el modo Grupo Ironman.",
        ["Group Ironman allows you to enjoy the Ironman experience as a group of 2 to 5 friends. You know, when you want to get away from it all, but do it with someone."] = "Group Ironman te permite disfrutar de la experiencia Ironman en grupo de 2 a 5 amigos. Ya sabes, cuando quieras alejarte de todo, pero hazlo con alguien.",
        ["As you work together and grow, you can complete Journey Achievements."] = "A medida que trabajen juntos y crezcan, podrán completar Journey Achievements.",
        ["Journey achievements are a set of objectives for the group to complete as individuals and as a group - you will need to level your skills, complete quests, kill bosses and explore all Gielinor has to offer."] = "Los logros del viaje son un conjunto de objetivos que el grupo puede completar como individuos y como grupo; necesitarás mejorar tus habilidades, completar misiones, matar jefes y explorar todo lo que Gielinor tiene para ofrecer.",
        ["Completing Journey Achievements will unlock rewards such as group storage, an upgradable cosmetic armour and unique pose emotes."] = "Completar los logros del viaje desbloqueará recompensas como almacenamiento grupal, una armadura cosmética actualizable y gestos de pose únicos.",
        ["Or you can chart your own path and set your own goals as you experience a brand new type of adventure. The choice, as they say, is yours."] = "O puedes trazar tu propio camino y establecer tus propios objetivos mientras experimentas un nuevo tipo de aventura. La elección, como dicen, es tuya.",
        ["How do I create or join a group?"] = "¿Cómo creo o me uno a un grupo?",
        ["It's quite simple really! There are two options: you can either start your own group or be invited to an existing group."] = "¡Es bastante simple realmente! Hay dos opciones: puedes iniciar tu propio grupo o ser invitado a un grupo existente.",
        ["If you want to create your own group, simply click the 'Create Group' option and then choose which ruleset you would like your group to be."] = "Si desea crear su propio grupo, simplemente haga clic en la opción 'Crear grupo' y luego elija qué conjunto de reglas desea que sea su grupo.",
        ["Once that's decided, you can then invite anyone you want to join your group. Each group can be between 2 and 5 players in size."] = "Una vez que lo hayas decidido, podrás invitar a quien quieras a unirse a tu grupo. Cada grupo puede tener entre 2 y 5 jugadores.",
        ["You can invite players to your group by clicking the {{Contrast|c=#036|t='Invite to Group'}} button and typing the player's name, or by right-clicking players and selecting {{Contrast|c=#036|t='Invite'}}."] = "Puedes invitar jugadores a tu grupo haciendo clic en el botón {{Contrast|c=#036|t='Invite to Group'}} y escribiendo el nombre de el player, o haciendo clic derecho en los jugadores y seleccionando {{Contrast|c=#036|t='Invite'}}.",
        ["Each group can have their own unique name so pick one that best represents you."] = "Cada grupo puede tener su propio nombre único, así que elige el que mejor te represente.",
        ["Then you're ready to go! Confirm your group, and head over the bridge to the portal which will take you to Lumbridge to begin your adventure!"] = "¡Entonces estás listo para comenzar! ¡Confirma tu grupo y cruza el puente hacia el portal que te llevará a Lumbridge para comenzar tu aventura!",
        ["Don't forget to collect a set of armour from the stand next to me; it will provide you some initial protection from any enemies you may face."] = "No olvides recoger una armadura del puesto de al lado; te proporcionará cierta protección inicial contra cualquier enemigo al que te puedas enfrentar.",
        ["What are the different group rulesets?"] = "¿Cuáles son los diferentes conjuntos de reglas de grupo?",
        ["There are two different rulesets that you can choose from: Competitive and Regular."] = "Hay dos conjuntos de reglas diferentes entre los que puedes elegir: Competitivo y Regular.",
        ["Competitive is a strict ruleset where you can only play with your group; this means all your progress and accomplishments come from within the group only."] = "Competitivo es un conjunto de reglas estrictas en el que solo puedes jugar con tu grupo; esto significa que todo su progreso y logros provienen únicamente del grupo.",
        ["In Competitive, a group can only be formed with those fresh to Gielinor so you can set out as a group to prove yourself as the best of the best."] = "En Competitivo, solo se puede formar un grupo con aquellos nuevos en Gielinor para que puedas iniciar como grupo y demostrar que eres el mejor de los mejores.",
        ["Regular is a more relaxed ruleset that allows you to play with others outside your group, and there are no restrictions on leaving and joining other groups in the future."] = "Regular es un conjunto de reglas más relajado que te permite jugar con otras personas fuera de tu grupo y no hay restricciones para salir o unirte a otros grupos en el futuro.",
        ["Pick whichever mode best represents your group. Competitive groups can choose to become a Regular group later; however a Regular group can never become a Competitive group once the group has been finalised."] = "Elige el modo que mejor represente a tu grupo. Los grupos competitivos pueden optar por convertirse en un grupo regular más adelante; sin embargo, un grupo Regular nunca puede convertirse en un grupo Competitivo una vez que el grupo haya sido finalizado.",
        ["Can I change my game mode?"] = "¿Puedo cambiar mi modo de juego?",
        ["I'm afraid you can't change your game mode, as you've previously opted to never disable Group Ironman mode."] = "Me temo que no puedes cambiar tu modo de juego, ya que previamente has optado por no desactivar nunca el modo Group Ironman.",
        ["Of course! What would you like to do?"] = "¡Por supuesto! ¿Qué te gustaría hacer?",
        ["Select an Option"] = "Selecciona una opción",
        ["Change to Standard mode (permanently leave Group Ironman mode)."] = "Cambia al modo Estándar (abandona permanentemente el modo Ironman grupal).",
        ["Very well. I will send you on to Burthorpe where my old friend, Turael, will be able to guide you from this point onwards."] = "Muy bien. Te enviaré a Burthorpe donde mi viejo amigo, Turael, podrá guiarte a partir de este punto.",
        ["Never disable Group Ironman mode."] = "Nunca desactives el modo Grupo Ironman.",
        ["Never means never! Are you sure you want to {{colour|#EB2F2F|permanently}} prevent yourself from leaving Group Ironman mode?"] = "¡Nunca significa nunca! ¿Estás seguro de que deseas {{colour|#EB2F2F|permanente}} evitar salir del modo Grupo Ironman?",
        ["Never disable Group Ironman mode?"] = "¿Nunca deshabilitas el modo Grupo Ironman?",
        ["Yes, I NEVER want to disable Group Ironman mode."] = "Sí, NUNCA quiero desactivar el modo Ironman grupal.",
        ["Are you absolutely sure you want to {{colour|#EB2F2F|permanently}} prevent yourself from leaving Group Ironman mode? This cannot be reversed."] = "¿Estás absolutamente seguro de que deseas {{colour|#EB2F2F|permanente}} evitar salir del modo Grupo Ironman? Esto no se puede revertir.",
        ["Confirm never disabling Group Ironman mode?"] = "¿Confirmar que nunca se deshabilitó el modo Group Ironman?",
        ["So be it, you will always remain a Group Ironman."] = "Que así sea, siempre seguirás siendo un Ironman grupal.",
        ["Thanks!"] = "¡Gracias!",
        ["No, I want to be able to leave Group Ironman mode."] = "No, quiero poder salir del modo Ironman grupal.",
        ["Never mind."] = "No importa.",
        ["Goodbye."] = "Adiós.",
        ["Farewell."] = "Adiós.",
    },
    ["Irwin Feaselbaum"] = {
        ["Can I help you?"] = "¿Puedo ayudarte?",
        ["Choose an option:"] = "Elige una opción:",
        ["What do you do here?"] = "¿Qué haces aquí?",
        ["I help the main man over there. He can get a bit cantankerous. Every now and then he'll just start attacking people without warning. I act as a sort of home help..."] = "Ayudo al hombre principal de allí. Puede ponerse un poco cascarrabias. De vez en cuando comenzará a atacar a la gente sin previo aviso. Actúo como una especie de ayuda a domicilio...",
        ["How do you mean, home help?"] = "¿Qué quieres decir con ayuda a domicilio?",
        ["Well, sometimes he'll fly right off the handle and just start, you know, 'raising the dead' to do his 'bidding'. That kind of activity is just so anti-social, so it tends to attract a lot of hero types, you know!"] = "Bueno, a veces se vuelve loco y simplemente comienza, ya sabes, a 'resucitar a los muertos' para cumplir sus 'ordenes'. Ese tipo de actividad es tan antisocial que tiende a atraer a muchos tipos de héroes, ¿sabes?",
        ["Yes, yes, I know the sort.<br>Full of themselves, aren't they?"] = "Sí, sí, los conozco.<br>Llenos de sí mismos, ¿no?",
        ["Exactly! They come in shouting 'Have at thee!' and 'Death to you, evil one!' It's all a bit too dramatic for me, to be honest."] = "¡Exactamente! Entran gritando '¡A por ti!' y '¡Muerte a ti, maligno!' Para ser honesto, todo es demasiado dramático para mí.",
        ["Anyway, he'll often end up getting killed, then nothing gets done around the house while he's awaiting his mortal return."] = "De todos modos, a menudo terminará asesinado y luego no se hará nada en la casa mientras espera su regreso mortal.",
        ["Mortal return? Sounds interesting."] = "¿Retorno mortal? Suena interesante.",
        ["Well, it's kind of interesting the first few times, but it's like falling off a bike..."] = "Bueno, es algo interesante las primeras veces, pero es como caerse de una bicicleta...",
        ["What, you graze your knees a lot?"] = "¿Qué? ¿Te rozas mucho las rodillas?",
        ["I was going to say that you soon get fed up with it. I guess it's one of those perks of the job, though, the ability to raise yourself from the dead."] = "Iba a decir que pronto te cansas de eso. Supongo que es una de esas ventajas del trabajo, la capacidad de resucitar de entre los muertos.",
        ["You'd think he'd do better things with a gift like that, but all he does is get angry at people who come into his house without being invited, and then he's off again 'raising the dead'."] = "Uno pensaría que haría mejores cosas con un regalo como ese, pero lo único que hace es enojarse con la gente que entra a su casa sin ser invitado, y luego vuelve a \"resucitar a los muertos\".",
        ["Thank you."] = "Gracias.",
        ["No thanks."] = "No gracias.",
        ["Okay. Please don't upset the boss while you're here."] = "Está bien. Por favor, no molestes al jefe mientras estés aquí.",
    },
    ["Irwinsson"] = {
        ["Corr blimey mate, you scared the life out of me, sneaking up like that!"] = "¡Caramba, amigo, me asustaste muchísimo al acercarte sigilosamente de esa manera!",
        ["Oh, sorry. I've just got here, who are you?"] = "Oh, lo siento. Acabo de llegar, ¿quién eres?",
        ["I'm Irwinsson, I think, and I've lived here as long as I can remember."] = "Creo que soy Irwinsson y he vivido aquí desde que tengo uso de razón.",
        ["You think? How do you not know your own name?"] = "¿Crees? ¿Cómo no sabes tu propio nombre?",
        ["Well, I was out on me dinghy when that big storm hit forever back and KABLAM, I woke up on this island left damn stranded. I've been struggling with me memory ever since."] = "Bueno, estaba en mi bote cuando esa gran tormenta golpeó para siempre y KABLAM, me desperté en esta isla y me quedé varado. He estado luchando con mi memoria desde entonces.",
        ["Forever ago? The storm wall around the island only broke recently... You can't have been here that long."] = "¿Hace una eternidad? El muro de tormenta que rodea la isla se rompió recientemente... No puedes haber estado aquí tanto tiempo.",
        ["WHAT?"] = "¿QUÉ?",
        ["N..n..no surely not, you're dreaming again Irwinsson, get it together man."] = "N..n..no, seguro que no, estás soñando de nuevo Irwinsson, recompóntelo, hombre.",
        ["Errr... are you ok?"] = "Errr... ¿estás bien?",
        ["Huh? Oh, yeah, I'm fine, must get back to the hunt..."] = "¿Eh? Oh, sí, estoy bien, debo volver a la caza...",
        ["What can I do ye for mate? Be quick, though, I gotta get back to the hunt."] = "¿Qué puedo hacer por amigo? Pero date prisa, tengo que volver a la caza.",
        ["*(Only before Father and Son)* Tell me more about yourself."] = "*(Solo ante Padre e Hijo)* Cuéntame más sobre ti.",
        ["*(Only after Father and Son)* How have you been surviving out here along for so long?"] = "*(Sólo después de Padre e Hijo)* ¿Cómo has sobrevivido aquí durante tanto tiempo?",
        ["So tell me, what's your trick to surviving out here for so long?"] = "Dime, ¿cuál es tu truco para sobrevivir aquí durante tanto tiempo?",
        ["It's been tough. I've had to hunt all me own tucker, but when it's one of those biggens, it lasts for days!"] = "Ha sido duro. He tenido que cazar todos mis propios tucker, pero cuando es uno de esos biggens, ¡dura días!",
        ["And I've been camped out here, the walls have kept me hidden and protected from everything out there."] = "Y he estado acampado aquí, las paredes me han mantenido oculto y protegido de todo lo que hay ahí afuera.",
        ["Oh and the water, how did I forget the water!"] = "¡Ah, y el agua, cómo me olvidé del agua!",
        ["Really? Water? What's so special about the water?"] = "¿En serio? ¿Agua? ¿Qué tiene de especial el agua?",
        ["Ah mate it's the best! Makes me a little lightheaded for a while afterwards but it gives me so much energy, I feel great. And the colours, the colours are incredible."] = "¡Ah amigo, es el mejor! Después me siento un poco mareado por un tiempo, pero me da tanta energía que me siento genial. Y los colores, los colores son increíbles.",
        ["Err... I think you should maybe lay off the water for a while."] = "Err... Creo que tal vez deberías dejar el agua por un tiempo.",
        ["It sounds like you've had a pretty scary time though."] = "Parece que has pasado un momento bastante aterrador.",
        ["It would have been easier if I had me compass with me. Wouldn't have been getting so lost all the time."] = "Hubiera sido más fácil si tuviera mi brújula conmigo. No habría estado tan perdido todo el tiempo.",
        ["*(Before returning the compass:)*"] = "*(Antes de devolver la brújula:)*",
        ["Oh wait... yes... my compass! Irwinsson you idiot, you lost it. How could you be so stupid."] = "Oh, espera... sí... ¡mi brújula! Irwinsson idiota, lo perdiste. ¿Cómo puedes ser tan estúpido?",
        ["Woah, hang on. What are you talking about? Have you lost something?"] = "Vaya, espera. ¿De qué estás hablando? ¿Has perdido algo?",
        ["I've lost everything! That compass has been in me family for generations and I've lost it!"] = "¡Lo he perdido todo! ¡Esa brújula ha estado en mi familia durante generaciones y la he perdido!",
        ["Please help me find it, I'll give ya a reward for your time if you do."] = "Por favor, ayúdame a encontrarlo. Si lo haces, te daré una recompensa por tu tiempo.",
        ["Leave it with me and I'll see what I can do."] = "Déjamelo y veré qué puedo hacer.",
        ["*(After returning the compass:)*"] = "*(Después de devolver la brújula:)*",
        ["And now that you have arrived and four it for me, I will be able to get around here even quicker."] = "Y ahora que has llegado y me lo has dado, podré desplazarme por aquí aún más rápido.",
        ["Cheers cobber."] = "Saludos cobber.",
        ["Is there anything else I can do ye for mate?"] = "¿Hay algo más que pueda hacer por amigo?",
        ["*(Only after Father and Son)* What's that thing you're wielding?"] = "*(Sólo después de Padre e Hijo)* ¿Qué es esa cosa que estás empuñando?",
        ["Woah that weapon looks so cool, what is it?"] = "Vaya, esa arma se ve tan genial, ¿qué es?",
        ["Ah, you mean this thing? I made it me'self. When I was out there killing some beasts, I managed to scavenge parts of the creature that helped me make this thing."] = "Ah, ¿te refieres a esto? Lo hice yo mismo. Cuando estaba matando algunas bestias, logré recuperar partes de la criatura que me ayudó a hacer esto.",
        ["It's not from the same giant creatures as the ones you hunt though. These are a completely different challenge where only the strongest will bring them down."] = "Sin embargo, no es de las mismas criaturas gigantes que cazas. Se trata de un desafío completamente diferente en el que sólo los más fuertes podrán derrotarlos.",
        ["Wow, that's incredible. How does it work?"] = "Vaya, eso es increíble. ¿Cómo funciona?",
        ["Well it's super small which means I can fire it quickly to catch my enemies by surprise."] = "Bueno, es súper pequeño, lo que significa que puedo dispararlo rápidamente para sorprender a mis enemigos.",
        ["And there's enough poison in here to last a lifetime, so everything that I fire from it is full to the brim with poison."] = "Y hay suficiente veneno aquí para toda la vida, así que todo lo que disparo está lleno hasta el borde de veneno.",
        ["Why did you say that? He's gonna come back in yer sleep and take it from ye."] = "¿Por qué dijiste eso? Él volverá mientras duermes y te lo quitará.",
        ["You don't have to worry about me. I hope to make my self one too!"] = "No tienes que preocuparte por mí. ¡Espero hacerme uno también!",
        ["So, you're a bit of a hunter then are you?"] = "Entonces, eres un poco cazador, ¿verdad?",
        ["What? How do they know this? Have we spoken to them before?"] = "¿Qué? ¿Cómo saben esto? ¿Hemos hablado con ellos antes?",
        ["Hello?"] = "¿Hola?",
        ["Oh alright there mate, what can I do ye for?"] = "Oh, está bien amigo, ¿qué puedo hacer por ti?",
        ["You spoke about getting back to the hunt?"] = "¿Hablaste de volver a cazar?",
        ["Ah right, yeah, there's this special creature out there, somewhere, and for the life of me I can't find it."] = "Ah, claro, sí, hay una criatura especial ahí fuera, en algún lugar, y por mi vida no puedo encontrarla.",
        ["Whenever I think I've gotten close, or when I've hunted something, it always turns out to be the wrong thing. I will never forget the glow in its eyes, the beauty."] = "Cada vez que creo que me he acercado, o cuando he cazado algo, siempre resulta ser algo equivocado. Nunca olvidaré el brillo de sus ojos, la belleza.",
        ["Wait, there's more big creatures out there?"] = "Espera, ¿hay más criaturas grandes por ahí?",
        ["There's loadsss of them, majestic things. They live across the lisand in these big open spaces."] = "Hay muchísimos de ellos, cosas majestuosas. Viven al otro lado de la isla en estos grandes espacios abiertos.",
        ["Give 'em the food they like and you can hunt one for ye'self!"] = "¡Dales la comida que les gusta y podrás cazar una para ti!",
        ["Don't let 'em spot ya though or you will lose 'em and need to lure out another."] = "No dejes que te detecten o los perderás y tendrás que atraer a otro.",
        ["Right on!"] = "¡Adelante!",
        ["Huh?"] = "¿Eh?",
        ["Nothing..."] = "Nada...",
        ["Do you have anything for sale?"] = "¿Tienes algo a la venta?",
        ["Yeah I got some bits I made to help me hunt those bloody creatures. I'll sell 'em to ya in exchange for hunter marks. I can also set you up with any other supplies you might need for hunting."] = "Sí, tengo algunas piezas que hice para ayudarme a cazar esas malditas criaturas. Te los venderé a cambio de marcas de cazador. También puedo proporcionarte otros suministros que puedas necesitar para la caza.",
        ["Select an option"] = "Seleccione una opción",
        ["Hunter mark shop."] = "Tienda de la marca Hunter.",
        ["Hunter supply shop."] = "Tienda de suministros Hunter.",
        ["What are hunter marks?"] = "¿Qué son las marcas de cazador?",
        ["Can you tell me about hunter marks please?"] = "¿Puedes contarme sobre las marcas de cazador, por favor?",
        ["Well, ye see, I've got eyes everywhere on this island so I see everything."] = "Bueno, ya ves, tengo ojos en todas partes de esta isla, así que veo todo.",
        ["That includes everything you hunt, big or small and for every successful catch, I'll tally up some hunter marks for ya."] = "Eso incluye todo lo que cazas, grande o pequeño, y por cada captura exitosa, contaré algunas marcas de cazador.",
        ["Trade the marks to me for some stuff I found since I was stranded here."] = "Cámbiame las marcas por algunas cosas que encontré desde que me quedé varado aquí.",
        ["Great, thank you."] = "Genial, gracias.",
        ["*(Only before Father and Son)* Goodbye."] = "*(Sólo ante Padre e Hijo)* Adiós.",
        ["See ya around, cobber."] = "Nos vemos, cobber.",
        ["What is that you've got there?"] = "¿Qué es eso que tienes ahí?",
        ["You mean this compass? I found it at a shipwreck."] = "¿Te refieres a esta brújula? Lo encontré en un naufragio.",
        ["It's my lucky compass! I thought I'd lost it forever. Can you give it back, mate?"] = "¡Es mi brújula de la suerte! Pensé que lo había perdido para siempre. ¿Puedes devolverlo, amigo?",
        ["I can, but... it's broken. It looks the glass has smashed and the arrow has been lost."] = "Puedo, pero... está roto. Parece que el cristal se ha roto y la flecha se ha perdido.",
        ["This can't be... Listen, I know it sounds silly but if there's anyway you could repair this it would mean everything to me."] = "Esto no puede ser... Escucha, sé que suena tonto, pero si hay alguna forma de reparar esto, significaría todo para mí.",
        ["I'll see what I can do."] = "Veré qué puedo hacer.",
        ["Yer the best! What can I do ye for mate?"] = "¡Eres el mejor! ¿Qué puedo hacer por compañero?",
        ["*(Continues with normal dialogue if dialogue was triggered by talking.)*"] = "*(Continúa con el diálogo normal si el diálogo se inició al hablar).*",
        ["Seems like a waste of my time."] = "Parece una pérdida de tiempo.",
        ["I get it, you're busy but if you change your mind, I'd love your help."] = "Lo entiendo, estás ocupado pero si cambias de opinión, me encantaría que me ayudaras.",
        ["Hmm... that looks familiar. Strange."] = "Hmm... eso me resulta familiar. Extraño.",
        ["Hand over the compass?"] = "¿Entregar la brújula?",
        ["Yes."] = "Sí.",
        ["You are incredible! I feel much luckier already. Listen I know it's not much but take these hunter marks for being such a friend."] = "¡Eres increíble! Ya me siento mucho más afortunado. Escucha, sé que no es mucho, pero toma estas marcas de cazador por ser tan amigo.",
        ["Congratulations! You have completed: 'A New Direction' - Reunite Irwinsson with his lost compass."] = "¡Felicitaciones! Has completado: 'Una nueva dirección' - Reúne a Irwinsson con su brújula perdida.",
        ["You earn 25 hunter marks. You now have [amount] available to spend in the reward shop."] = "Obtienes 25 marcas de cazador. Ahora tienes [amount] disponible para gastar en la tienda de recompensas.",
        ["Irwinsson hands you 25 hunter marks."] = "Irwinsson te entrega 25 marcas de cazador.",
        ["*(Continues above with normal dialogue if dialogue was triggered by talking.)*"] = "*(Continúa arriba con el diálogo normal si el diálogo se inició al hablar).*",
        ["Ahh I forgot to give ya this for helping reunite me with me 'ol cobber."] = "Ahh, olvidé darte esto por ayudarme a reunirme con mi viejo cobber.",
        ["I have a special request for [Breed]. Especially if it has the [Trait] trait!"] = "Tengo una solicitud especial para [Breed]. ¡Especialmente si tiene el rasgo [Trait]!",
        ["I'm also after some Pavosaurus rex, in fact I'll buy up to [number] more while I'm here."] = "También busco algunos Pavosaurus rex, de hecho compraré hasta [número] más mientras esté aquí.",
        ["Would you like to sell [name] for [number] beans?"] = "¿Le gustaría vender [name] por frijoles [número]?",
        ["This transaction would take you over the cap of one million beans. In doing so, you would lose out on [number] beans."] = "Esta transacción le llevaría por encima del límite de un millón de frijoles. Al hacerlo, perdería beans [número].",
        ["**COMPLETE TRANSACTION ANYWAY?**"] = "**¿COMPLETAR LA TRANSACCIÓN DE TODOS MODOS?**",
        ["[number] beans added to your currency pouch."] = "Frijoles [número] agregados a su bolsa de divisas.",
        ["Your currency pouch is full of beans! You need to spend some beans before you can earn any more."] = "¡Tu bolsa de monedas está llena de frijoles! Necesitas gastar algunos frijoles antes de poder ganar más.",
        ["You can't hold anymore beans, I can't purchase this animal off you."] = "No puedes aguantar más frijoles, no puedo comprarte este animal.",
        ["Are you sure you want me to take all the Pavosaurus rex you're holding? I won't take any of your favourites."] = "¿Estás seguro de que quieres que me lleve todo el Pavosaurus rex que tienes? No aceptaré ninguno de tus favoritos.",
        ["**SELL ALL OF YOUR PAVOSAURUS REX?**"] = "**¿VENDER TODO TU PAVOSAURUS REX?**",
        ["Yes"] = "si",
        ["You don't have any animals to sell. Zero animals, Zero beans!"] = "No tienes animales para vender. ¡Cero animales, cero frijoles!",
    },
    ["Isaac (Havenhythe)"] = {
        ["If you're looking for pottery, you've found the best and...well, only, potter in Wendlewick."] = "Si buscas cerámica, has encontrado la mejor y... bueno, la única alfarera en Wendlewick.",
        ["If you're looking for a stick-in-the-mud who can't appreciate that true art is messy, you'll find my wife across the street."] = "Si estás buscando a alguien que no puede apreciar que el verdadero arte es desordenado, encontrarás a mi esposa al otro lado de la calle.",
        ["I decided to move my workshop out of the house."] = "Decidí trasladar mi taller fuera de casa.",
    },
    ["Isaac"] = {
        ["If you're looking for pottery, you've found the best and...well, only, potter in Wendlewick."] = "Si buscas cerámica, has encontrado la mejor y... bueno, la única alfarera en Wendlewick.",
        ["If you're looking for a stick-in-the-mud who can't appreciate that true art is messy, you'll find my wife across the street."] = "Si estás buscando a alguien que no puede apreciar que el verdadero arte es desordenado, encontrarás a mi esposa al otro lado de la calle.",
        ["I decided to move my workshop out of the house."] = "Decidí trasladar mi taller fuera de casa.",
    },
    ["Isaura"] = {
        ["Who are you and what are you doing here?"] = "¿Quién eres y qué haces aquí?",
        ["I'm not sure why I'm here, but my name is Player."] = "No estoy seguro de por qué estoy aquí, pero mi nombre es Player.",
        ["Well, Player, if you were an archaeologist, I would be asking you about collections."] = "Bueno, Player, si fueras arqueólogo, te estaría preguntando sobre colecciones.",
        ["My name is Player, and I'm an archaeologist! I'm here because apparently you are interested in collecting artefacts?"] = "¡Mi nombre es Player y soy arqueólogo! Estoy aquí porque aparentemente estás interesado en coleccionar artefactos.",
        ["Ah yes. That is correct. Excellent."] = "Ah, sí. Eso es correcto. Excelente.",
        ["Why do the Black Knights want to collect all this old stuff?"] = "¿Por qué los Black Knights quieren coleccionar todas estas cosas viejas?",
        ["That is none of your concern. We are paying for your artefacts and for you not to ask questions."] = "Eso no es de tu incumbencia. Estamos pagando por tus artefactos y para que no hagas preguntas.",
        ["Select an Option"] = "Selecciona una opción",
        ["Who are you?"] = "¿Quién eres?",
        ["I am Chief Requisitions Officer Isaura Wabub. You may call me precisely that."] = "Soy el director de solicitudes de Isaura Wabub. Puedes llamarme precisamente así.",
        ["That's an unusual name. Are you sure you're a Black Knight, and not a White Knight in disguise?"] = "Ese es un nombre inusual. ¿Estás seguro de que eres un Black Knight y no un Caballero Blanco disfrazado?",
        ["Are you suggesting the name my parents gave me is a silly pun or joke?"] = "¿Estás sugiriendo que el nombre que me dieron mis padres es un juego de palabras o una broma tonta?",
        ["Wait, no, sorry, that's not what I meant. I just me-"] = "Espera, no, lo siento, eso no es lo que quise decir. Yo solo yo-",
        ["Haha! I'm just yanking your chain. I've heard all the jokes, don't worry."] = "¡Jaja! Sólo estoy tirando de tu cadena. He oído todos los chistes, no te preocupes.",
        ["But, yes, of course I'm a Black Knight...though I would hardly reveal it to a random archaeologist if I were a spy, now, would I?"] = "Pero sí, por supuesto que soy un Black Knight... aunque difícilmente se lo revelaría a un arqueólogo al azar si fuera un espía, ¿verdad?",
        ["What are you collecting?"] = "¿Qué estás coleccionando?",
        ["Take a look at my requirements, unless you're one of those types who prefers - urgh - talking..."] = "Echa un vistazo a mis requisitos, a menos que seas de esos tipos que prefieren - urgh - hablar...",
        ["View collections."] = "Ver colecciones.",
        ["Talk about collections."] = "Habla de colecciones.",
        ["Well, I am a Black Knight, so I will take anything Zamorakian! The order is very interested in whatever you might unearth at the Infernal Source. It's part of our organisation's history and heritage."] = "Bueno, soy un Black Knight, ¡así que aceptaré cualquier cosa zamorakiana! La orden está muy interesada en todo lo que puedas descubrir en Infernal Source. Es parte de la historia y el patrimonio de nuestra organización.",
        ["Is Movario not connected with your organisation? How do you feel about him managing the site?"] = "¿Movario no está conectado con su organización? ¿Qué opinas de que él administre el sitio?",
        ["As I understand it, we have worked with him in the past, but he is more of a freelancer. I also understand he is mostly in it for himself, so I would put my trust in you over him."] = "Según tengo entendido, hemos trabajado con él en el pasado, pero es más un profesional independiente. También entiendo que él está principalmente en esto por sí mismo, por lo que confiaría más en ti que en él.",
        ["The Kinshra can make it worth your while."] = "El Kinshra puede hacer que valga la pena.",
        ["What are your collection rewards?"] = "¿Cuáles son las recompensas de tu colección?",
        ["For a start, we will trade you chronotes for anything you bring to us. They hold value to archaeologists for a number of reasons."] = "Para empezar, te cambiaremos cronotas por cualquier cosa que nos traigas. Tienen valor para los arqueólogos por varias razones.",
        ["Though, for each of my collections, I have some specific and unique items up for trade."] = "Sin embargo, para cada una de mis colecciones, tengo algunos artículos específicos y únicos para intercambiar.",
        ["Hmm, I suppose you can have this abyssal thread I've found no use for?"] = "Hmm, ¿supongo que puedes quedarte con este hilo abismal al que no he encontrado uso?",
        ["Ooh, what's that?"] = "Oh, ¿qué es eso?",
        ["I think it's the stringy bits of abyssal creatures spun together."] = "Creo que son los trozos fibrosos de criaturas abisales entrelazados.",
        ["Eww, no thanks."] = "Vaya, no gracias.",
        ["Don't be so hasty! The ZMI's dark mage at the centre of the Abyss says you could use it on a giant Runecrafting essence pouch, and it would permanently stop your essence pouches from degrading."] = "¡No te apresures! El dark mage de ZMI en el centro del Abismo dice que podrías usarlo en una bolsa de esencia gigante Runecrafting, y evitaría permanentemente que tus bolsas de esencia se degraden.",
        ["Actually, that sounds alright, thanks!"] = "En realidad, eso suena bien, ¡gracias!",
        ["Did you use that abyssal thread to protect your rune essence pouches yet?"] = "¿Ya usaste ese hilo abisal para proteger tus bolsas de esencia rúnica?",
        ["Not yet."] = "Todavía no.",
        ["Um, do you have any more abyssal thread? I lost mine before using it."] = "Um, ¿tienes algún hilo más abisal? Perdí el mío antes de usarlo.",
        ["Fine, but don't lose this one!"] = "Bien, ¡pero no te pierdas este!",
        ["Take abyssal thread from Isaura?"] = "¿Tomar hilo abisal de Isaura?",
        ["Yes."] = "Sí.",
        ["Yes, I put it to good use, thanks."] = "Sí, le di un buen uso, gracias.",
        ["I have a couple of tetracompass pieces you can have for completing my middle two collections."] = "Tengo un par de piezas de tetracompass que puedes tener para completar mis dos colecciones intermedias.",
        ["I have a relic - some headwear called Ariadne's Diadem. It makes you better at support skills, helps you train them slightly faster."] = "Tengo una reliquia: una prenda para la cabeza llamada Diadema de Ariadna. Te mejora en las habilidades de apoyo y te ayuda a entrenarlas un poco más rápido.",
        ["How's that head support? Good? Good. No need to talk more about it."] = "¿Cómo es ese soporte para la cabeza? ¿Bien? Bien. No es necesario hablar más sobre eso.",
        ["Bye."] = "Adiós.",
        ["Dismissed!"] = "¡Descartado!",
    },
    ["Isis"] = {
        ["You need the following skills to start this quest: 74 Firemaking, 76 Constitution, 64 Agility."] = "Necesitas las siguientes habilidades para comenzar esta misión: 74 Firemaking, 76 Constitution, 64 Agility.",
        ["What are you all doing here?"] = "¿Qué están haciendo todos aquí?",
        ["Top secret, my friend. But perhaps when you're more experienced you could help us."] = "Alto secreto, amigo mío. Pero quizás cuando tengas más experiencia puedas ayudarnos.",
        ["I see."] = "Ya veo.",
        ["Good to see you again, Player."] = "Me alegro de verte de nuevo, Player.",
        ["You too, Isis. How are you enjoying the circus?"] = "Tú también, Isis. ¿Cómo estás disfrutando del circo?",
        ["Circus? Oh! I thought this was Zanaris, what with the fairies... Well, that would explain a lot!"] = "¿Circo? ¡Oh! Pensé que esto era Zanaris, lo de las hadas... Bueno, ¡eso explicaría muchas cosas!",
    },
    ["Islwyn"] = {
        ["Hello there."] = "Hola.",
        ["Leave me be, I have no time for easterners, now be gone."] = "Déjame en paz, no tengo tiempo para los orientales, ahora vete.",
        ["Hello again."] = "Hola de nuevo.",
        ["Ah, good to see you back. Are you after another bow or one of my shields?"] = "Ah, me alegro de verte de regreso. ¿Buscas otro arco o uno de mis escudos?",
        ["Ah, good to see you back. Are you after another shield or one of my bows?"] = "Ah, me alegro de verte de regreso. ¿Buscas otro escudo o uno de mis arcos?",
        ["Choose an option:"] = "Elige una opción:",
        ["One of your bows, please."] = "Uno de tus arcos, por favor.",
        ["They're 1,000,000 coins each for new ones."] = "Son 1.000.000 coins cada uno para los nuevos.",
        ["Select an option"] = "Selecciona una opción",
        ["Pay 1,000,000 coins?"] = "¿Pagar 1.000.000 coins?",
        ["Here's 1,000,000 coins."] = "Aquí hay 1.000.000 coins.",
        ["You hand over 1,000,000 coins and get a crystal bow in return."] = "Entregas 1.000.000 coins y recibes a cambio un lazo de cristal.",
        ["Good hunting."] = "Buena caza.",
        ["Thanks... goodbye."] = "Gracias... adiós.",
        ["Sorry but I don't have that much."] = "Lo siento, pero no tengo tanto.",
        ["You can not afford that."] = "No puedes permitirte eso.",
        ["Well sorry, but I can't let it go for anything less."] = "Bueno, lo siento, pero no puedo dejarlo pasar por menos.",
        ["Oh well... see you later."] = "Oh, bueno... hasta luego.",
        ["No, thank you."] = "No, gracias.",
        ["I'd like to buy a shield."] = "Me gustaría comprar un escudo.",
        ["You hand over 1,000,000 coins and get a crystal ward in return."] = "Entregas 1.000.000 coins y obtienes a cambio una protección de cristal.",
        ["Look after yourself."] = "Cuídate.",
        ["Thank you... good bye."] = "Gracias... adiós.",
        ["Oh well... never mind then."] = "Oh, bueno... no importa entonces.",
        ["No, I'm just passing by."] = "No, sólo estoy de paso.",
        ["Well it is good to see you again...<br> Eluned tells me that Arianwyn is looking for you. Perhaps she knows why."] = "Bueno, que bueno verte de nuevo...<br> Eluned me dice que Arianwyn te está buscando. Quizás ella sepa por qué.",
        ["Well it's good to see you again. I hope all is going well for you?"] = "Bueno, es bueno verte de nuevo. Espero que todo te vaya bien?",
        ["As well as can be expected."] = "Tan bien como se puede esperar.",
        ["You should be Lord Cadarn, not Arianwyn."] = "Deberías ser Lord Cadarn, no Arianwyn.",
        ["Why? What have I done that would merit such a great honour?"] = "¿Por qué? ¿Qué he hecho yo para merecer tan gran honor?",
        ["But you're the grandson of Queen Glarial...it's your birthright."] = "Pero eres nieto de la Reina Glarial... es tu derecho de nacimiento.",
        ["You are quick to assume that elves share your customs. My blood grants me no special privilege. How could I be trusted in a position of power, if I have not proven myself to be a wise leader? If King Lathas had not inherited a throne, it's likely your lands to the east would have been spared much sorrow."] = "Rápidamente asumes que los elfos comparten tus costumbres. Mi sangre no me concede ningún privilegio especial. ¿Cómo podrían confiar en mí en una posición de poder si no he demostrado ser un líder sabio? Si King Lathas no hubiera heredado un trono, es probable que tus tierras del este se hubieran ahorrado muchas penas.",
        ["I am surprised you showed him mercy."] = "Me sorprende que le hayas mostrado misericordia.",
        ["I feel that humans put too much power in the hands of monarchs. Presumably you agree, king slayer."] = "Siento que los humanos ponen demasiado poder en manos de los monarcas. Presumiblemente estás de acuerdo, King Slayer.",
        ["Arianwyn has proven remarkably suited to lordship. He fought against the tyranny of Lord Iorwerth and, with no small help from you, led our people back to Prifddinas. I am proud of Lord Cadarn's achievement, and he has earned my respect."] = "Arianwyn ha demostrado ser notablemente apto para el señorío. Luchó contra la tiranía de Lord Iorwerth y, con no poca ayuda de su parte, llevó a nuestra gente de regreso a Prifddinas. Estoy orgulloso del logro de Lord Cadarn y se ha ganado mi respeto.",
        ["Hello Islwyn."] = "Hola Islwyn.",
        ["Well met Player."] = "Bien conocido Player.",
        ["Where's Eluned? Isn't she normally here?"] = "¿Dónde está Eluned? ¿No está ella normalmente aquí?",
        ["The letter should cover everything."] = "La carta debe cubrir todo.",
        ["Yes ... she wanted me to give you this. It explains everything."] = "Sí... ella quería que te diera esto. Lo explica todo.",
        ["[Islwyn hands you a letter from Eluned.]"] = "[Islwyn te entrega una carta de Eluned.]",
        ["Prifddinas is quite the sight. It certainly lives up to expectations."] = "Prifddinas es todo un espectáculo. Sin duda está a la altura de las expectativas.",
        ["Have you spoken to your grandfather yet?"] = "¿Ya has hablado con tu abuelo?",
        ["No … not yet… I'm trying to work out what to say."] = "No... todavía no... Estoy tratando de decidir qué decir.",
        ["He probably feels the same maybe you should … er … both fail to talk together?"] = "Probablemente él siente lo mismo, tal vez deberías... eh... ¿ambos no logran hablar juntos?",
        ["That … yeah … that really didn’t make much sense."] = "Eso... sí... eso realmente no tenía mucho sentido.",
        ["Indeed not … so …crystal singing?"] = "De hecho, no... entonces... ¿canto de cristal?",
        ["Show me a crystal seed or crystal item, and I'll see what I can do with it."] = "Muéstrame una semilla de cristal o un objeto de cristal y veré qué puedo hacer con él.",
        ["Sorry, I can't do anything with attuned crystals. They're beyond my ability."] = "Lo siento, no puedo hacer nada con cristales sintonizados. Están más allá de mi capacidad.",
        ["Oh, that teleport crystal is still enchanted."] = "Oh, ese cristal de teletransporte todavía está encantado.",
        ["I've never seen a crystal tool like that before! I didn't think it was even possible to..."] = "¡Nunca antes había visto una herramienta de cristal como esa! Ni siquiera pensé que fuera posible...",
        ["This is Lady Ithell's doing, isn't it?"] = "Esto es obra de Lady Ithell, ¿no?",
        ["The harmonic stresses inflicted on this instrument are painful to my ears. I'm surprised it hasn't shattered. Keep it away from me."] = "Las tensiones armónicas infligidas a este instrumento son dolorosas para mis oídos. Me sorprende que no se haya hecho añicos. Mantenlo alejado de mí.",
        ["Add 8 charges to one teleport seed for 400 coins?"] = "¿Agregar 8 cargas a una semilla de teletransporte por 400 coins?",
        ["Cancel"] = "Cancelar",
        ["OK"] = "bien",
        ["Add 8 charges to [number] teleport seeds for [number] coins?"] = "¿Agregar 8 cargas a las semillas de teletransporte [número] para [número] coins?",
        ["This item is fully charged."] = "Este artículo está completamente cargado.",
        ["RECHARGE"] = "RECARGAR",
        ["Recharge item for [number] coins."] = "Artículo de recarga para [número] coins.",
        ["You don't have enough coins to cover that cost, sorry."] = "No tienes suficiente coins para cubrir ese costo, lo siento.",
        ["[number] coins have been removed from your money pouch."] = "[número] coins se han eliminado de su bolsa de dinero.",
        ["Revert this item to seed (lose all charges)."] = "Revierta este artículo a semilla (pierde todos los cargos).",
        ["REVERT"] = "REVERTIR",
    },
    ["Isma'il the Kebab seller"] = {
        ["Hello."] = "Hola.",
        ["Hello. What can I do for you?"] = "Hola. ¿Qué puedo hacer por ti?",
        ["I don't know, what can you do for me?"] = "No sé, ¿qué puedes hacer por mí?",
        ["Well, that depends."] = "Bueno, eso depende.",
        ["Depends on what?"] = "¿Depende de qué?",
        ["It depends on whether you like kebabs or not."] = "Depende de si te gustan los kebabs o no.",
        ["Why is that?"] = "¿Por qué?",
        ["Seeing as I'm in the kebab construction industry, I mainly help people in need of a kebab."] = "Dado que estoy en la industria de la construcción de kebab, principalmente ayudo a las personas que necesitan un kebab.",
        ["Well then, what kind of kebabs do you, er, construct?"] = "Bueno, entonces, ¿qué tipo de kebabs construyes?",
        ["I offer two different types of kebabs: the standard run-of-the-mill kebab seen throughout Gielinor and enjoyed by many an intoxicated dwarf, and my speciality, the extra-hot kebab. So which shall it be?"] = "Ofrezco dos tipos diferentes de kebabs: el kebab común y corriente que se ve en Gielinor y que disfrutan muchos enanos ebrios, y mi especialidad, el kebab extra picante. Entonces ¿cuál será?",
        ["Or are my services even required?"] = "¿O incluso se requieren mis servicios?",
        ["Select an Option"] = "Selecciona una opción",
        ["I want a kebab, please."] = "Quiero un kebab, por favor.",
        ["That will be three gold coins please."] = "Serán tres gold coins, por favor.",
        ["I seem to have not brought enough money with me. Sorry."] = "Parece que no he traído suficiente dinero. Lo siento.",
        ["You can not afford that."] = "No puedes permitirte eso.",
        ["Here you go."] = "Aquí tienes.",
        ["Thanks."] = "Gracias.",
        ["Is there anything else I can do for you?"] = "¿Hay algo más que pueda hacer por ti?",
        ["Yes, thanks."] = "Sí, gracias.",
        ["No thanks, I'm good."] = "No, gracias, estoy bien.",
        ["Come back soon, I could do with a few more customers."] = "Vuelve pronto, me vendrían bien algunos clientes más.",
        ["Could I have an extra-hot kebab please?"] = "¿Podría darme un kebab extra caliente, por favor?",
        ["Could I have one of those crazy hot kebabs of yours."] = "¿Podría darme uno de esos locos kebabs calientes tuyos?",
        ["A super kebab it is so. Be careful, they really are as hot as they're made out to be."] = "Un súper kebab, así es. Tenga cuidado, realmente son tan calientes como parecen.",
        ["Sure, sure."] = "Claro, claro.",
        ["Would you sell me that bottle of special kebab sauce?"] = "¿Me venderías esa botella de salsa especial para kebab?",
        ["Well, that depends on what you have in mind."] = "Bueno, eso depende de lo que tengas en mente.",
        ["Set yourself at ease, I have no intention of setting up a rival kebab shop."] = "Tranquilízate, no tengo intención de montar una tienda de kebab rival.",
        ["Well then, what do you want it for?"] = "Pues bien, ¿para qué lo quieres?",
        ["I don't know, but I think I could have a little bit of fun with it."] = "No lo sé, pero creo que podría divertirme un poco con ello.",
        ["You're not going to put it in Jalal the Drunk's drink, are you? That's what happened the last time I gave someone the sauce."] = "No lo vas a poner en la bebida de Jalal the Drunk, ¿verdad? Eso es lo que pasó la última vez que le di la salsa a alguien.",
        ["No, that would be a bit cliché. I think I'll come up with something more original."] = "No, eso sería un poco cliché. Creo que se me ocurrirá algo más original.",
        ["Just be careful with it, it's potent enough to give a camel the runs."] = "Solo ten cuidado con él, es lo suficientemente potente como para hacer correr a un camello.",
        ["Thank you very much."] = "Muchas gracias.",
        ["I don't think I will give you it, for the simple fact that you already have one sticking out of your bag. I have to run a business here."] = "No creo que te lo regale, por el simple hecho de que ya tienes uno sobresaliendo de tu bolso. Tengo que administrar un negocio aquí.",
        ["Didn't I just give you a bottle of this already?"] = "¿No te acabo de dar ya una botella de esto?",
        ["You might have. Any chance of another?"] = "Es posible que sí. ¿Alguna posibilidad de otro?",
        ["I'm trying to run a business here, not a charity."] = "Estoy tratando de administrar un negocio aquí, no una organización benéfica.",
        ["What is the difference between the standard and the extra-hot kebab?"] = "¿Cuál es la diferencia entre el kebab estándar y el extra picante?",
        ["If I told you that I would have to kill you. Kebab sales is a cut-throat industry. The extra-hot kebab gives me the competitive edge on the rest and if I were to divulge my secrets to every passing adventurer, well it would soon disappear."] = "Si te dijera eso, tendría que matarte. La venta de kebab es una industria feroz. El kebab extra picante me da una ventaja competitiva sobre el resto y si tuviera que divulgar mis secretos a cada aventurero que pasa, pronto desaparecería.",
        ["So there's no difference except the sauce you use then!"] = "¡Así que no hay diferencia excepto la salsa que usas entonces!",
        ["Shh! Keep your voice down. You should have told me you were from the union."] = "¡Shh! Mantén la voz baja. Deberías haberme dicho que eras del sindicato.",
        ["Listen I've got to run. I'll catch you later."] = "Escucha, tengo que correr. Te veré más tarde.",
        ["Could I have an extra-hot kebab?"] = "¿Me podría dar un kebab extra caliente?",
        ["I need some information."] = "Necesito información.",
        ["If information is what you need, there are many better people to ask than myself who could help you. One of the town's street urchins or perhaps the local drunk. I may be many things to many different people, but a gossip I am not."] = "Si lo que necesita es información, hay muchas personas mejores que yo para pedírsela y que podrían ayudarle. Uno de los pilluelos callejeros de la ciudad o quizás el borracho local. Puede que sea muchas cosas para muchas personas diferentes, pero no soy un chismoso.",
    },
    ["Ivan (Summer Skill Off)"] = {
        ["*(The following is seen every 60 seconds:)*"] = "*(Lo siguiente se ve cada 60 segundos:)*",
        ["Can I get sunspear req here?"] = "¿Puedo conseguir el requisito de Lanza del Sol aquí?",
    },
    ["Ivan"] = {
        ["*(Before River of Blood:)*"] = "*(Antes de Río de Sangre:)*",
        ["Hey it's the hero! Wow, you're amazing! How on earth did you manage to tackle those two juvinates and Gadderanks? And the town is lovely - you've done a great job!"] = "¡Oye, es el héroe! ¡Guau, eres increíble! ¿Cómo diablos lograste enfrentarte a esos dos juvinates y Gadderanks? Y la ciudad es preciosa. ¡Has hecho un gran trabajo!",
        ["*(After River of Blood:)*"] = "*(Después de Río de Sangre :)*",
        ["Hey it's the hero! Wow, you're amazing! How did you manage to return all the villagers? Things feel so much safer around here now too - great job!"] = "¡Oye, es el héroe! ¡Guau, eres increíble! ¿Cómo conseguiste devolver a todos los aldeanos? Ahora las cosas también se sienten mucho más seguras por aquí: ¡excelente trabajo!",
        ["You're more than welcome."] = "De nada.",
        ["Select an option"] = "Selecciona una opción",
        ["What do you do here?"] = "¿Qué haces aquí?",
        ["I'm Ivan. I may be just a kid, but I'll duff you in! You don't look that tough to me!"] = "Soy Ivan. Puede que sea sólo un niño, ¡pero te dejaré en paz! ¡No me pareces tan duro!",
        ["How do you like your town?"] = "¿Qué te parece tu ciudad?",
        ["It's just perfect, thanks so much for your efforts."] = "Es simplemente perfecto, muchas gracias por tus esfuerzos.",
        ["What's happening around here?"] = "¿Qué está pasando por aquí?",
        ["Oh, not much really, we're all still hiding from the vampyres and eking out a living from this terrible place, hopefully soon we'll be strong enough to make the journey to the temple on the Salve."] = "Oh, no mucho en realidad, todos todavía nos estamos escondiendo del vampyres y ganándonos la vida a duras penas en este terrible lugar, con suerte pronto seremos lo suficientemente fuertes para hacer el viaje al templo en la Salve.",
        ["Oh, not much really, we're all just trying to eke out a living in this place. Some of us still want to head for the Salve and into Misthalin, but honestly, it's not so bad here anymore...in spite of how it might look."] = "Oh, no mucho en realidad, todos estamos tratando de ganarnos la vida a duras penas en este lugar. Algunos de nosotros todavía queremos dirigirnos a la Salve y a Misthalin, pero, sinceramente, ya no está tan mal aquí... a pesar de cómo pueda parecer.",
        ["Is there anything I can do to help out?"] = "¿Hay algo que pueda hacer para ayudar?",
        ["Not as far as I know, we have some basic amenities now which is so very useful, we're all incredibly grateful to you. I've never really seen or known a hero before, so I have nothing to compare one to, but I suspect in most people's judgement, you would be one! I for one am very pleased to have met you."] = "No que yo sepa, ahora contamos con algunos servicios básicos que son muy útiles y todos te estamos increíblemente agradecidos. Nunca antes había visto o conocido a un héroe, así que no tengo nada con qué compararlo, pero sospecho que, a juicio de la mayoría de la gente, ¡tú serías uno! Por mi parte, estoy muy contento de haberte conocido.",
        ["Okay, thanks."] = "Está bien, gracias.",
    },
    ["Ivan (The Beach)"] = {
        ["[The body builders are too busy working out to talk. They gesture towards the podiums offering you the chance to join them.]"] = "[Los culturistas están demasiado ocupados haciendo ejercicio para hablar. Hacen gestos hacia los podios ofreciéndote la oportunidad de unirte a ellos.]",
    },
    ["Ivan Strom"] = {
        ["Wolfbane dagger"] = "Lobo dagger",
        ["[You reclaim the wolfbane dagger from Ivan.]"] = "[Recuperas el azote de lobos dagger de Ivan.]",
        ["Tome of XP"] = "Tomo de XP",
        ["I see you've lost the tome King Roald gave you. I have it here!"] = "Veo que has perdido el tomo que te dio King Roald. ¡Lo tengo aquí!",
        ["There you go. Enjoy it!"] = "Ahí lo tienes. ¡Disfrútala!",
        ["A Taste of Hope"] = "Un sabor de esperanza",
        ["I've found the 'A Taste of Hope' book you dropped. Would you like it back?"] = "Encontré el libro 'A Taste of Hope' que dejaste caer. ¿Te gustaría recuperarlo?",
        ["Yes."] = "Sí.",
        ["Sunspear, the sword"] = "Lanza del sol, la espada",
        ["I've found the Sunspear sword. I'm happy to return it to you, but, well, we could use some money to help renovate Paterdomus."] = "Encontré la espada Sunspear. Me alegrará devolvértelo, pero bueno, nos vendría bien algo de dinero para ayudar a renovar Paterdomus.",
        ["Sunspear, the reformed spear"] = "Lanza del Sol, la lanza reformada",
        ["Queen Efaritay asked me to look after the Sunspear for you. I'm happy to return it to you, but, well, we could use some money to help renovate Paterdomus."] = "La reina Efaritay me pidió que cuidara la Lanza del Sol por ti. Me alegrará devolvértelo, pero bueno, nos vendría bien algo de dinero para ayudar a renovar Paterdomus.",
    },
    ["Ivar (Artisans' Workshop)"] = {
        ["Good day. Are you here about the starlight ore?"] = "Buenos días. ¿Estás aquí por el mineral Starlight?",
        ["What are you talking about?"] = "¿De qué estás hablando?",
        ["The other night I was working away when I saw something in the sky: a whole storm of shooting stars, flying through the sky."] = "La otra noche estaba trabajando cuando vi algo en el cielo: toda una tormenta de estrellas fugaces, volando por el cielo.",
        ["The next day I went mining and found a new type of ore that I've never seen before."] = "Al día siguiente fui a minar y encontré un nuevo tipo de mineral que nunca antes había visto.",
        ["Don't you see? They came from up there!"] = "¿No lo ves? ¡Vinieron de allá arriba!",
        ["I had some blueprints made for some new weapon designs, but I was attacked. In my rush to escape, I dropped them."] = "Hice algunos planos para algunos diseños de armas nuevos, pero fui atacado. En mi prisa por escapar, los dejé caer.",
        ["If you can get your hands on some blueprints and find enough ore, return to me and we can look into making some weapons."] = "Si puedes conseguir algunos planos y encontrar suficiente mineral, regresa conmigo y podremos investigar la posibilidad de fabricar algunas armas.",
        ["If that doesn't interest you, I would be willing to trade any materials for some personal training in mining or smithing."] = "Si eso no te interesa, estaría dispuesto a intercambiar cualquier material por algún entrenamiento personal en minería o herrería.",
        ["What do I need to make these weapons?"] = "¿Qué necesito para fabricar estas armas?",
        ["First, we need enough ore to smith these weapons. This starlight ore seems delicate to the touch, so we'll need 10,000 ore to get a finished weapon out of it."] = "Primero, necesitamos suficiente mineral para fabricar estas armas. Este mineral de luz estelar parece delicado al tacto, por lo que necesitaremos 10 000 minerales para obtener un arma terminada.",
        ["Next, we'll need some blueprints. I dropped them when I was attacked, but they must be somewhere else. Kill enough monsters and hopefully you'll find them."] = "A continuación, necesitaremos algunos planos. Los dejé caer cuando me atacaron, pero deben estar en otro lugar. Mata suficientes monstruos y con suerte los encontrarás.",
        ["That should be enough for us to make a starfire weapon, but I hear there are also some starborn diamonds that fell alongside the ore. If you find one of those, we can add it to create a starfury weapon."] = "Eso debería ser suficiente para que podamos hacer un arma de fuego estelar, pero escuché que también hay algunos diamantes nacidos de estrellas que cayeron junto al mineral. Si encuentra uno de esos, podemos agregarlo para crear un arma de furia estelar.",
        ["We'll have to be quick though. It looks like the ore is deteriorating in quality already."] = "Aunque tendremos que ser rápidos. Parece que la calidad del mineral ya se está deteriorando.",
        ["Goodbye."] = "Adiós.",
        ["Farewell. Remember, if you find any starlight ore bring it to me."] = "Adiós. Recuerda, si encuentras algún mineral de luz estelar, tráemelo.",
        ["I've found some starlight ore. *(If having at least 10,000 starlight ores)*"] = "Encontré un mineral de luz estelar. *(Si tienes al menos 10,000 minerales de luz estelar)*",
        ["We have enough resources to make a weapon. What would you like to make?"] = "Tenemos suficientes recursos para fabricar un arma. ¿Qué te gustaría hacer?",
        ["There we go, all made!"] = "¡Ahí vamos, todo hecho!",
        ["Starfire sword."] = "Espada de fuego estelar.",
        ["Starfire bow."] = "Arco de fuego estelar.",
        ["Cancel."] = "Cancelar.",
        ["*(Closes chatbox)*"] = "*(Cierra el chat)*",
        ["I've found some starfire blueprints."] = "Encontré algunos planos de Starfire.",
        ["That's a good start but you need 10,000 ore to make a starfire weapon."] = "Es un buen comienzo, pero necesitas 10 000 minerales para fabricar un arma de fuego estelar.",
        ["I've found a starborn diamond. *(If having a diamond but no starfire weapons with you)*"] = "Encontré un diamante nacido de una estrella. *(Si tienes un diamante pero no armas de fuego estelar contigo)*",
        ["That's a good start but you need to have a complete starfire weapon before we can make a starfury weapon."] = "Ese es un buen comienzo, pero necesitas tener un arma de fuego estelar completa antes de que podamos crear un arma de furia estelar.",
        ["I've found a starborn diamond. *(If having a diamond and at least one starfire weapon with you)*"] = "Encontré un diamante nacido de una estrella. *(Si tienes un diamante y al menos un arma de fuego contigo)*",
        ["Starfury staff."] = "Furia Estelar staff.",
        ["Starfury sword."] = "Espada Furia Estelar.",
        ["Starfury bow."] = "Arco de furia estelar.",
        ["I have some ore I'd like to trade."] = "Tengo algo de mineral que me gustaría intercambiar.",
        ["Are you sure you wish to trade your ore with me? I will take of it as much as I can in your inventory and - in exchange - give you some mining or smithing training."] = "¿Estás seguro de que deseas intercambiar tu mineral conmigo? Tomaré todo lo que pueda en tu inventario y, a cambio, te daré algo de entrenamiento en minería o herrería.",
        ["Yes, I'd like some mining training."] = "Sí, me gustaría algo de formación en minería.",
        ["Pleasure doing business with you."] = "Un placer hacer negocios con usted.",
        ["Yes, I'd like some smithing training."] = "Sí, me gustaría algo de formación en herrería.",
        ["No, I've changed my mind."] = "No, he cambiado de opinión.",
        ["Work, work."] = "Trabajo, trabajo.",
        ["*If the player has leftover ore in inventory.*"] = "*Si el player tiene mineral sobrante en el inventario.*",
        ["Ivar doesn't seem interested in starlight ore right now."] = "Ivar no parece interesado en el mineral Starlight en este momento.",
    },
